window.lessonsHSK3=[{"num":10,"emoji":"📚","han":"你明天再把书还给我","pinyin":"Nǐ míngtiān zài bǎ shū huán gěi wǒ","translation":"Ngày mai em trả lại sách cho cô nhé","theme":"Học tập & câu chữ 把","vocab":[{"emoji":"🔢","word":"数学","pinyin":"shùxué","pos":"Danh từ","meaning":"môn Toán","example":"数学很难。","examplePinyin":"Shùxué hěn nán.","exampleVi":"Môn Toán rất khó."},{"emoji":"🧐","word":"认真","pinyin":"rènzhēn","pos":"Tính từ","meaning":"chăm chỉ, nghiêm túc","example":"他学习很认真。","examplePinyin":"Tā xuéxí hěn rènzhēn.","exampleVi":"Anh ấy học rất chăm chỉ."},{"emoji":"📓","word":"笔记","pinyin":"bǐjì","pos":"Danh từ","meaning":"ghi chép","example":"我记了很多笔记。","examplePinyin":"Wǒ jì le hěn duō bǐjì.","exampleVi":"Tôi ghi chép rất nhiều."},{"emoji":"🔍","word":"清楚","pinyin":"qīngchu","pos":"Tính từ","meaning":"rõ ràng","example":"老师讲得很清楚。","examplePinyin":"Lǎoshī jiǎng de hěn qīngchu.","exampleVi":"Thầy giảng rất rõ ràng."},{"emoji":"⬛","word":"黑板","pinyin":"hēibǎn","pos":"Danh từ","meaning":"bảng đen","example":"老师在黑板上写字。","examplePinyin":"Lǎoshī zài hēibǎn shang xiě zì.","exampleVi":"Thầy viết chữ lên bảng."},{"emoji":"✋","word":"把","pinyin":"bǎ","pos":"Giới từ","meaning":"(đưa tân ngữ lên trước động từ)","example":"把书放在桌子上。","examplePinyin":"Bǎ shū fàng zài zhuōzi shang.","exampleVi":"Đặt sách lên bàn."},{"emoji":"📚","word":"作业","pinyin":"zuòyè","pos":"Danh từ","meaning":"bài tập về nhà","example":"今天的作业很多。","examplePinyin":"Jīntiān de zuòyè hěn duō.","exampleVi":"Bài tập hôm nay rất nhiều."},{"emoji":"🔁","word":"遍","pinyin":"biàn","pos":"Lượng từ","meaning":"lượt","example":"这本书我看了两遍。","examplePinyin":"Zhè běn shū wǒ kàn le liǎng biàn.","exampleVi":"Cuốn sách này tôi đọc hai lượt."},{"emoji":"📈","word":"提高","pinyin":"tígāo","pos":"Động từ","meaning":"nâng cao","example":"我想提高中文水平。","examplePinyin":"Wǒ xiǎng tígāo Zhōngwén shuǐpíng.","exampleVi":"Tôi muốn nâng cao trình độ tiếng Trung."},{"emoji":"🏛️","word":"历史","pinyin":"lìshǐ","pos":"Danh từ","meaning":"Lịch sử","example":"我喜欢历史课。","examplePinyin":"Wǒ xǐhuān lìshǐ kè.","exampleVi":"Tôi thích giờ Lịch sử."},{"emoji":"😖","word":"难","pinyin":"nán","pos":"Tính từ","meaning":"khó","example":"这个问题很难。","examplePinyin":"Zhè ge wèntí hěn nán.","exampleVi":"Câu hỏi này rất khó."},{"emoji":"📋","word":"要求","pinyin":"yāoqiú","pos":"Danh từ / Động từ","meaning":"yêu cầu","example":"老师的要求很高。","examplePinyin":"Lǎoshī de yāoqiú hěn gāo.","exampleVi":"Yêu cầu của thầy rất cao."},{"emoji":"📉","word":"差","pinyin":"chà","pos":"Tính từ","meaning":"kém","example":"他的数学比较差。","examplePinyin":"Tā de shùxué bǐjiào chà.","exampleVi":"Môn Toán của anh ấy khá kém."},{"emoji":"🔄","word":"复习","pinyin":"fùxí","pos":"Động từ","meaning":"ôn tập","example":"考试前要复习。","examplePinyin":"Kǎoshì qián yào fùxí.","exampleVi":"Trước kỳ thi phải ôn tập."},{"emoji":"🗣️","word":"外语","pinyin":"wàiyǔ","pos":"Danh từ","meaning":"ngoại ngữ","example":"他会说三门外语。","examplePinyin":"Tā huì shuō sān mén wàiyǔ.","exampleVi":"Anh ấy nói được ba ngoại ngữ."},{"emoji":"✅","word":"当然","pinyin":"dāngrán","pos":"Phó từ","meaning":"đương nhiên","example":"当然可以。","examplePinyin":"Dāngrán kěyǐ.","exampleVi":"Đương nhiên được."},{"emoji":"🤝","word":"遇到","pinyin":"yùdào","pos":"Động từ","meaning":"gặp, gặp phải","example":"我遇到了一个老朋友。","examplePinyin":"Wǒ yùdào le yí ge lǎo péngyou.","exampleVi":"Tôi gặp một người bạn cũ."},{"emoji":"🏢","word":"办公室","pinyin":"bàngōngshì","pos":"Danh từ","meaning":"văn phòng","example":"老师在办公室。","examplePinyin":"Lǎoshī zài bàngōngshì.","exampleVi":"Thầy ở văn phòng."},{"emoji":"📄","word":"页","pinyin":"yè","pos":"Lượng từ","meaning":"trang (sách)","example":"请看第十页。","examplePinyin":"Qǐng kàn dì shí yè.","exampleVi":"Xin xem trang 10."},{"emoji":"💬","word":"对话","pinyin":"duìhuà","pos":"Danh từ","meaning":"hội thoại","example":"我们练习对话。","examplePinyin":"Wǒmen liànxí duìhuà.","exampleVi":"Chúng tôi luyện hội thoại."},{"emoji":"💡","word":"明白","pinyin":"míngbai","pos":"Động từ","meaning":"hiểu","example":"你明白了吗？","examplePinyin":"Nǐ míngbai le ma?","exampleVi":"Bạn hiểu chưa?"},{"emoji":"🎤","word":"讲","pinyin":"jiǎng","pos":"Động từ","meaning":"giảng","example":"老师在讲课。","examplePinyin":"Lǎoshī zài jiǎng kè.","exampleVi":"Thầy đang giảng bài."},{"emoji":"💭","word":"句","pinyin":"jù","pos":"Lượng từ","meaning":"câu (nói)","example":"他说了一句中文。","examplePinyin":"Tā shuō le yí jù Zhōngwén.","exampleVi":"Anh ấy nói một câu tiếng Trung."},{"emoji":"📝","word":"句子","pinyin":"jùzi","pos":"Danh từ","meaning":"câu (văn)","example":"这个句子很长。","examplePinyin":"Zhè ge jùzi hěn cháng.","exampleVi":"Câu này rất dài."},{"emoji":"🏫","word":"年级","pinyin":"niánjí","pos":"Danh từ","meaning":"khối lớp","example":"他是三年级的。","examplePinyin":"Tā shì sān niánjí de.","exampleVi":"Cậu ấy học khối 3."},{"emoji":"📅","word":"后年","pinyin":"hòunián","pos":"Danh từ","meaning":"năm sau nữa","example":"后年我毕业。","examplePinyin":"Hòunián wǒ bìyè.","exampleVi":"Năm sau nữa tôi tốt nghiệp."},{"emoji":"😐","word":"一般","pinyin":"yìbān","pos":"Tính từ","meaning":"bình thường","example":"他的成绩一般。","examplePinyin":"Tā de chéngjì yìbān.","exampleVi":"Thành tích của cậu ấy bình thường."},{"emoji":"💪","word":"努力","pinyin":"nǔlì","pos":"Động từ","meaning":"nỗ lực","example":"学习要努力。","examplePinyin":"Xuéxí yào nǔlì.","exampleVi":"Học tập phải nỗ lực."}],"summary":"Chuyện học tập ở trường — nghe giảng, ghi chép bài, mượn sách của thầy cô rồi hẹn ngày mai trả, làm bài tập và bàn về các môn học (Toán, Lịch sử).","structures":[{"han":"你明天再把书还给我","pinyin":"Nǐ míngtiān zài bǎ shū huán gěi wǒ","meaning":"Ngày mai em trả lại sách cho cô nhé.","note":"把 + 再: \"hãy làm lại việc gì vào lúc khác\""},{"han":"把作业写完","pinyin":"Bǎ zuòyè xiě wán","meaning":"Làm xong bài tập đi.","note":"把 + tân ngữ xác định + động từ + kết quả"},{"han":"在黑板上写字","pinyin":"Zài hēibǎn shang xiě zì","meaning":"Viết chữ lên bảng.","note":"在 + nơi chốn"},{"han":"再说一遍","pinyin":"Zài shuō yí biàn","meaning":"Nói lại một lượt nữa.","note":""}],"natural":["Câu \"把书还给我\" nghe rất tự nhiên — người TQ dùng 把 hằng ngày khi muốn nhấn mạnh \"xử lý\" một đồ vật cụ thể.","\"再\" trong \"明天再还\" mang nghĩa \"để mai làm\" — khác hẳn \"又\" (làm lại chuyện đã xảy ra). Dùng đúng chỗ này là bạn đã lên trình rồi đó.","Khi mượn đồ, người TQ hay thêm \"用完就还你\" (dùng xong trả ngay) cho lịch sự — học thuộc câu này rất có ích."],"grammar":[{"title":"Câu chữ 把 (1) — cơ bản","formula":"Chủ ngữ + 把 + tân ngữ (xác định) + động từ + thành phần khác","explain":"Khi muốn \"xử lý\" một đồ vật cụ thể (cất đi, đưa cho ai, làm xong…), tiếng Trung \"nhấc\" tân ngữ lên trước động từ bằng 把. Tân ngữ phải là thứ đã xác định (cuốn sách ĐÓ, bài tập ĐÓ).","examples":"我会把这些题都记在本子上。 (Wǒ huì bǎ zhè xiē tí dōu jì zài běnzi shang) — Tôi sẽ ghi tất cả những bài này vào vở.. 老师把作业本放到桌子上了。 (Lǎoshī bǎ zuòyè běn fàng dào zhuōzi shang le) — Thầy giáo đã đặt vở bài tập lên bàn rồi.. 你不能把名字写在这里。 (Nǐ bù néng bǎ míngzi xiě zài zhèli) — Bạn không được viết tên ở đây.","tip":"","error":"Sau động từ trong câu 把 PHẢI có thêm thành phần (了/补语/…). Nói \"我把书还\" là sai — phải là \"我把书还给你了\"."},{"title":"Cấu trúc 在……上 / 中 / 下","formula":"","explain":"在 không chỉ chỉ nơi chốn cụ thể, mà còn chỉ \"phạm vi trừu tượng\": 在学习上 (trong học tập), 在生活中 (trong cuộc sống), 在这一点上 (ở điểm này).","examples":"在学习上，遇到什么问题都可以问我。 (Zài xuéxí shang, yùdào shénme wèntí dōu kěyǐ wèn wǒ) — Trong học tập, gặp vấn đề gì cũng có thể hỏi tôi.. 在工作上，他总是能给我很多帮助。 (Zài gōngzuò shang, tā zǒngshì néng gěi wǒ hěn duō bāngzhù) — Trong công việc, anh ấy luôn có thể giúp tôi rất nhiều.. 在比赛中，他得分最高。 (Zài bǐsài zhōng, tā défēn zuì gāo) — Trong trận đấu, anh ấy ghi điểm cao nhất.. 在假期中，我认识了几个新朋友。 (Zài jiàqī zhōng, wǒ rènshi le jǐ ge xīn péngyou) — Trong kỳ nghỉ, tôi đã quen vài người bạn mới.. 在她的影响下，我开始喜欢拍照。 (Zài tā de yǐngxiǎng xià, wǒ kāishǐ xǐhuan pāizhào) — Dưới ảnh hưởng của cô ấy, tôi bắt đầu thích chụp ảnh.. 在老师的帮助下，我的成绩提高很快。 (Zài lǎoshī de bāngzhù xià, wǒ de chéngjī tígāo hěn kuài) — Nhờ sự giúp đỡ của thầy cô, thành tích của tôi tiến bộ rất nhanh.","tip":"","error":"Đừng dịch word-by-word \"trên/dưới\" — đây là cách nói phạm vi, không phải vị trí vật lý."},{"title":"Câu chữ 把 (2) — phủ định và mở rộng","formula":"","explain":"Phủ định (不/没/别) và động từ năng nguyện (想/要/可以) đứng TRƯỚC 把, không chen vào giữa.","examples":"你明天再把书还给我。 (Nǐ míngtiān zài bǎ shū huán gěi wǒ) — Ngày mai bạn hãy trả lại sách cho tôi.. 我把礼物送给她了。 (Wǒ bǎ lǐwù sòng gěi tā le) — Tôi đã tặng quà cho cô ấy rồi.. 请你把这本书带给老师。 (Qǐng nǐ bǎ zhè běn shū dài gěi lǎoshī) — Xin bạn mang cuốn sách này cho thầy giáo.","tip":"","error":"\"把不书还\" là sai — luôn là \"没把书还\"."}]},{"num":11,"emoji":"💼","han":"看来我没办法解决这个问题","pinyin":"Kànlái wǒ méi bànfǎ jiějué zhè ge wèntí","translation":"Xem ra em không thể giải quyết vấn đề này","theme":"Công sở & giải quyết vấn đề","vocab":[{"emoji":"👥","word":"会议","pinyin":"huìyì","pos":"Danh từ","meaning":"cuộc họp","example":"明天有一个会议。","examplePinyin":"Míngtiān yǒu yí ge huìyì.","exampleVi":"Ngày mai có một cuộc họp."},{"emoji":"💼","word":"经理","pinyin":"jīnglǐ","pos":"Danh từ","meaning":"giám đốc","example":"经理在开会。","examplePinyin":"Jīnglǐ zài kāihuì.","exampleVi":"Giám đốc đang họp."},{"emoji":"📅","word":"开会","pinyin":"kāihuì","pos":"Động từ","meaning":"họp","example":"我们三点开会。","examplePinyin":"Wǒmen sān diǎn kāihuì.","exampleVi":"Chúng ta họp lúc 3 giờ."},{"emoji":"📆","word":"后天","pinyin":"hòutiān","pos":"Danh từ","meaning":"ngày kia","example":"后天是星期六。","examplePinyin":"Hòutiān shì xīngqīliù.","exampleVi":"Ngày kia là thứ bảy."},{"emoji":"📍","word":"地点","pinyin":"dìdiǎn","pos":"Danh từ","meaning":"địa điểm","example":"会议的地点在哪儿？","examplePinyin":"Huìyì de dìdiǎn zài nǎr?","exampleVi":"Địa điểm họp ở đâu?"},{"emoji":"🚪","word":"室","pinyin":"shì","pos":"Danh từ","meaning":"phòng","example":"会议室在二楼。","examplePinyin":"Huìyìshì zài èr lóu.","exampleVi":"Phòng họp ở tầng 2."},{"emoji":"📤","word":"发","pinyin":"fā","pos":"Động từ","meaning":"gửi","example":"请把邮件发给我。","examplePinyin":"Qǐng bǎ yóujiàn fā gěi wǒ.","exampleVi":"Xin gửi email cho tôi."},{"emoji":"💻","word":"笔记本电脑","pinyin":"bǐjìběn diànnǎo","pos":"Danh từ","meaning":"máy tính xách tay","example":"他的笔记本电脑坏了。","examplePinyin":"Tā de bǐjìběn diànnǎo huài le.","exampleVi":"Laptop của anh ấy hỏng rồi."},{"emoji":"🔀","word":"或者","pinyin":"huòzhě","pos":"Liên từ","meaning":"hoặc","example":"喝茶或者喝咖啡？","examplePinyin":"Hē chá huòzhě hē kāfēi?","exampleVi":"Uống trà hay uống cà phê?"},{"emoji":"🔊","word":"声音","pinyin":"shēngyīn","pos":"Danh từ","meaning":"âm thanh","example":"他的声音很大。","examplePinyin":"Tā de shēngyīn hěn dà.","exampleVi":"Giọng anh ấy rất to."},{"emoji":"👀","word":"看来","pinyin":"kànlái","pos":"Động từ","meaning":"xem ra, có vẻ như","example":"看来今天要下雨。","examplePinyin":"Kànlái jīntiān yào xià yǔ.","exampleVi":"Xem ra hôm nay trời sẽ mưa."},{"emoji":"💡","word":"办法","pinyin":"bànfǎ","pos":"Danh từ","meaning":"cách, biện pháp","example":"我有一个好办法。","examplePinyin":"Wǒ yǒu yí ge hǎo bànfǎ.","exampleVi":"Tôi có một cách hay."},{"emoji":"🔧","word":"解决","pinyin":"jiějué","pos":"Động từ","meaning":"giải quyết","example":"这个问题很难解决。","examplePinyin":"Zhè ge wèntí hěn nán jiějué.","exampleVi":"Vấn đề này rất khó giải quyết."},{"emoji":"⛔","word":"只能","pinyin":"zhǐnéng","pos":"Phó từ","meaning":"chỉ có thể","example":"我只能明天去。","examplePinyin":"Wǒ zhǐnéng míngtiān qù.","exampleVi":"Tôi chỉ có thể đi ngày mai."},{"emoji":"👥","word":"别人","pinyin":"biérén","pos":"Danh từ","meaning":"người khác","example":"别拿别人的东西。","examplePinyin":"Bié ná biérén de dōngxi.","exampleVi":"Đừng lấy đồ của người khác."},{"emoji":"📝","word":"请假","pinyin":"qǐngjià","pos":"Động từ","meaning":"xin nghỉ","example":"他今天请假了。","examplePinyin":"Tā jīntiān qǐngjià le.","exampleVi":"Hôm nay anh ấy xin nghỉ."},{"emoji":"👔","word":"同事","pinyin":"tóngshì","pos":"Danh từ","meaning":"đồng nghiệp","example":"我的同事很好。","examplePinyin":"Wǒ de tóngshì hěn hǎo.","exampleVi":"Đồng nghiệp của tôi rất tốt."},{"emoji":"🏖️","word":"休假","pinyin":"xiūjià","pos":"Động từ","meaning":"nghỉ phép","example":"下个月我想休假。","examplePinyin":"Xià ge yuè wǒ xiǎng xiūjià.","exampleVi":"Tháng sau tôi muốn nghỉ phép."},{"emoji":"😨","word":"怕","pinyin":"pà","pos":"Động từ","meaning":"sợ","example":"我怕迟到。","examplePinyin":"Wǒ pà chídào.","exampleVi":"Tôi sợ đến muộn."},{"emoji":"📧","word":"邮箱","pinyin":"yóuxiāng","pos":"Danh từ","meaning":"hộp thư điện tử","example":"请发到我的邮箱。","examplePinyin":"Qǐng fā dào wǒ de yóuxiāng.","exampleVi":"Xin gửi vào hộp thư của tôi."},{"emoji":"👍","word":"愿意","pinyin":"yuànyì","pos":"Động từ năng nguyện","meaning":"sẵn lòng","example":"我愿意帮助你。","examplePinyin":"Wǒ yuànyì bāngzhù nǐ.","exampleVi":"Tôi sẵn lòng giúp bạn."},{"emoji":"🏙️","word":"城市","pinyin":"chéngshì","pos":"Danh từ","meaning":"thành phố","example":"这个城市很大。","examplePinyin":"Zhè ge chéngshì hěn dà.","exampleVi":"Thành phố này rất lớn."},{"emoji":"🚶","word":"离开","pinyin":"líkāi","pos":"Động từ","meaning":"rời khỏi","example":"他离开北京了。","examplePinyin":"Tā líkāi Běijīng le.","exampleVi":"Anh ấy đã rời Bắc Kinh."},{"emoji":"🎯","word":"机会","pinyin":"jīhuì","pos":"Danh từ","meaning":"cơ hội","example":"这是个好机会。","examplePinyin":"Zhè shì ge hǎo jīhuì.","exampleVi":"Đây là một cơ hội tốt."},{"emoji":"🏠","word":"生活","pinyin":"shēnghuó","pos":"Danh từ / Động từ","meaning":"cuộc sống","example":"这里的生活很好。","examplePinyin":"Zhèlǐ de shēnghuó hěn hǎo.","exampleVi":"Cuộc sống ở đây rất tốt."},{"emoji":"💝","word":"为","pinyin":"wèi","pos":"Giới từ","meaning":"vì","example":"为工作，他很忙。","examplePinyin":"Wèi gōngzuò, tā hěn máng.","exampleVi":"Vì công việc, anh ấy rất bận."},{"emoji":"🔀","word":"或","pinyin":"huò","pos":"Liên từ","meaning":"hoặc","example":"茶或咖啡都可以。","examplePinyin":"Chá huò kāfēi dōu kěyǐ.","exampleVi":"Trà hay cà phê đều được."},{"emoji":"👨","word":"老张","pinyin":"Lǎo Zhāng","pos":"Danh từ riêng","meaning":"Lão Trương (cách gọi đồng nghiệp họ Trương)","example":"老张是我们的同事。","examplePinyin":"Lǎo Zhāng shì wǒmen de tóngshì.","exampleVi":"Lão Trương là đồng nghiệp của chúng tôi."}],"summary":"Những cuộc trò chuyện nơi công sở — đi họp, máy tính hỏng phải nhờ đồng nghiệp giúp, xin nghỉ phép, và cân nhắc giữa công việc với cuộc sống.","structures":[{"han":"看来我没办法解决这个问题","pinyin":"Kànlái wǒ méi bànfǎ jiějué zhè ge wèntí","meaning":"Xem ra tôi không có cách giải quyết vấn đề này.","note":"看来 = xem ra + 没办法 = hết cách"},{"han":"对我来说，健康最重要","pinyin":"Duì wǒ lái shuō, jiànkāng zuì zhòngyào","meaning":"Đối với tôi, sức khỏe là quan trọng nhất.","note":"对……来说"},{"han":"你愿意帮助我吗？","pinyin":"Nǐ yuànyì bāngzhù wǒ ma?","meaning":"Bạn có sẵn lòng giúp tôi không?","note":""},{"han":"只能明天去","pinyin":"Zhǐnéng míngtiān qù","meaning":"Chỉ có thể đi ngày mai.","note":""}],"natural":["\"看来\" là từ cực kỳ thông dụng khi đưa ra phán đoán — người TQ nói \"看来要下雨了\" hằng ngày.","\"没办法\" không chỉ là \"không có cách\" mà còn mang nghĩa bất lực, đành chịu — cảm xúc rất thật trong văn nói.","Trong công sở, thay vì nói thẳng \"我不会\" (tôi không biết), người TQ hay nói uyển chuyển \"看来我没办法解决\" — vừa lịch sự vừa thật lòng."],"grammar":[{"title":"还是 vs 或者","formula":"","explain":"Cả hai đều là \"hoặc\", nhưng 还是 dùng trong CÂU HỎI lựa chọn (A还是B?), 或者 dùng trong CÂU KỂ (nói về lựa chọn chung chung).","examples":"我们用会议室的电脑还是自己的笔记本电脑？ (Wǒmen yòng huìyìshì de diànnǎo háishì zìjǐ de bǐjìběn diànnǎo?) — Chúng ta dùng máy tính của phòng họp hay máy tính xách tay của mình?. 我们今天去、明天去还是后天去？ (Wǒmen jīntiān qù, míngtiān qù háishì hòutiān qù?) — Chúng ta đi hôm nay, ngày mai hay ngày kia?. 会议室的电脑或者自己的电脑都可以。 (Huìyìshì de diànnǎo huòzhě zìjǐ de diànnǎo dōu kěyǐ) — Máy tính của phòng họp hay máy tính của mình đều được.. 你可以坐地铁或者打车去学校。 (Nǐ kěyǐ zuò dìtiě huòzhě dǎchē qù xuéxiào) — Bạn có thể đi tàu điện ngầm hoặc bắt taxi đến trường.","tip":"Thấy dấu \"?\" thì dùng 还是, câu kể thì 或者.","error":"\"你喝茶或者喝咖啡吗?\" là sai — câu hỏi lựa chọn phải dùng 还是."},{"title":"Cụm cố định 看来","formula":"看来 + phán đoán","explain":"\"Xem ra / có vẻ như\" — đưa ra kết luận dựa trên những gì quan sát được. Đứng đầu câu, sau đó là cả một mệnh đề.","examples":"看来我没办法解决这个问题。 (Kànlái wǒ méi bànfǎ jiějué zhège wèntí) — Xem ra tôi không có cách nào giải quyết vấn đề này.. 这么晚了，看来他今天不会来了。 (Zhème wǎn le, kànlái tā jīntiān bù huì lái le) — Muộn thế này rồi, xem ra hôm nay anh ấy sẽ không đến.. 电梯坏了，看来咱们只能走下去了。 (Diàntī huài le, kànlái zánmen zhǐ néng zǒu xiàqù le) — Thang máy hỏng rồi, xem ra chúng ta chỉ có thể đi bộ xuống thôi.","tip":"","error":"看来 không đi với tân ngữ trực tiếp — không nói \"看来雨\"."},{"title":"Câu chữ 把 (3) — nâng cao","formula":"","explain":"Ôn lại 把 với các bổ ngữ phức tạp hơn: 把 + O + V + 给/到/在 + người/nơi. Nhớ: phủ định và năng nguyện đứng TRƯỚC 把.","examples":"我跟您一起把这些工作做完。 (Wǒ gēn nín yīqǐ bǎ zhè xiē gōngzuò zuò wán) — Tôi cùng anh/chị làm xong những công việc này.. 妈妈把衣服洗干净了。 (Māma bǎ yīfu xǐ gānjìng le) — Mẹ đã giặt sạch quần áo rồi.. 他还没把笔记本电脑接好呢。 (Tā hái méi bǎ bǐjìběn diànnǎo jiē hǎo ne) — Anh ấy vẫn chưa nối xong máy tính xách tay.","tip":"","error":"Động từ trong câu 把 phải là động từ \"xử lý\" được (không dùng 是/有/在/喜欢…)."},{"title":"对……来说","formula":"对 + người + 来说, + nhận xét","explain":"\"Đối với … mà nói\" — nêu quan điểm đứng từ góc nhìn của ai đó.","examples":"对我来说，生活也很重要，我不愿意为工作或学习离开家人。 (Duì wǒ lái shuō, shēnghuó yě hěn zhòngyào, wǒ bù yuànyì wèi gōngzuò huò xuéxí líkāi jiārén) — Đối với tôi, cuộc sống cũng rất quan trọng, tôi không muốn vì công việc hay học tập mà rời xa gia đình.. 对她来说，学习汉语很有意思。 (Duì tā lái shuō, xuéxí Hànyǔ hěn yǒu yìsi) — Đối với cô ấy, học tiếng Trung rất thú vị.. 对孩子来说，玩也是一种学习。 (Duì háizi lái shuō, wán yě shì yī zhǒng xuéxí) — Đối với trẻ con, chơi cũng là một cách học.","tip":"","error":"Sau 来说 phải là cả một câu nhận xét, không phải một danh từ cụt lủn."}]},{"num":12,"emoji":"🌦️","han":"这个季节天气变化很快","pinyin":"Zhè ge jìjié tiānqì biànhuà hěn kuài","translation":"Thời tiết mùa này thay đổi rất nhanh","theme":"Thời tiết & bốn mùa","vocab":[{"emoji":"🛣️","word":"街","pinyin":"jiē","pos":"Danh từ","meaning":"phố, đường","example":"这条街很热闹。","examplePinyin":"Zhè tiáo jiē hěn rènao.","exampleVi":"Con phố này rất nhộn nhịp."},{"emoji":"🌸","word":"开花","pinyin":"kāihuā","pos":"Động từ","meaning":"nở hoa","example":"春天花开了。","examplePinyin":"Chūntiān huā kāi le.","exampleVi":"Mùa xuân hoa nở."},{"emoji":"🌳","word":"公园","pinyin":"gōngyuán","pos":"Danh từ","meaning":"công viên","example":"公园里有很多花。","examplePinyin":"Gōngyuán li yǒu hěn duō huā.","exampleVi":"Trong công viên có nhiều hoa."},{"emoji":"⛵","word":"船","pinyin":"chuán","pos":"Danh từ","meaning":"thuyền","example":"湖上有一只船。","examplePinyin":"Hú shang yǒu yì zhī chuán.","exampleVi":"Trên hồ có một chiếc thuyền."},{"emoji":"💼","word":"工作日","pinyin":"gōngzuòrì","pos":"Danh từ","meaning":"ngày làm việc","example":"工作日我很忙。","examplePinyin":"Gōngzuòrì wǒ hěn máng.","exampleVi":"Ngày làm việc tôi rất bận."},{"emoji":"📍","word":"地方","pinyin":"dìfang","pos":"Danh từ","meaning":"nơi, địa điểm","example":"这是个好地方。","examplePinyin":"Zhè shì ge hǎo dìfang.","exampleVi":"Đây là một nơi tốt."},{"emoji":"🕐","word":"刚才","pinyin":"gāngcái","pos":"Danh từ","meaning":"vừa rồi, lúc nãy","example":"刚才下雨了。","examplePinyin":"Gāngcái xià yǔ le.","exampleVi":"Vừa rồi trời mưa."},{"emoji":"💨","word":"刮","pinyin":"guā","pos":"Động từ","meaning":"(gió) thổi","example":"外面刮大风了。","examplePinyin":"Wàimiàn guā dà fēng le.","exampleVi":"Bên ngoài nổi gió to."},{"emoji":"🌬️","word":"风","pinyin":"fēng","pos":"Danh từ","meaning":"gió","example":"今天风很大。","examplePinyin":"Jīntiān fēng hěn dà.","exampleVi":"Hôm nay gió rất to."},{"emoji":"📺","word":"新闻","pinyin":"xīnwén","pos":"Danh từ","meaning":"tin tức","example":"我看了新闻。","examplePinyin":"Wǒ kàn le xīnwén.","exampleVi":"Tôi đã xem tin tức."},{"emoji":"☂️","word":"伞","pinyin":"sǎn","pos":"Danh từ","meaning":"ô, dù","example":"下雨了，带把伞。","examplePinyin":"Xià yǔ le, dài bǎ sǎn.","exampleVi":"Trời mưa rồi, mang theo ô đi."},{"emoji":"🤲","word":"借","pinyin":"jiè","pos":"Động từ","meaning":"mượn","example":"我想借你的伞。","examplePinyin":"Wǒ xiǎng jiè nǐ de sǎn.","exampleVi":"Tôi muốn mượn ô của bạn."},{"emoji":"☂️","word":"把","pinyin":"bǎ","pos":"Lượng từ","meaning":"cái (đồ có tay cầm)","example":"一把伞","examplePinyin":"Yì bǎ sǎn.","exampleVi":"một cái ô."},{"emoji":"🧥","word":"雨衣","pinyin":"yǔyī","pos":"Danh từ","meaning":"áo mưa","example":"下雨穿雨衣。","examplePinyin":"Xià yǔ chuān yǔyī.","exampleVi":"Trời mưa thì mặc áo mưa."},{"emoji":"🔄","word":"变","pinyin":"biàn","pos":"Động từ","meaning":"thay đổi","example":"天气变冷了。","examplePinyin":"Tiānqì biàn lěng le.","exampleVi":"Thời tiết trở lạnh."},{"emoji":"🍂","word":"季节","pinyin":"jìjié","pos":"Danh từ","meaning":"mùa (trong năm)","example":"这个季节很美。","examplePinyin":"Zhè ge jìjié hěn měi.","exampleVi":"Mùa này rất đẹp."},{"emoji":"📊","word":"变化","pinyin":"biànhuà","pos":"Động từ / Danh từ","meaning":"thay đổi; sự thay đổi","example":"天气变化很快。","examplePinyin":"Tiānqì biànhuà hěn kuài.","exampleVi":"Thời tiết thay đổi rất nhanh."},{"emoji":"❄️","word":"冬天","pinyin":"dōngtiān","pos":"Danh từ","meaning":"mùa đông","example":"冬天很冷。","examplePinyin":"Dōngtiān hěn lěng.","exampleVi":"Mùa đông rất lạnh."},{"emoji":"🔁","word":"常常","pinyin":"chángcháng","pos":"Phó từ","meaning":"thường, thường xuyên","example":"他常常去公园。","examplePinyin":"Tā chángcháng qù gōngyuán.","exampleVi":"Anh ấy thường đến công viên."},{"emoji":"👀","word":"关注","pinyin":"guānzhù","pos":"Động từ","meaning":"quan tâm, chú ý","example":"请关注天气。","examplePinyin":"Qǐng guānzhù tiānqì.","exampleVi":"Xin chú ý thời tiết."},{"emoji":"🗓️","word":"四季","pinyin":"sìjì","pos":"Danh từ","meaning":"bốn mùa","example":"一年有四季。","examplePinyin":"Yì nián yǒu sì jì.","exampleVi":"Một năm có bốn mùa."},{"emoji":"🌷","word":"春天","pinyin":"chūntiān","pos":"Danh từ","meaning":"mùa xuân","example":"春天花开了。","examplePinyin":"Chūntiān huā kāi le.","exampleVi":"Mùa xuân hoa nở."},{"emoji":"☀️","word":"夏天","pinyin":"xiàtiān","pos":"Danh từ","meaning":"mùa hè","example":"夏天很热。","examplePinyin":"Xiàtiān hěn rè.","exampleVi":"Mùa hè rất nóng."},{"emoji":"🌤️","word":"凉快","pinyin":"liángkuai","pos":"Tính từ","meaning":"mát mẻ","example":"秋天很凉快。","examplePinyin":"Qiūtiān hěn liángkuai.","exampleVi":"Mùa thu rất mát mẻ."},{"emoji":"🍁","word":"秋天","pinyin":"qiūtiān","pos":"Danh từ","meaning":"mùa thu","example":"秋天叶子黄了。","examplePinyin":"Qiūtiān yèzi huáng le.","exampleVi":"Mùa thu lá vàng."},{"emoji":"🍃","word":"叶子","pinyin":"yèzi","pos":"Danh từ","meaning":"lá","example":"树上有很多叶子。","examplePinyin":"Shù shang yǒu hěn duō yèzi.","exampleVi":"Trên cây có nhiều lá."},{"emoji":"🦋","word":"变成","pinyin":"biànchéng","pos":"Động từ","meaning":"trở thành","example":"水变成冰了。","examplePinyin":"Shuǐ biànchéng bīng le.","exampleVi":"Nước biến thành băng."}],"summary":"Hai bạn Bạch Gia Nguyệt và Vương Nhất Phi trò chuyện về thời tiết và các mùa trong năm — mùa này thời tiết thay đổi rất nhanh, bỗng dưng nổi gió đổ mưa nên phải mang ô, rồi kể đặc điểm của bốn mùa xuân, hạ, thu, đông.","structures":[{"han":"这个季节天气变化很快","pinyin":"Zhè ge jìjié tiānqì biànhuà hěn kuài","meaning":"Thời tiết mùa này thay đổi rất nhanh.","note":"Chủ đề + nhận xét: mẫu câu kể chuyện thời tiết"},{"han":"或者坐车，或者走路","pinyin":"Huòzhě zuò chē, huòzhě zǒu lù","meaning":"Hoặc đi xe, hoặc đi bộ.","note":"Lựa chọn"},{"han":"下起雨来了","pinyin":"Xià qǐ yǔ lái le","meaning":"Trời bắt đầu mưa rồi.","note":"V + 起来: bắt đầu xảy ra"},{"han":"把伞带上","pinyin":"Bǎ sǎn dài shang","meaning":"Mang ô theo đi.","note":"把 + mang theo"}],"natural":["Nói về thời tiết, người TQ hay dùng \"变天了\" (trời trở rồi) — ngắn gọn hơn \"天气变化了\", bạn nên thuộc.","\"刮风/下雨\" là cách nói chuẩn cho \"nổi gió/đổ mưa\" — đừng nói \"风来了\" nghe rất Tây.","Khi trời sắp mưa, người TQ hay nhắc nhau \"带把伞\" (mang ô theo) — câu này dùng hằng ngày."],"grammar":[{"title":"Câu ghép lựa chọn: 或者……，或者……","formula":"或者 + A, + 或者 + B","explain":"\"Hoặc A, hoặc B\" trong câu kể (không phải câu hỏi). Nhớ phân biệt với 还是 (dùng trong câu hỏi).","examples":"或者明天去，或者后天去，我给你打电话。 (Huòzhě míngtiān qù, huòzhě hòutiān qù, wǒ gěi nǐ dǎ diànhuà) — Hoặc đi ngày mai, hoặc đi ngày kia, tôi sẽ gọi điện cho bạn.. 我们或者今天去电影院看电影，或者明天在家看电影。 (Wǒmen huòzhě jīntiān qù diànyǐngyuàn kàn diànyǐng, huòzhě míngtiān zài jiā kàn diànyǐng) — Chúng ta hoặc hôm nay đi rạp xem phim, hoặc ngày mai xem phim ở nhà.. 晚饭你自己选，或者吃中国菜，或者吃日本菜，或者吃泰国菜。 (Wǎnfàn nǐ zìjǐ xuǎn, huòzhě chī Zhōngguó cài, huòzhě chī Rìběn cài, huòzhě chī Tàiguó cài) — Bữa tối bạn tự chọn, hoặc ăn món Trung Quốc, hoặc ăn món Nhật, hoặc ăn món Thái.","tip":"","error":"Câu hỏi \"…hay…?\" thì dùng 还是, không dùng 或者."},{"title":"Bổ ngữ xu hướng \"起来\" (mở rộng)","formula":"Động từ + 起来 / Tính từ + 起来","explain":"Ngoài nghĩa \"đứng dậy\", 起来 còn có 2 nghĩa bóng hay gặp: (1) \"bắt đầu xảy ra\": 下起雨来 (trời bắt đầu mưa), 哭起来 (òa khóc); (2) \"trông có vẻ\": 看起来 (trông có vẻ), 听起来 (nghe có vẻ).","examples":"雨已经下起来了。 (Yǔ yǐjīng xià qǐlái le) — Mưa đã bắt đầu rơi rồi.. 最近天气热起来了。 (Zuìjìn tiānqì rè qǐlái le) — Gần đây thời tiết đã bắt đầu nóng lên.. 怎么突然刮起风来了？ (Zěnme tūrán guā qǐ fēng lái?) — Sao đột nhiên lại nổi gió thế?","tip":"","error":"看起来 (trông có vẻ) khác 看上来 (không có cách nói này) — chỉ có 看起来/听起来/闻起来."},{"title":"Phó từ chỉ phạm vi \"就\"","formula":"","explain":"就 ngoài nghĩa \"thì\", còn có nghĩa \"CHỈ\" — giới hạn phạm vi, tương đương \"只\". Đọc nhẹ, nhấn vào sự ít ỏi.","examples":"北京常常下雪，但听说今年就下了一次。 (Běijīng chángcháng xià xuě, dàn tīngshuō jīnnián jiù xià le yī cì) — Bắc Kinh thường có tuyết, nhưng nghe nói năm nay chỉ rơi có một lần.. 他昨天就看了十分钟书。 (Tā zuótiān jiù kàn le shí fēnzhōng shū) — Hôm qua anh ấy chỉ đọc sách có mười phút.. 我每天书包里都放着雨伞，就今天没带。 (Wǒ měitiān shūbāo li dōu fàng zhe yǔsǎn, jiù jīntiān méi dài) — Ngày nào trong cặp tôi cũng để ô, chỉ riêng hôm nay không mang.. 你们点的菜都挺好吃的，就我点的这个菜不太好吃。 (Nǐmen diǎn de cài dōu tǐng hǎochī de, jiù wǒ diǎn de zhège cài bù tài hǎochī) — Các món các bạn gọi đều khá ngon, chỉ riêng món tôi gọi này không ngon lắm.","tip":"","error":"就 (chỉ) khác 才 (mới) — \"我就三个人\" (chỉ có 3 người — ít), \"我才三个人\" (sai)."},{"title":"Bổ ngữ xu hướng \"下来\" (mở rộng)","formula":"Động từ + 下来","explain":"Ngoài nghĩa \"đi xuống\", 下来 còn có nghĩa \"từ đầu đến cuối, ghi/nhớ lại\": 写下来 (ghi lại), 记下来 (nhớ kỹ), 冷静下来 (bình tĩnh lại).","examples":"这一年多住下来，我还是更喜欢北京的四季。 (Zhè yī nián duō zhù xiàlái, wǒ háishì gèng xǐhuan Běijīng de sìjì) — Sống ở đây hơn một năm nay, tôi vẫn thích bốn mùa của Bắc Kinh hơn.. 这半年练下来，他画画的水平提高了不少。 (Zhè bànnián liàn xiàlái, tā huà huà de shuǐpíng tígāo le bù shǎo) — Luyện tập nửa năm nay, trình độ vẽ của anh ấy đã nâng lên không ít.. 5000米的长跑比赛，没想到我跑下来了。 (Wǔqiān mǐ de chángpǎo bǐsài, méi xiǎngdào wǒ pǎo xiàlái le) — Cuộc thi chạy dài 5000 mét, không ngờ tôi đã chạy xong.","tip":"","error":"下来 (hoàn thành, ghi lại) khác 下去 (tiếp tục) — 记下来 (ghi lại cho xong) vs 说下去 (nói tiếp)."}]},{"num":13,"emoji":"🏠","han":"我的新邻居来自英国","pinyin":"Wǒ de xīn línjū láizì Yīngguó","translation":"Hàng xóm mới của tôi đến từ Anh","theme":"Hàng xóm & văn hóa","vocab":[{"emoji":"🤝","word":"请客","pinyin":"qǐngkè","pos":"Động từ","meaning":"đãi khách, mời khách","example":"今天我请客，你别带钱。","examplePinyin":"Jīntiān wǒ qǐngkè, nǐ bié dài qián.","exampleVi":"Hôm nay tôi đãi khách, bạn đừng mang tiền."},{"emoji":"🧭","word":"南方","pinyin":"nánfāng","pos":"Danh từ","meaning":"miền Nam","example":"南方冬天不冷。","examplePinyin":"Nánfāng dōngtiān bù lěng.","exampleVi":"Miền Nam mùa đông không lạnh."},{"emoji":"🧭","word":"北方","pinyin":"běifāng","pos":"Danh từ","meaning":"miền Bắc","example":"北方人喜欢吃面食。","examplePinyin":"Běifāng rén xǐhuān chī miànshí.","exampleVi":"Người miền Bắc thích ăn món làm từ bột mì."},{"emoji":"📝","word":"做法","pinyin":"zuòfǎ","pos":"Danh từ","meaning":"cách làm","example":"这种菜的做法很简单。","examplePinyin":"Zhè zhǒng cài de zuòfǎ hěn jiǎndān.","exampleVi":"Cách làm món ăn này rất đơn giản."},{"emoji":"↔️","word":"不同","pinyin":"bùtóng","pos":"Tính từ","meaning":"khác nhau","example":"南方和北方的文化不同。","examplePinyin":"Nánfāng hé běifāng de wénhuà bùtóng.","exampleVi":"Văn hóa miền Nam và miền Bắc khác nhau."},{"emoji":"➕","word":"加","pinyin":"jiā","pos":"Động từ","meaning":"thêm","example":"请再加一点儿糖。","examplePinyin":"Qǐng zài jiā yì diǎnr táng.","exampleVi":"Xin thêm một chút đường nữa."},{"emoji":"❓","word":"的话","pinyin":"dehuà","pos":"Trợ từ/cấu trúc","meaning":"nếu","example":"有空的话，就来我家做客。","examplePinyin":"Yǒu kòng dehuà, jiù lái wǒ jiā zuòkè.","exampleVi":"Nếu rảnh thì đến nhà tôi chơi nhé."},{"emoji":"🏠","word":"做客","pinyin":"zuòkè","pos":"Động từ","meaning":"làm khách","example":"欢迎你来我家做客。","examplePinyin":"Huānyíng nǐ lái wǒ jiā zuòkè.","exampleVi":"Hoan nghênh bạn đến nhà tôi chơi."},{"emoji":"🏘️","word":"邻居","pinyin":"línjū","pos":"Danh từ","meaning":"hàng xóm, láng giềng","example":"我的邻居很友好。","examplePinyin":"Wǒ de línjū hěn yǒuhǎo.","exampleVi":"Hàng xóm của tôi rất thân thiện."},{"emoji":"😌","word":"放心","pinyin":"fàngxīn","pos":"Động từ","meaning":"yên tâm","example":"你放心，我会做好的。","examplePinyin":"Nǐ fàngxīn, wǒ huì zuò hǎo de.","exampleVi":"Bạn yên tâm, tôi sẽ làm tốt."},{"emoji":"🍷","word":"酒","pinyin":"jiǔ","pos":"Danh từ","meaning":"rượu","example":"他不喝酒。","examplePinyin":"Tā bù hē jiǔ.","exampleVi":"Anh ấy không uống rượu."},{"emoji":"📥","word":"放","pinyin":"fàng","pos":"Động từ","meaning":"đặt, để","example":"把礼物放在桌子上。","examplePinyin":"Bǎ lǐwù fàng zài zhuōzi shang.","exampleVi":"Đặt quà lên bàn."},{"emoji":"🧑‍🤝‍🧑","word":"客人","pinyin":"kèrén","pos":"Danh từ","meaning":"khách, khách hàng","example":"今天家里来了很多客人。","examplePinyin":"Jīntiān jiā li lái le hěn duō kèrén.","exampleVi":"Hôm nay nhà có rất nhiều khách đến."},{"emoji":"🎉","word":"晚会","pinyin":"wǎnhuì","pos":"Danh từ","meaning":"dạ hội, buổi tiệc tối","example":"学校举办了新年晚会。","examplePinyin":"Xuéxiào jǔbàn le xīnnián wǎnhuì.","exampleVi":"Trường tổ chức dạ hội năm mới."},{"emoji":"🎁","word":"礼物","pinyin":"lǐwù","pos":"Danh từ","meaning":"quà, món quà","example":"这是送给你的礼物。","examplePinyin":"Zhè shì sòng gěi nǐ de lǐwù.","exampleVi":"Đây là quà tặng bạn."},{"emoji":"🎨","word":"画家","pinyin":"huàjiā","pos":"Danh từ","meaning":"họa sĩ","example":"他想当一名画家。","examplePinyin":"Tā xiǎng dāng yì míng huàjiā.","exampleVi":"Anh ấy muốn làm họa sĩ."},{"emoji":"🍽️","word":"盘子","pinyin":"pánzi","pos":"Danh từ","meaning":"đĩa","example":"盘子里的菜很好吃。","examplePinyin":"Pánzi li de cài hěn hǎochī.","exampleVi":"Món ăn trong đĩa rất ngon."},{"emoji":"🔀","word":"一边","pinyin":"yìbiān","pos":"Phó từ","meaning":"vừa… vừa…","example":"我们一边吃饭，一边聊天儿。","examplePinyin":"Wǒmen yìbiān chī fàn, yìbiān liáotiānr.","exampleVi":"Chúng tôi vừa ăn cơm vừa trò chuyện."},{"emoji":"💬","word":"聊天儿","pinyin":"liáotiānr","pos":"Động từ","meaning":"trò chuyện, tán gẫu","example":"他们在公园里聊天儿。","examplePinyin":"Tāmen zài gōngyuán li liáotiānr.","exampleVi":"Họ đang trò chuyện trong công viên."},{"emoji":"🌍","word":"来自","pinyin":"láizì","pos":"Động từ","meaning":"đến từ","example":"我的新邻居来自英国。","examplePinyin":"Wǒ de xīn línjū láizì Yīngguó.","exampleVi":"Người hàng xóm mới của tôi đến từ Anh."},{"emoji":"💑","word":"夫妻","pinyin":"fūqī","pos":"Danh từ","meaning":"vợ chồng","example":"他们是一对年轻的夫妻。","examplePinyin":"Tāmen shì yí duì niánqīng de fūqī.","exampleVi":"Họ là một cặp vợ chồng trẻ."},{"emoji":"⏳","word":"直到","pinyin":"zhídào","pos":"Động từ/Giới từ","meaning":"cho đến, mãi đến","example":"他直到半夜才回家。","examplePinyin":"Tā zhídào bànyè cái huí jiā.","exampleVi":"Mãi đến nửa đêm anh ấy mới về nhà."},{"emoji":"🗺️","word":"地图","pinyin":"dìtú","pos":"Danh từ","meaning":"bản đồ","example":"你在地图上找一下吧。","examplePinyin":"Nǐ zài dìtú shang zhǎo yí xià ba.","exampleVi":"Bạn tìm trên bản đồ đi."},{"emoji":"🔹","word":"点","pinyin":"diǎn","pos":"Danh từ","meaning":"điểm, chấm nhỏ","example":"地图上有个红点。","examplePinyin":"Dìtú shang yǒu ge hóng diǎn.","exampleVi":"Trên bản đồ có một chấm đỏ."},{"emoji":"💭","word":"感到","pinyin":"gǎndào","pos":"Động từ","meaning":"cảm thấy","example":"我感到很开心。","examplePinyin":"Wǒ gǎndào hěn kāixīn.","exampleVi":"Tôi cảm thấy rất vui."},{"emoji":"🌅","word":"东方","pinyin":"dōngfāng","pos":"Danh từ","meaning":"phương Đông","example":"东方文化很有意思。","examplePinyin":"Dōngfāng wénhuà hěn yǒu yìsi.","exampleVi":"Văn hóa phương Đông rất thú vị."},{"emoji":"🏛️","word":"文化","pinyin":"wénhuà","pos":"Danh từ","meaning":"văn hóa","example":"我想了解中国文化。","examplePinyin":"Wǒ xiǎng liǎojiě Zhōngguó wénhuà.","exampleVi":"Tôi muốn tìm hiểu văn hóa Trung Quốc."},{"emoji":"🇬🇧","word":"英国","pinyin":"Yīngguó","pos":"Danh từ riêng","meaning":"Vương quốc Anh","example":"他来自英国。","examplePinyin":"Tā láizì Yīngguó.","exampleVi":"Anh ấy đến từ Anh."}],"summary":"Có gia đình mới chuyển đến làm hàng xóm — đến từ nước Anh xa xôi. Mọi người tò mò rủ nhau sang chơi, tìm hiểu phong tục: cách đãi khách, món ăn miền Nam/miền Bắc khác nhau ra sao. Bữa tiệc nhỏ diễn ra vui vẻ — mọi người vừa ăn vừa trò chuyện, chủ nhà đãi khách chu đáo. Câu chuyện mở rộng sang khác biệt văn hóa Đông – Tây và cảm nhận về cuộc sống mới.","structures":[{"han":"我的新邻居来自英国","pinyin":"Wǒ de xīn línjū láizì Yīngguó","meaning":"Hàng xóm mới của tôi đến từ Anh.","note":"Câu then chốt của bài"},{"han":"有空的话，就来我家做客","pinyin":"Yǒu kòng dehuà, jiù lái wǒ jiā zuòkè","meaning":"Nếu rảnh thì đến nhà tôi chơi nhé.","note":"Câu then chốt của bài"},{"han":"我们一边吃饭，一边聊天儿","pinyin":"Wǒmen yìbiān chī fàn, yìbiān liáotiānr","meaning":"Chúng tôi vừa ăn vừa trò chuyện.","note":"Câu then chốt của bài"}],"natural":["请客 — văn hóa đãi khách: ở Trung Quốc, người mời khách thường giành trả tiền bằng được — đó là lịch sự, không phải khoe của. Nói 我请客 (để tôi mời) là câu cửa miệng khi đi ăn cùng bạn bè.","做客 vs 请客: cặp từ dễ nhầm — 做客 là \"làm khách\" (đi chơi nhà người ta), 请客 là \"đãi khách\" (mời người ta). Nhớ: mình 请客, mình đi 做客.","的话 — nêu điều kiện mềm mại: 有空的话…… (nếu rảnh thì……) nghe tự nhiên, thân thiện hơn nhiều so với cứng nhắc 如果……. Trong văn nói hàng ngày, người TQ dùng 的话 cực kỳ nhiều.","边……边……: dạng rút gọn khẩu ngữ của 一边……一边…… — 边吃边聊 (vừa ăn vừa nói chuyện) là câu người TQ nói hằng ngày."],"grammar":[{"title":"Câu ghép giả định \"……的话，就……\"","formula":"Điều kiện + 的话, (就) + kết quả","explain":"\"Nếu…… thì……\" — cách nêu điều kiện rất tự nhiên trong văn nói. Không cần 如果 cũng đủ nghĩa.","examples":"你们有时间的话，就来我家做客。 (Nǐmen yǒu shíjiān dehuà, jiù lái wǒ jiā zuòkè.) — Nếu các bạn có thời gian thì đến nhà tôi làm khách. 你觉得满意的话，咱们就买。 (Nǐ juéde mǎnyì dehuà, zánmen jiù mǎi.) — Nếu bạn thấy hài lòng thì chúng ta mua. 明天天气好的话，我就去爬山。 (Míngtiān tiānqì hǎo dehuà, wǒ jiù qù pá shān.) — Nếu mai thời tiết đẹp, tôi sẽ đi leo núi.","tip":"","error":"的话 phải đặt SAU TOÀN BỘ cụm điều kiện, không chen giữa chủ ngữ và vị ngữ."},{"title":"Câu chữ 把 (4) — bổ ngữ xu hướng/trạng thái","formula":"Chủ ngữ + 把 + tân ngữ + động từ + bổ ngữ (得……/进去/出来…)","explain":"Nâng cao của câu 把 — sau động từ có thể là bổ ngữ xu hướng (进去/出来) hoặc bổ ngữ trạng thái (V得……).","examples":"你把声音开得太大了。 (Nǐ bǎ shēngyīn kāi de tài dà le.) — Bạn bật âm lượng to quá rồi. 他把球踢进去了吗？ (Tā bǎ qiú tī jìnqù le ma?) — Anh ấy đã đá bóng vào trong chưa? 你把字写得太小了，我看不清楚。 (Nǐ bǎ zì xiě de tài xiǎo le, wǒ kàn bù qīngchu.) — Bạn viết chữ nhỏ quá, tôi nhìn không rõ.","tip":"","error":"得/进去 đặt sau động từ — không viết \"把得声音开大了\"."},{"title":"\"一边……，一边……\"","formula":"一边 + việc 1，一边 + việc 2 (cùng chủ ngữ)","explain":"\"Vừa…… vừa……\" — hai hành động diễn ra ĐỒNG THỜI. Khẩu ngữ rút gọn: 边吃边聊.","examples":"咱们一边吃蛋糕，一边聊天儿吧。 (Zánmen yìbiān chī dàngāo, yìbiān liáo tiānr ba.) — Chúng ta vừa ăn bánh vừa trò chuyện nhé. 我喜欢一边跑步，一边听音乐。 (Wǒ xǐhuān yìbiān pǎobù, yìbiān tīng yīnyuè.) — Tôi thích vừa chạy bộ vừa nghe nhạc. 你不应该边开车边打电话。 (Nǐ bù yīnggāi biān kāichē biān dǎ diànhuà.) — Bạn không nên vừa lái xe vừa gọi điện thoại.","tip":"","error":"Khác 一会儿……一会儿…… (hai việc LUÂN PHIÊN nhau)."}]},{"num":14,"emoji":"📕","han":"这本书被别人借走了","pinyin":"Zhè běn shū bèi biérén jiè zǒu le","translation":"Cuốn sách này bị người khác mượn mất rồi","theme":"Thư viện & câu chữ 被","vocab":[{"emoji":"📖","word":"词典","pinyin":"cídiǎn","pos":"Danh từ","meaning":"từ điển","example":"我买了一本汉越词典。","examplePinyin":"Wǒ mǎi le yì běn Hàn-Yuè cídiǎn.","exampleVi":"Tôi mua một cuốn từ điển Hán-Việt."},{"emoji":"🥇","word":"最好","pinyin":"zuìhǎo","pos":"Phó từ","meaning":"tốt nhất","example":"最好先去图书馆看看。","examplePinyin":"Zuìhǎo xiān qù túshūguǎn kànkan.","exampleVi":"Tốt nhất nên đến thư viện xem trước."},{"emoji":"🕐","word":"节","pinyin":"jié","pos":"Lượng từ","meaning":"tiết (học)","example":"今天有三节课。","examplePinyin":"Jīntiān yǒu sān jié kè.","exampleVi":"Hôm nay có ba tiết học."},{"emoji":"📚","word":"图书馆","pinyin":"túshūguǎn","pos":"Danh từ","meaning":"thư viện","example":"图书馆里很安静。","examplePinyin":"Túshūguǎn li hěn ānjìng.","exampleVi":"Trong thư viện rất yên tĩnh."},{"emoji":"🔄","word":"被","pinyin":"bèi","pos":"Giới từ","meaning":"bị, được","example":"这本书被别人借走了。","examplePinyin":"Zhè běn shū bèi biérén jiè zǒu le.","exampleVi":"Cuốn sách này bị người khác mượn mất rồi."},{"emoji":"⭐","word":"名人","pinyin":"míngrén","pos":"Danh từ","meaning":"danh nhân","example":"他是历史上的名人。","examplePinyin":"Tā shì lìshǐ shang de míngrén.","exampleVi":"Ông ấy là danh nhân trong lịch sử."},{"emoji":"📜","word":"故事","pinyin":"gùshi","pos":"Danh từ","meaning":"câu chuyện","example":"这个故事很有意思。","examplePinyin":"Zhè ge gùshi hěn yǒu yìsi.","exampleVi":"Câu chuyện này rất thú vị."},{"emoji":"➡️","word":"然后","pinyin":"ránhòu","pos":"Liên từ","meaning":"sau đó","example":"先吃饭，然后去看电影。","examplePinyin":"Xiān chī fàn, ránhòu qù kàn diànyǐng.","exampleVi":"Ăn cơm trước, sau đó đi xem phim."},{"emoji":"📰","word":"报纸","pinyin":"bàozhǐ","pos":"Danh từ","meaning":"báo, tờ báo","example":"爸爸每天看报纸。","examplePinyin":"Bàba měitiān kàn bàozhǐ.","exampleVi":"Bố ngày nào cũng đọc báo."},{"emoji":"🤦","word":"忘记","pinyin":"wàngjì","pos":"Động từ","meaning":"quên","example":"我忘记带伞了。","examplePinyin":"Wǒ wàngjì dài sǎn le.","exampleVi":"Tôi quên mang ô rồi."},{"emoji":"📱","word":"电子书","pinyin":"diànzǐshū","pos":"Danh từ","meaning":"sách điện tử","example":"我喜欢看电子书。","examplePinyin":"Wǒ xǐhuān kàn diànzǐshū.","exampleVi":"Tôi thích đọc sách điện tử."},{"emoji":"👧","word":"女生","pinyin":"nǚshēng","pos":"Danh từ","meaning":"nữ sinh","example":"她是我们班的女生。","examplePinyin":"Tā shì wǒmen bān de nǚshēng.","exampleVi":"Cô ấy là nữ sinh lớp tôi."},{"emoji":"🎭","word":"表演","pinyin":"biǎoyǎn","pos":"Động từ","meaning":"biểu diễn","example":"他们在晚会上表演节目。","examplePinyin":"Tāmen zài wǎnhuì shang biǎoyǎn jiémù.","exampleVi":"Họ biểu diễn tiết mục trong dạ hội."},{"emoji":"🎪","word":"节目","pinyin":"jiémù","pos":"Danh từ","meaning":"tiết mục","example":"这个节目很精彩。","examplePinyin":"Zhè ge jiémù hěn jīngcǎi.","exampleVi":"Tiết mục này rất hay."},{"emoji":"🤷","word":"怎么办","pinyin":"zěnme bàn","pos":"Cụm từ","meaning":"làm thế nào","example":"书不见了，怎么办？","examplePinyin":"Shū bú jiàn le, zěnme bàn?","exampleVi":"Sách mất rồi, làm thế nào đây?"},{"emoji":"👨‍🏫","word":"校长","pinyin":"xiàozhǎng","pos":"Danh từ","meaning":"hiệu trưởng","example":"校长在台上讲话。","examplePinyin":"Xiàozhǎng zài tái shang jiǎng huà.","exampleVi":"Hiệu trưởng đang phát biểu trên sân khấu."},{"emoji":"🔜","word":"面前","pinyin":"miànqián","pos":"Danh từ","meaning":"phía trước, trước mặt","example":"他站在我面前。","examplePinyin":"Tā zhàn zài wǒ miànqián.","exampleVi":"Anh ấy đứng trước mặt tôi."},{"emoji":"😟","word":"有些","pinyin":"yǒuxiē","pos":"Phó từ","meaning":"hơi, có phần","example":"我有些紧张。","examplePinyin":"Wǒ yǒuxiē jǐnzhāng.","exampleVi":"Tôi hơi hồi hộp."},{"emoji":"🙏","word":"相信","pinyin":"xiāngxìn","pos":"Động từ","meaning":"tin tưởng","example":"你要相信自己。","examplePinyin":"Nǐ yào xiāngxìn zìjǐ.","exampleVi":"Bạn phải tin vào chính mình."},{"emoji":"🎊","word":"新年","pinyin":"xīnnián","pos":"Danh từ","meaning":"năm mới","example":"新年快乐！","examplePinyin":"Xīnnián kuàilè!","exampleVi":"Chúc mừng năm mới!"},{"emoji":"🏫","word":"班级","pinyin":"bānjí","pos":"Danh từ","meaning":"lớp học","example":"我们班级有三十个人。","examplePinyin":"Wǒmen bānjí yǒu sānshí ge rén.","exampleVi":"Lớp tôi có ba mươi người."},{"emoji":"💃","word":"跳","pinyin":"tiào","pos":"Động từ","meaning":"nhảy, khiêu vũ","example":"她喜欢跳舞。","examplePinyin":"Tā xǐhuān tiào wǔ.","exampleVi":"Cô ấy thích nhảy múa."},{"emoji":"🎒","word":"留学生","pinyin":"liúxuéshēng","pos":"Danh từ","meaning":"lưu học sinh","example":"他是越南留学生。","examplePinyin":"Tā shì Yuènán liúxuéshēng.","exampleVi":"Anh ấy là lưu học sinh Việt Nam."},{"emoji":"🔚","word":"最后","pinyin":"zuìhòu","pos":"Danh từ/Phó từ","meaning":"cuối cùng","example":"最后我们一起吃了饭。","examplePinyin":"Zuìhòu wǒmen yìqǐ chī le fàn.","exampleVi":"Cuối cùng chúng tôi cùng nhau ăn cơm."},{"emoji":"👥","word":"一块儿","pinyin":"yíkuàir","pos":"Phó từ","meaning":"cùng nhau","example":"我们一块儿去吧。","examplePinyin":"Wǒmen yíkuàir qù ba.","exampleVi":"Chúng ta cùng đi đi."},{"emoji":"🌐","word":"网站","pinyin":"wǎngzhàn","pos":"Danh từ","meaning":"trang web","example":"这个网站很有用。","examplePinyin":"Zhè ge wǎngzhàn hěn yǒuyòng.","exampleVi":"Trang web này rất hữu ích."},{"emoji":"🎬","word":"视频","pinyin":"shìpín","pos":"Danh từ","meaning":"video","example":"我在网上看了视频。","examplePinyin":"Wǒ zài wǎng shang kàn le shìpín.","exampleVi":"Tôi đã xem video trên mạng."}],"summary":"Một bạn đến thư viện mượn sách thì phát hiện cuốn sách cần đã bị người khác mượn mất — đành tìm sách khác thay thế, có bạn gợi ý tra từ điển hoặc đọc sách điện tử. Câu chuyện chuyển sang việc chuẩn bị tiết mục văn nghệ đón năm mới: một bạn được phân công hát nhưng hồi hộp vì phải biểu diễn trước hiệu trưởng và cả trường, các bạn xúm vào động viên \"có gì mà hồi hộp, ai cũng thích nghe bạn hát mà\".","structures":[{"han":"这本书被别人借走了","pinyin":"Zhè běn shū bèi biérén jiè zǒu le","meaning":"Cuốn sách này bị người khác mượn mất rồi.","note":"Câu then chốt của bài"},{"han":"紧张什么啊，我们都喜欢听你唱歌","pinyin":"Jǐnzhāng shénme a, wǒmen dōu xǐhuān tīng nǐ chàng gē","meaning":"Có gì mà hồi hộp, chúng tôi đều thích nghe bạn hát.","note":"Câu then chốt của bài"},{"han":"先去图书馆借书，然后去游泳","pinyin":"Xiān qù túshūguǎn jiè shū, ránhòu qù yóu yǒng","meaning":"Đến thư viện mượn sách trước, rồi đi bơi.","note":"Câu then chốt của bài"}],"natural":["被 — câu bị động \"quốc dân\": 把 người/vật chịu tác động lên làm chủ ngữ. Nhưng lưu ý quan trọng: không phải câu \"bị/được\" tiếng Việt nào cũng dịch bằng 被 — nhiều khi nói chủ động gọn và tự nhiên hơn (ví dụ \"cửa đóng rồi\" nói 门关了 là đủ).","被 không chỉ chuyện xấu: 他被表扬了 (anh ấy ĐƯỢC khen) — 被 dùng cho cả điều tốt khi muốn nhấn mạnh \"nhận được tác động\".","×什么啊 — trấn an kiểu phản vấn: 紧张什么啊 = \"có gì mà hồi hộp!\". Giữa bạn bè thân thì ấm áp, nhưng với người chưa thân có thể nghe gắt — lúc đó dùng 别紧张，你唱得很好 sẽ an toàn hơn.","怎么办: câu hỏi \"làm sao đây\" đa năng nhất tiếng Trung — gặp rắc rối gì cũng dùng được."],"grammar":[{"title":"Câu bị động với \"被\"","formula":"Chủ ngữ (chịu tác động) + 被 + (người gây ra) + động từ + thành phần khác","explain":"Nhấn mạnh ai/cái gì CHỊU ảnh hưởng của hành động. Có thể lược người gây ra khi không cần nêu.","examples":"这本书被别人借走了。 (Zhè běn shū bèi biérén jiè zǒu le.) — Quyển sách này đã bị người khác mượn mất rồi. 水果可能被弟弟吃了。 (Shuǐguǒ kěnéng bèi dìdi chī le.) — Hoa quả có thể đã bị em trai ăn mất rồi. 我们俩经常被叫错名字。 (Wǒmen liǎ jīngcháng bèi jiào cuò míngzi.) — Hai chúng tôi thường xuyên bị gọi nhầm tên.","tip":"","error":"Đừng dịch mọi câu \"bị/được\" sang 被 — nhiều câu nói chủ động tự nhiên hơn."},{"title":"\"先……，再/然后……\"","formula":"先 + việc 1，再/然后 + việc 2","explain":"\"Trước……, rồi……\" — sắp xếp thứ tự hành động.","examples":"我要先去图书馆借书，然后去游泳。 (Wǒ yào xiān qù túshūguǎn jiè shū, ránhòu qù yóu yǒng.) — Tôi sẽ đến thư viện mượn sách trước, rồi đi bơi. 你先去买门票，再来这里找我。 (Nǐ xiān qù mǎi ménpiào, zài lái zhèlǐ zhǎo wǒ.) — Bạn đi mua vé vào cửa trước, rồi đến đây tìm tôi. 你们先回房间休息一会儿，然后再出来吃晚饭。 (Nǐmen xiān huí fángjiān xiūxi yíhuìr, ránhòu zài chūlái chī wǎnfàn.) — Các bạn về phòng nghỉ một lát trước, rồi hãy ra ngoài ăn tối.","tip":"","error":"再 (việc TIẾP THEO, chưa làm) khác 又 (việc LẶP LẠI, đã xảy ra)."},{"title":"Cấu trúc \"×什么（啊）\"","formula":"Tính từ/động từ + 什么(啊)","explain":"Câu phản vấn để trấn an hoặc phản bác — \"có gì mà……!\". Không phải câu hỏi thật.","examples":"A：一想到要在校长、老师和那么多同学面前表演，我就有些紧张。 B：紧张什么啊，我们都喜欢听你唱歌，你要相信自己。 (Yì xiǎngdào yào zài xiàozhǎng, lǎoshī hé nàme duō tóngxué miànqián biǎoyǎn, wǒ jiù yǒuxiē jǐnzhāng. Jǐnzhāng shénme a, wǒmen dōu xǐhuān tīng nǐ chàng gē, nǐ yào xiāngxìn zìjǐ.) — A: Vừa nghĩ đến việc phải biểu diễn trước hiệu trưởng, thầy cô và nhiều bạn học như vậy là tôi hơi căng thẳng. B: Căng thẳng gì chứ, chúng tôi đều thích nghe bạn hát, bạn phải tin vào bản thân mình. A：我最近胖了很多，不想拍照了。 B：胖什么啊，你看起来不胖也不瘦。 (Wǒ zuìjìn pàng le hěn duō, bù xiǎng pāizhào le. Pàng shénme a, nǐ kàn qǐlái bù pàng yě bù shòu.) — A: Dạo này tôi béo lên nhiều, không muốn chụp ảnh nữa. B: Béo gì chứ, trông bạn không béo cũng không gầy. A：还有十分钟，快点儿走吧。 B：急什么啊，马上就到了。 (Hái yǒu shí fēnzhōng, kuài diǎnr zǒu ba. Jí shénme a, mǎshàng jiù dào le.) — A: Còn mười phút nữa thôi, đi nhanh lên nào. B: Vội gì chứ, sắp đến nơi rồi.","tip":"","error":"Ngữ điệu quyết định tất cả — nói nhẹ là trấn an, nói gắt thành trách móc."}]},{"num":15,"emoji":"🏯","han":"我是半个南京人","pinyin":"Wǒ shì bàn ge Nánjīng rén","translation":"Tôi là nửa người Nam Kinh","theme":"Nam Kinh & Hoàng Hà","vocab":[{"emoji":"🔵","word":"蓝","pinyin":"lán","pos":"Tính từ","meaning":"màu xanh lam","example":"天空是蓝的。","examplePinyin":"Tiānkōng shì lán de.","exampleVi":"Bầu trời màu xanh."},{"emoji":"📏","word":"段","pinyin":"duàn","pos":"Lượng từ","meaning":"đoạn, quãng","example":"这段路很长。","examplePinyin":"Zhè duàn lù hěn cháng.","exampleVi":"Đoạn đường này rất dài."},{"emoji":"📍","word":"附近","pinyin":"fùjìn","pos":"Danh từ","meaning":"gần đó, lân cận","example":"我家附近有个公园。","examplePinyin":"Wǒ jiā fùjìn yǒu ge gōngyuán.","exampleVi":"Gần nhà tôi có một công viên."},{"emoji":"🛣️","word":"马路","pinyin":"mǎlù","pos":"Danh từ","meaning":"đường cái","example":"过马路要小心。","examplePinyin":"Guò mǎlù yào xiǎoxīn.","exampleVi":"Qua đường phải cẩn thận."},{"emoji":"📅","word":"平时","pinyin":"píngshí","pos":"Danh từ","meaning":"thường ngày","example":"平时我六点起床。","examplePinyin":"Píngshí wǒ liù diǎn qǐ chuáng.","exampleVi":"Thường ngày tôi dậy lúc 6 giờ."},{"emoji":"🏫","word":"放学","pinyin":"fàngxué","pos":"Động từ","meaning":"tan học","example":"放学以后我们去打球。","examplePinyin":"Fàngxué yǐhòu wǒmen qù dǎ qiú.","exampleVi":"Sau khi tan học chúng tôi đi đánh bóng."},{"emoji":"🎮","word":"游戏","pinyin":"yóuxì","pos":"Danh từ","meaning":"trò chơi","example":"孩子们在玩游戏。","examplePinyin":"Háizimen zài wán yóuxì.","exampleVi":"Bọn trẻ đang chơi trò chơi."},{"emoji":"👴","word":"老人","pinyin":"lǎorén","pos":"Danh từ","meaning":"người già","example":"老人在公园里散步。","examplePinyin":"Lǎorén zài gōngyuán li sànbù.","exampleVi":"Người già đi dạo trong công viên."},{"emoji":"📋","word":"根据","pinyin":"gēnjù","pos":"Giới từ/Động từ","meaning":"căn cứ vào, dựa vào","example":"根据天气，我们决定明天去。","examplePinyin":"Gēnjù tiānqì, wǒmen juédìng míngtiān qù.","exampleVi":"Căn cứ vào thời tiết, chúng tôi quyết định ngày mai đi."},{"emoji":"🔍","word":"了解","pinyin":"liǎojiě","pos":"Động từ","meaning":"hiểu rõ, tìm hiểu","example":"我想了解这座城市。","examplePinyin":"Wǒ xiǎng liǎojiě zhè zuò chéngshì.","exampleVi":"Tôi muốn tìm hiểu thành phố này."},{"emoji":"🔀","word":"可是","pinyin":"kěshì","pos":"Liên từ","meaning":"nhưng","example":"很好，可是太贵了。","examplePinyin":"Hěn hǎo, kěshì tài guì le.","exampleVi":"Rất tốt, nhưng đắt quá."},{"emoji":"⬆️","word":"以上","pinyin":"yǐshàng","pos":"Danh từ","meaning":"trở lên","example":"十八岁以上可以参加。","examplePinyin":"Shíbā suì yǐshàng kěyǐ cānjiā.","exampleVi":"Từ 18 tuổi trở lên có thể tham gia."},{"emoji":"⭐","word":"有名","pinyin":"yǒumíng","pos":"Tính từ","meaning":"nổi tiếng","example":"南京是有名的城市。","examplePinyin":"Nánjīng shì yǒumíng de chéngshì.","exampleVi":"Nam Kinh là thành phố nổi tiếng."},{"emoji":"🏞️","word":"景点","pinyin":"jǐngdiǎn","pos":"Danh từ","meaning":"điểm du lịch","example":"这里的景点很多。","examplePinyin":"Zhèlǐ de jǐngdiǎn hěn duō.","exampleVi":"Điểm du lịch ở đây rất nhiều."},{"emoji":"🧳","word":"游客","pinyin":"yóukè","pos":"Danh từ","meaning":"du khách","example":"很多游客来这里玩。","examplePinyin":"Hěn duō yóukè lái zhèlǐ wán.","exampleVi":"Rất nhiều du khách đến đây chơi."},{"emoji":"🗺️","word":"外地","pinyin":"wàidì","pos":"Danh từ","meaning":"nơi khác, vùng khác","example":"他来自外地。","examplePinyin":"Tā láizì wàidì.","exampleVi":"Anh ấy đến từ nơi khác."},{"emoji":"💬","word":"聊","pinyin":"liáo","pos":"Động từ","meaning":"trò chuyện","example":"我们聊了很久。","examplePinyin":"Wǒmen liáo le hěn jiǔ.","exampleVi":"Chúng tôi đã trò chuyện rất lâu."},{"emoji":"🌊","word":"河","pinyin":"hé","pos":"Danh từ","meaning":"sông","example":"这条河很长。","examplePinyin":"Zhè tiáo hé hěn cháng.","exampleVi":"Con sông này rất dài."},{"emoji":"🔗","word":"关系","pinyin":"guānxi","pos":"Danh từ","meaning":"quan hệ","example":"他们关系很好。","examplePinyin":"Tāmen guānxi hěn hǎo.","exampleVi":"Quan hệ của họ rất tốt."},{"emoji":"🤱","word":"养","pinyin":"yǎng","pos":"Động từ","meaning":"nuôi dưỡng","example":"黄河养了我们几千年。","examplePinyin":"Huáng Hé yǎng le wǒmen jǐ qiān nián.","exampleVi":"Sông Hoàng Hà đã nuôi dưỡng chúng ta mấy nghìn năm."},{"emoji":"🧭","word":"西北","pinyin":"xīběi","pos":"Danh từ","meaning":"tây bắc","example":"他家在城市的西北。","examplePinyin":"Tā jiā zài chéngshì de xīběi.","exampleVi":"Nhà anh ấy ở phía tây bắc thành phố."},{"emoji":"🚶","word":"经过","pinyin":"jīngguò","pos":"Động từ","meaning":"đi qua, trải qua","example":"每天我经过这条马路。","examplePinyin":"Měitiān wǒ jīngguò zhè tiáo mǎlù.","exampleVi":"Mỗi ngày tôi đi qua con đường này."},{"emoji":"🌱","word":"草地","pinyin":"cǎodì","pos":"Danh từ","meaning":"thảm cỏ","example":"草地上有很多花。","examplePinyin":"Cǎodì shang yǒu hěn duō huā.","exampleVi":"Trên thảm cỏ có rất nhiều hoa."},{"emoji":"👋","word":"遇见","pinyin":"yùjiàn","pos":"Động từ","meaning":"tình cờ gặp","example":"昨天我在街上遇见了他。","examplePinyin":"Zuótiān wǒ zài jiē shang yùjiàn le tā.","exampleVi":"Hôm qua tôi tình cờ gặp anh ấy trên phố."},{"emoji":"🏯","word":"南京","pinyin":"Nánjīng","pos":"Danh từ riêng","meaning":"Nam Kinh","example":"南京是中国有名的城市。","examplePinyin":"Nánjīng shì Zhōngguó yǒumíng de chéngshì.","exampleVi":"Nam Kinh là thành phố nổi tiếng của Trung Quốc."},{"emoji":"🌊","word":"黄河","pinyin":"Huáng Hé","pos":"Danh từ riêng","meaning":"sông Hoàng Hà","example":"黄河很长。","examplePinyin":"Huáng Hé hěn cháng.","exampleVi":"Sông Hoàng Hà rất dài."}],"summary":"Một bạn kể về quê hương Nam Kinh của mình — thành phố nổi tiếng bên dòng Hoàng Hà. Bạn ấy kể cuộc sống thường ngày: tan học ra công viên chơi, người già đi dạo, đường phố quen thuộc. Rồi giải thích vì sao tự nhận là \"nửa người Nam Kinh\" — sống ở đó lâu nên thành người địa phương. Bài học khép lại bằng niềm tự hào: với người Trung Quốc, Hoàng Hà như người mẹ đã nuôi dưỡng dân tộc suốt mấy nghìn năm.","structures":[{"han":"我是半个南京人","pinyin":"Wǒ shì bàn ge Nánjīng rén","meaning":"Tôi là nửa người Nam Kinh.","note":"Câu then chốt của bài"},{"han":"在我们中国人看来，黄河像妈妈一样","pinyin":"Zài wǒmen Zhōngguó rén kànlái, Huáng Hé xiàng māma yíyàng","meaning":"Theo người Trung Quốc chúng tôi, Hoàng Hà như người mẹ.","note":"Câu then chốt của bài"},{"han":"不一会儿，天就黑了","pinyin":"Bù yíhuìr, tiān jiù hēi le","meaning":"Chẳng mấy chốc trời đã tối.","note":"Câu then chốt của bài"}],"natural":["半个……人 — cách nói hóm hỉnh: 半个南京人 (nửa người Nam Kinh) — người sống lâu ở một nơi, hòa nhập đến mức \"thành người địa phương\". Cách nói dí dỏm, thân thiện, dùng được cho mọi thành phố: 半个北京人, 半个上海人.","根据 vs 因为: 根据 dẫn CĂN CỨ (quy định, nhu cầu, tình hình) — 根据要求 (theo yêu cầu); 因为 nêu NGUYÊN NHÂN. Nói 根据我很忙 để chỉ \"vì tôi bận\" là sai — phải dùng 因为.","Ba cách nêu quan điểm: 在我看来 (theo nhận định của tôi — trang trọng), 我觉得 (tôi thấy — gần gũi, dùng nhiều nhất), 对我来说 (đối với tôi — góc độ cảm nhận). Dùng đúng chỗ là lên trình ngay.","Số từ + lượng từ lặp lại: 一点儿一点儿 (từng chút một), 一天一天 (từng ngày) — cách diễn đạt giàu hình ảnh, rất văn học. Khẩu ngữ có thể lược 地."],"grammar":[{"title":"Giới từ \"根据\"","formula":"根据 + căn cứ, + hành động/phán đoán","explain":"\"Căn cứ vào / theo……\" — dẫn ra cơ sở (quy định, nhu cầu, tình hình) cho hành động hay nhận định.","examples":"这几年小区根据他们的需要，有了很多变化。 (Zhè jǐ nián xiǎoqū gēnjù tāmen de xūyào, yǒu le hěn duō biànhuà.) — Mấy năm nay khu dân cư đã có nhiều thay đổi theo nhu cầu của họ. 根据要求，我们必须参加明天的会议。 (Gēnjù yāoqiú, wǒmen bìxū cānjiā míngtiān de huìyì.) — Theo yêu cầu, chúng tôi phải tham gia cuộc họp ngày mai. 老师根据每个学生的兴趣，选择了不一样的书。 (Lǎoshī gēnjù měi ge xuéshēng de xìngqù, xuǎnzé le bù yíyàng de shū.) — Cô giáo đã chọn những cuốn sách khác nhau căn cứ vào sở thích của từng học sinh.","tip":"","error":"根据 dẫn căn cứ, không thay cho 因为 (nguyên nhân)."},{"title":"Cụm số lượng lặp lại \"số từ + lượng từ + số từ + lượng từ\"","formula":"(số từ + lượng từ) × 2 (+ 地) + động từ","explain":"Làm trạng ngữ chỉ CÁCH THỨC — \"từng…… một\", diễn đạt giàu hình ảnh.","examples":"我得一点儿一点儿给您讲。 (Wǒ děi yìdiǎnr yìdiǎnr gěi nín jiǎng.) — Tôi phải kể cho bác từng chút một. 学生们的汉语水平一天一天地提高了。 (Xuéshēngmen de Hànyǔ shuǐpíng yì tiān yì tiān de tígāo le.) — Trình độ tiếng Hán của các học sinh tiến bộ từng ngày. 他们两个两个地走进去了。 (Tāmen liǎng ge liǎng ge de zǒu jìnqù le.) — Họ đi vào từng hai người một.","tip":"","error":"Khác 个个都…… (mỗi người đều……) — cái này nhấn trình tự/cách thức, không phải \"mỗi\"."},{"title":"Cấu trúc \"在……看来\"","formula":"在 + người/nhóm người + 看来, + nhận định","explain":"\"Theo…… thấy/nhìn nhận\" — nêu quan điểm đứng từ góc nhìn của ai đó.","examples":"在我们中国人看来，黄河像妈妈一样，养了我们几千年。 (Zài wǒmen Zhōngguó rén kànlái, Huáng Hé xiàng māma yíyàng, yǎng le wǒmen jǐ qiān nián.) — Theo người Trung Quốc chúng tôi, sông Hoàng Hà như mẹ, đã nuôi dưỡng chúng tôi mấy nghìn năm. 在同事们看来，她工作非常认真。 (Zài tóngshìmen kànlái, tā gōngzuò fēicháng rènzhēn.) — Theo các đồng nghiệp, cô ấy làm việc rất nghiêm túc. 在我看来，每天读书是一种很好的习惯。 (Zài wǒ kànlái, měitiān dú shū shì yì zhǒng hěn hǎo de xíguàn.) — Theo tôi, đọc sách mỗi ngày là một thói quen rất tốt.","tip":"","error":"Đừng nhầm với 看起来 (trông có vẻ — ấn tượng vẻ ngoài) hay 对我来说 (góc độ cảm nhận)."},{"title":"Cụm cố định \"不一会儿\"","formula":"不一会儿 (+ 就) + sự việc","explain":"\"Chẳng mấy chốc\" — khoảng thời gian rất ngắn, thường đi với 就 để nhấn nhanh.","examples":"难过的事情不一会儿就忘了。 (Nánguò de shìqing bù yíhuìr jiù wàng le.) — Chuyện buồn chẳng mấy chốc đã quên. 不一会儿，张校长就来了。 (Bù yíhuìr, Zhāng xiàozhǎng jiù lái le.) — Chẳng mấy chốc hiệu trưởng Trương đã đến. 两个小时看起来长，但是不一会儿就过去了。 (Liǎng ge xiǎoshí kàn qǐlái cháng, dànshì bù yíhuìr jiù guòqù le.) — Hai tiếng đồng hồ trông thì dài, nhưng chẳng mấy chốc đã trôi qua.","tip":"","error":"不 ở đây KHÔNG phủ định hành động sau — cả cụm là một biểu thức thời gian."}]},{"num":16,"emoji":"🐼","han":"我听说有的熊猫出国了","pinyin":"Wǒ tīngshuō yǒude xióngmāo chūguó le","translation":"Tôi nghe nói có một số con gấu trúc đã ra nước ngoài","theme":"Động vật & vườn thú","vocab":[{"emoji":"⏳","word":"半天","pinyin":"bàntiān","pos":"Số lượng từ","meaning":"nửa ngày; rất lâu","example":"我等了半天。","examplePinyin":"Wǒ děng le bàntiān.","exampleVi":"Tôi đã đợi rất lâu."},{"emoji":"🍚","word":"饱","pinyin":"bǎo","pos":"Tính từ","meaning":"no","example":"我已经吃饱了。","examplePinyin":"Wǒ yǐjīng chī bǎo le.","exampleVi":"Tôi ăn no rồi."},{"emoji":"🧑","word":"大人","pinyin":"dàrén","pos":"Danh từ","meaning":"người lớn","example":"这里有两个大人。","examplePinyin":"Zhèlǐ yǒu liǎng ge dàrén.","exampleVi":"Ở đây có hai người lớn."},{"emoji":"🐼","word":"大熊猫","pinyin":"dàxióngmāo","pos":"Danh từ","meaning":"gấu trúc lớn","example":"大熊猫很可爱。","examplePinyin":"Dàxióngmāo hěn kě'ài.","exampleVi":"Gấu trúc rất đáng yêu."},{"emoji":"🐾","word":"动物","pinyin":"dòngwù","pos":"Danh từ","meaning":"động vật","example":"你喜欢什么动物？","examplePinyin":"Nǐ xǐhuan shénme dòngwù?","exampleVi":"Bạn thích động vật nào?"},{"emoji":"🦁","word":"动物园","pinyin":"dòngwùyuán","pos":"Danh từ","meaning":"vườn thú","example":"周末我们去动物园。","examplePinyin":"Zhōumò wǒmen qù dòngwùyuán.","exampleVi":"Cuối tuần chúng tôi đi vườn thú."},{"emoji":"📌","word":"关于","pinyin":"guānyú","pos":"Giới từ","meaning":"về, liên quan đến","example":"这是关于中国的书。","examplePinyin":"Zhè shì guānyú Zhōngguó de shū.","exampleVi":"Đây là sách về Trung Quốc."},{"emoji":"🏆","word":"国宝","pinyin":"guóbǎo","pos":"Danh từ","meaning":"báu vật quốc gia, quốc bảo","example":"大熊猫是中国的国宝。","examplePinyin":"Dàxióngmāo shì Zhōngguó de guóbǎo.","exampleVi":"Gấu trúc là quốc bảo của Trung Quốc."},{"emoji":"🤔","word":"好像","pinyin":"hǎoxiàng","pos":"Động từ","meaning":"hình như; giống như","example":"他好像很累。","examplePinyin":"Tā hǎoxiàng hěn lèi.","exampleVi":"Hình như anh ấy rất mệt."},{"emoji":"🦶","word":"脚","pinyin":"jiǎo","pos":"Danh từ","meaning":"bàn chân","example":"我的脚有点儿疼。","examplePinyin":"Wǒ de jiǎo yǒudiǎnr téng.","exampleVi":"Chân tôi hơi đau."},{"emoji":"🥰","word":"可爱","pinyin":"kě'ài","pos":"Tính từ","meaning":"đáng yêu","example":"这只猫真可爱。","examplePinyin":"Zhè zhī māo zhēn kě'ài.","exampleVi":"Con mèo này thật đáng yêu."},{"emoji":"😊","word":"脸","pinyin":"liǎn","pos":"Danh từ","meaning":"mặt, khuôn mặt","example":"她的脸红了。","examplePinyin":"Tā de liǎn hóng le.","exampleVi":"Mặt cô ấy đỏ lên."},{"emoji":"❓","word":"奇怪","pinyin":"qíguài","pos":"Tính từ","meaning":"kỳ lạ","example":"这件事很奇怪。","examplePinyin":"Zhè jiàn shì hěn qíguài.","exampleVi":"Chuyện này rất kỳ lạ."},{"emoji":"💡","word":"其实","pinyin":"qíshí","pos":"Phó từ","meaning":"thật ra, thực ra","example":"其实我也不知道。","examplePinyin":"Qíshí wǒ yě bù zhīdào.","exampleVi":"Thật ra tôi cũng không biết."},{"emoji":"🌍","word":"全","pinyin":"quán","pos":"Tính từ","meaning":"toàn bộ, tất cả","example":"这些书我全看过。","examplePinyin":"Zhèxiē shū wǒ quán kàn guo.","exampleVi":"Những quyển sách này tôi đọc hết rồi."},{"emoji":"👀","word":"认得","pinyin":"rènde","pos":"Động từ","meaning":"nhận ra, biết mặt/chữ","example":"你认得这个字吗？","examplePinyin":"Nǐ rènde zhège zì ma?","exampleVi":"Bạn nhận ra chữ này không?"},{"emoji":"👥","word":"身边","pinyin":"shēnbiān","pos":"Danh từ","meaning":"bên cạnh (người)","example":"妈妈坐在我身边。","examplePinyin":"Māma zuò zài wǒ shēnbiān.","exampleVi":"Mẹ ngồi bên cạnh tôi."},{"emoji":"❤️","word":"喜爱","pinyin":"xǐ'ài","pos":"Động từ","meaning":"yêu thích","example":"孩子们喜爱动物。","examplePinyin":"Háizimen xǐ'ài dòngwù.","exampleVi":"Trẻ em yêu thích động vật."},{"emoji":"🌿","word":"野生","pinyin":"yěshēng","pos":"Tính từ","meaning":"hoang dã","example":"我们要保护野生动物。","examplePinyin":"Wǒmen yào bǎohù yěshēng dòngwù.","exampleVi":"Chúng ta cần bảo vệ động vật hoang dã."},{"emoji":"⏱️","word":"一会儿","pinyin":"yíhuìr","pos":"Phó từ","meaning":"một lát","example":"请等一会儿。","examplePinyin":"Qǐng děng yíhuìr.","exampleVi":"Hãy đợi một lát."},{"emoji":"🧤","word":"脏","pinyin":"zāng","pos":"Tính từ","meaning":"bẩn","example":"你的手太脏了。","examplePinyin":"Nǐ de shǒu tài zāng le.","exampleVi":"Tay bạn bẩn quá."},{"emoji":"😲","word":"张","pinyin":"zhāng","pos":"Động từ","meaning":"mở, há","example":"请张开嘴。","examplePinyin":"Qǐng zhāngkāi zuǐ.","exampleVi":"Hãy há miệng ra."},{"emoji":"🤲","word":"照顾","pinyin":"zhàogu","pos":"Động từ","meaning":"chăm sóc","example":"她在照顾孩子。","examplePinyin":"Tā zài zhàogu háizi.","exampleVi":"Cô ấy đang chăm sóc con."},{"emoji":"📅","word":"周末","pinyin":"zhōumò","pos":"Danh từ","meaning":"cuối tuần","example":"周末你有空吗？","examplePinyin":"Zhōumò nǐ yǒu kòng ma?","exampleVi":"Cuối tuần bạn có rảnh không?"},{"emoji":"🎋","word":"竹子","pinyin":"zhúzi","pos":"Danh từ","meaning":"tre, trúc","example":"大熊猫喜欢吃竹子。","examplePinyin":"Dàxióngmāo xǐhuan chī zhúzi.","exampleVi":"Gấu trúc thích ăn trúc."},{"emoji":"👄","word":"嘴","pinyin":"zuǐ","pos":"Danh từ","meaning":"miệng","example":"请把嘴张开。","examplePinyin":"Qǐng bǎ zuǐ zhāngkāi.","exampleVi":"Hãy há miệng ra."}],"summary":"Hai chị em Lưu Tiểu Tuyết và Lưu Tiểu Minh theo mẹ Vương Nhất Tuyết đi vườn thú Bắc Kinh xem gấu trúc. Từ con mèo đáng yêu ở quán trà, qua “mười vạn câu hỏi vì sao” của cậu em về loài gấu trúc, đến buổi ngắm gấu trúc thật trong vườn thú — bài học đưa bạn đi cùng gia đình nhỏ khám phá vì sao gấu trúc là quốc bảo của Trung Quốc, và khép lại bằng lời kể của mẹ về vườn thú nổi tiếng này.","structures":[{"han":"它一会儿在你脚边睡觉，一会儿在你身上爬","pinyin":"Tā yíhuìr zài nǐ jiǎobiān shuìjiào, yíhuìr zài nǐ shēnshang pá","meaning":"Nó lúc thì ngủ bên chân bạn, lúc lại bò trên người bạn.","note":"Câu then chốt của bài"},{"han":"全世界只有中国有野生大熊猫","pinyin":"Quán shìjiè zhǐyǒu Zhōngguó yǒu yěshēng dàxióngmāo","meaning":"Trên toàn thế giới chỉ Trung Quốc mới có gấu trúc hoang dã.","note":"Câu then chốt của bài"},{"han":"一般来说，熊猫每天要睡很多次觉","pinyin":"Yìbān lái shuō, xióngmāo měitiān yào shuì hěn duō cì jiào","meaning":"Nói chung, gấu trúc mỗi ngày ngủ rất nhiều giấc.","note":"Câu then chốt của bài"}],"natural":["一会儿……一会儿…… khác 一边……一边……: một mẫu là LUÂN PHIÊN (lúc này lúc kia), một mẫu là ĐỒNG THỜI (vừa… vừa…). Nhầm hai mẫu này là lỗi kinh điển.","关于 vs 对： 关于 nêu CHỦ ĐỀ (cuốn sách về động vật — 关于动物的书); 对 nêu THÁI ĐỘ với đối tượng （对中文感兴趣 — hứng thú với tiếng Trung).","大熊猫 hay 大猫熊？ Theo cấu tạo họ hàng, tên 'đúng' là 大猫熊 (họ gấu), nhưng cả thế giới quen gọi 大熊猫 — chi tiết vui được giải thích ngay trong bài khóa 16-2.","睡很多次觉 — từ li hợp 睡觉 có thể chèn cụm số lần vào giữa: 睡一次觉、睡很多次觉. Tương tự: 洗澡 → 洗个澡."],"grammar":[{"title":"Câu ghép đẳng lập “一会儿……，一会儿……”","formula":"一会儿 + hành động/trạng thái 1，一会儿 + hành động/trạng thái 2","explain":"Diễn tả nhiều hành động hoặc trạng thái LUÂN PHIÊN nhau trong một khoảng thời gian ngắn — “lúc thì…, lúc thì…”. Các hành động không diễn ra cùng lúc.","examples":"它一会儿在你脚边睡觉，一会儿在你身上爬。(Tā yíhuìr zài nǐ jiǎobiān shuìjiào, yíhuìr zài nǐ shēnshang pá.) — Nó lúc thì ngủ bên chân bạn, lúc lại bò trên người bạn. 他一会儿进来，一会儿出去，忙得很。(Tā yīhuìr jìnlái, yīhuìr chūqù, máng de hěn.) — Anh ấy lúc thì đi vào, lúc thì đi ra, bận lắm. 最近天气变化很快，一会儿冷，一会儿热。(Zuìjìn tiānqì biànhuà hěn kuài, yíhuìr lěng, yíhuìr rè.) — Gần đây thời tiết thay đổi rất nhanh, lúc lạnh lúc nóng.","tip":"","error":"Khác 一边……一边…… (hai việc CÙNG lúc — Bài 18). 一会儿……一会儿…… là thay phiên nhau, không đồng thời."},{"title":"Giới từ “关于”","formula":"关于 + danh từ / cụm danh từ (+ 的 + danh từ)","explain":"Giới thiệu nội dung, sự việc hay vấn đề được đề cập — “về…”. Thường đứng đầu câu để nêu chủ đề, hơi trang trọng hơn khẩu ngữ thân mật.","examples":"关于这个问题，我得慢慢给你讲。(Guānyú zhège wèntí, wǒ děi mànmàn gěi nǐ jiǎng.) — Về vấn đề này, tôi phải giải thích từ từ cho bạn. (得 đọc děi = phải). 关于他的要求，我们还要开会以后再决定。(Guānyú tā de yāoqiú, wǒmen hái yào kāihuì yǐhòu zài juédìng.) — Về yêu cầu của anh ấy, chúng tôi còn phải họp xong rồi mới quyết định. 关于比赛的时间，我明天一定告诉大家。(Guānyú bǐsài de shíjiān, wǒ míngtiān yīdìng gàosù dàjiā.) — Về thời gian thi đấu, ngày mai tôi nhất định sẽ báo cho mọi người.","tip":"","error":"Không thay thế cho 对 trong mọi trường hợp: nói thái độ với đối tượng thì dùng 对 — 对中文感兴趣 (hứng thú với tiếng Trung), không dùng 关于。"},{"title":"Cụm từ cố định “一般来说”","formula":"一般来说，+ nhận định chung","explain":"Đưa ra nhận xét mang tính khái quát — “nói chung / thông thường mà nói”. Nhận xét này để ngỏ khả năng có ngoại lệ, không có nghĩa “luôn luôn tuyệt đối”.","examples":"一般来说，熊猫每天要睡很多次觉。(Yìbān lái shuō, xióngmāo měitiān yào shuì hěn duō cì jiào.) — Thông thường, gấu trúc ngủ nhiều lần mỗi ngày. 一般来说，这种树每年开一次花。(Yìbān lái shuō, zhè zhǒng shù měinián kāi yī cì huā.) — Nói chung, loại cây này mỗi năm nở hoa một lần. 一般来说，学习外语需要多练习。(Yìbān lái shuō, xuéxí wàiyǔ xūyào duō liànxí.) — Nói chung, học ngoại ngữ cần luyện tập nhiều.","tip":"","error":"Chỉ dùng cho nhận định CHUNG về một nhóm/loại; chuyện cụ thể của một người tại một thời điểm thì không đặt 一般来说。"},{"title":"Câu so sánh (11): A 比 B + 多/少/早/晚 + động từ + số lượng","formula":"A + 比 + B + 多/少/早/晚 + động từ + cụm số lượng","explain":"Khi vị ngữ của câu 比 là động từ, đặt 多/少/早/晚 TRƯỚC động từ để chỉ mức chênh lệch về số lượng hoặc thời gian. Cụm số lượng phía sau là ĐỘ CHÊNH LỆCH, không phải tổng số.","examples":"冬天比夏天早关门一个小时。(Dōngtiān bǐ xiàtiān zǎo guānmén yí ge xiǎoshí.) — Mùa đông đóng cửa sớm hơn mùa hè một tiếng. 哥哥比弟弟多吃了三个饺子。(Gēge bǐ dìdi duō chī le sān ge jiǎozi.) — Anh trai đã ăn nhiều hơn em trai ba chiếc bánh chẻo. 我比他晚到了十分钟。(Wǒ bǐ tā wǎn dào le shí fēnzhōng.) — Tôi đến muộn hơn anh ấy mười phút.","tip":"","error":"“Ăn nhiều hơn ba cái” （多吃了三个） là CHÊNH 3 cái, không phải tổng cộng ăn 3 cái. Đừng đặt số lượng ngay sau 比。"}]},{"num":17,"emoji":"🎓","han":"我要多向认真的人学习","pinyin":"Wǒ yào duō xiàng rènzhēn de rén xuéxí","translation":"Tôi cần học hỏi nhiều hơn từ những người cẩn thận","theme":"Định hướng & học tập","vocab":[{"emoji":"🧭","word":"向","pinyin":"xiàng","pos":"Giới từ","meaning":"hướng về","example":"我要向你学习。","examplePinyin":"Wǒ yào xiàng nǐ xuéxí.","exampleVi":"Tôi muốn học hỏi bạn."},{"emoji":"🪜","word":"楼梯","pinyin":"lóutī","pos":"Danh từ","meaning":"cầu thang bộ","example":"我们走楼梯吧。","examplePinyin":"Wǒmen zǒu lóutī ba.","exampleVi":"Chúng ta đi cầu thang bộ nhé."},{"emoji":"😨","word":"害怕","pinyin":"hàipà","pos":"Động từ","meaning":"sợ, sợ hãi","example":"别害怕，我在这里。","examplePinyin":"Bié hàipà, wǒ zài zhèlǐ.","exampleVi":"Đừng sợ, tôi ở đây."},{"emoji":"😠","word":"生气","pinyin":"shēngqì","pos":"Động từ","meaning":"giận, tức giận","example":"别生气了。","examplePinyin":"Bié shēngqì le.","exampleVi":"Đừng giận nữa."},{"emoji":"👀","word":"常见","pinyin":"chángjiàn","pos":"Tính từ","meaning":"thường gặp, thường thấy","example":"这是常见的问题。","examplePinyin":"Zhè shì chángjiàn de wèntí.","exampleVi":"Đây là vấn đề thường gặp."},{"emoji":"🧠","word":"聪明","pinyin":"cōngming","pos":"Tính từ","meaning":"thông minh","example":"这个孩子很聪明。","examplePinyin":"Zhège háizi hěn cōngming.","exampleVi":"Đứa trẻ này rất thông minh."},{"emoji":"❌","word":"错","pinyin":"cuò","pos":"Tính từ","meaning":"sai, lỗi, lỗi sai","example":"这个字写错了。","examplePinyin":"Zhège zì xiě cuò le.","exampleVi":"Chữ này viết sai rồi."},{"emoji":"💭","word":"认为","pinyin":"rènwéi","pos":"Động từ","meaning":"cho rằng, nghĩ rằng","example":"我认为这个办法很好。","examplePinyin":"Wǒ rènwéi zhège bànfǎ hěn hǎo.","exampleVi":"Tôi cho rằng cách này rất hay."},{"emoji":"🌸","word":"到处","pinyin":"dàochù","pos":"Phó từ","meaning":"mọi nơi, khắp nơi","example":"这里到处都是花。","examplePinyin":"Zhèlǐ dàochù dōu shì huā.","exampleVi":"Ở đây khắp nơi đều là hoa."},{"emoji":"▶️","word":"继续","pinyin":"jìxù","pos":"Động từ","meaning":"tiếp tục","example":"我们继续学习吧。","examplePinyin":"Wǒmen jìxù xuéxí ba.","exampleVi":"Chúng ta tiếp tục học nhé."},{"emoji":"👍","word":"同意","pinyin":"tóngyì","pos":"Động từ","meaning":"đồng ý","example":"我同意你的想法。","examplePinyin":"Wǒ tóngyì nǐ de xiǎngfǎ.","exampleVi":"Tôi đồng ý với ý kiến của bạn."},{"emoji":"⚠️","word":"可","pinyin":"kě","pos":"Liên từ","meaning":"nhưng, nhưng mà; thật (nhấn mạnh)","example":"这道题可难了。","examplePinyin":"Zhè dào tí kě nán le.","exampleVi":"Bài này khó thật đấy."},{"emoji":"🏠","word":"屋子","pinyin":"wūzi","pos":"Danh từ","meaning":"phòng, căn phòng, ngôi nhà","example":"屋子里很安静。","examplePinyin":"Wūzi lǐ hěn ānjìng.","exampleVi":"Trong phòng rất yên tĩnh."},{"emoji":"🔗","word":"有关","pinyin":"yǒuguān","pos":"Động từ","meaning":"liên quan, có liên quan","example":"这本书跟历史有关。","examplePinyin":"Zhè běn shū gēn lìshǐ yǒuguān.","exampleVi":"Quyển sách này liên quan đến lịch sử."},{"emoji":"📴","word":"关机","pinyin":"guānjī","pos":"Động từ","meaning":"tắt máy","example":"睡觉前请关机。","examplePinyin":"Shuìjiào qián qǐng guānjī.","exampleVi":"Hãy tắt máy trước khi ngủ."},{"emoji":"🗓️","word":"前天","pinyin":"qiántiān","pos":"Danh từ","meaning":"hôm kia","example":"我前天去了北京。","examplePinyin":"Wǒ qiántiān qù le Běijīng.","exampleVi":"Hôm kia tôi đã đến Bắc Kinh."},{"emoji":"✈️","word":"留学","pinyin":"liúxué","pos":"Động từ","meaning":"du học","example":"我想去中国留学。","examplePinyin":"Wǒ xiǎng qù Zhōngguó liúxué.","exampleVi":"Tôi muốn đi du học Trung Quốc."},{"emoji":"🗺️","word":"国家","pinyin":"guójiā","pos":"Danh từ","meaning":"quốc gia, đất nước","example":"你来自哪个国家？","examplePinyin":"Nǐ láizì nǎ ge guójiā?","exampleVi":"Bạn đến từ quốc gia nào?"},{"emoji":"🍎","word":"比如","pinyin":"bǐrú","pos":"Động từ","meaning":"ví dụ như, chẳng hạn","example":"我喜欢水果，比如苹果。","examplePinyin":"Wǒ xǐhuan shuǐguǒ, bǐrú píngguǒ.","exampleVi":"Tôi thích trái cây, chẳng hạn như táo."},{"emoji":"🔎","word":"查","pinyin":"chá","pos":"Động từ","meaning":"tra, kiểm tra","example":"我用手机查生词。","examplePinyin":"Wǒ yòng shǒujī chá shēngcí.","exampleVi":"Tôi dùng điện thoại tra từ mới."},{"emoji":"✅","word":"有用","pinyin":"yǒuyòng","pos":"Tính từ","meaning":"hữu ích","example":"这些笔记很有用。","examplePinyin":"Zhèxiē bǐjì hěn yǒuyòng.","exampleVi":"Những ghi chép này rất hữu ích."},{"emoji":"😌","word":"容易","pinyin":"róngyì","pos":"Tính từ","meaning":"dễ, dễ dàng","example":"这道题很容易。","examplePinyin":"Zhè dào tí hěn róngyì.","exampleVi":"Bài này rất dễ."},{"emoji":"🗣️","word":"回答","pinyin":"huídá","pos":"Động từ","meaning":"trả lời","example":"请回答这个问题。","examplePinyin":"Qǐng huídá zhège wèntí.","exampleVi":"Hãy trả lời câu hỏi này."},{"emoji":"🧭","word":"方向","pinyin":"fāngxiàng","pos":"Danh từ","meaning":"phương hướng","example":"我们走错方向了。","examplePinyin":"Wǒmen zǒu cuò fāngxiàng le.","exampleVi":"Chúng ta đi sai hướng rồi."},{"emoji":"🔑","word":"只有","pinyin":"zhǐyǒu","pos":"Liên từ","meaning":"chỉ có","example":"只有认真听，才能听懂。","examplePinyin":"Zhǐyǒu rènzhēn tīng, cái néng tīngdǒng.","exampleVi":"Chỉ khi chăm chú nghe mới có thể nghe hiểu."},{"emoji":"💎","word":"真正","pinyin":"zhēnzhèng","pos":"Phó từ","meaning":"thực sự, thật sự","example":"他是真正的朋友。","examplePinyin":"Tā shì zhēnzhèng de péngyou.","exampleVi":"Anh ấy là người bạn thật sự."},{"emoji":"🧩","word":"难题","pinyin":"nántí","pos":"Danh từ","meaning":"vấn đề khó, vấn đề nan giải","example":"我们解决了这个难题。","examplePinyin":"Wǒmen jiějué le zhège nántí.","exampleVi":"Chúng tôi đã giải quyết vấn đề khó này."}],"summary":"Bốn mảnh chuyện xoay quanh những lựa chọn cuối thời sinh viên: một bạn học lo lắng vì hay làm sai việc đơn giản và quyết tâm học hỏi người nghiêm túc; Trần Thiên Trung chưa muốn đi làm mà muốn tiếp tục học, được bạn bè gợi ý hướng đi từ sở thích máy tính đến dự định du học Trung Quốc; và câu hỏi “sau này bạn muốn làm gì?” — nghe đơn giản mà không dễ trả lời.","structures":[{"han":"你不是喜欢玩电脑吗？","pinyin":"Nǐ bú shì xǐhuan wán diànnǎo ma?","meaning":"Chẳng phải bạn thích dùng máy tính sao?","note":"Câu then chốt của bài"},{"han":"我还没想好学什么，更没想好去哪个国家","pinyin":"Wǒ hái méi xiǎnghǎo xué shénme, gèng méi xiǎnghǎo qù nǎge guójiā","meaning":"Tôi chưa nghĩ xong học gì, lại càng chưa nghĩ xong đi nước nào.","note":"Câu then chốt của bài"},{"han":"只有想清楚自己真正喜欢什么，才能做出最合适的选择","pinyin":"Zhǐyǒu xiǎng qīngchu zìjǐ zhēnzhèng xǐhuan shénme, cái néng zuò chū zuì héshì de xuǎnzé","meaning":"Chỉ khi nghĩ rõ mình thật sự thích gì mới chọn được lựa chọn phù hợp nhất.","note":"Câu then chốt của bài"}],"natural":["向……学习 là cụm nên thuộc lòng: “học hỏi ai đó”. Đừng nói 学向 ai — 向 luôn đứng trước đối tượng, động từ 学习 theo sau.","不是……吗？ nghe KHẲNG ĐỊNH hơn một câu hỏi thật: dùng để nhắc lại hoặc nhấn mạnh. Với người chưa thân, giọng điệu dễ bị hiểu là trách móc.","可是 là “nhưng” rất khẩu ngữ, thường đứng đầu vế sau: 是，可是我还没想好…… — nhẹ và tự nhiên hơn 但是 trong văn nói hằng ngày.","只有……才…… (Bài 17, điều kiện CẦN) và 只要……就…… (Bài 18, điều kiện ĐỦ) là cặp câu điều kiện kinh điển của HSK 3 — học liền hai bài để so sánh."],"grammar":[{"title":"Giới từ “向”","formula":"向 + đại từ / danh từ / cụm danh từ + động từ","explain":"Chỉ phương hướng mà hành động hướng tới (向前走 — đi về phía trước) hoặc đối tượng trừu tượng （向老师学习 — học hỏi thầy cô, 向你道歉 — xin lỗi bạn). Nghĩa cụ thể do động từ phía sau quyết định.","examples":"别再向前走了。(Bié zài xiàng qián zǒu le.) — Đừng đi về phía trước nữa. 以后我要多向认真的人学习。(Yǐhòu wǒ yào duō xiàng rènzhēn de rén xuéxí.) — Sau này tôi phải học hỏi nhiều hơn từ những người nghiêm túc. 孩子一看见妈妈，就向她跑过去了。(Háizi yí kànjiàn māma, jiù xiàng tā pǎoguòqu le.) — Đứa trẻ vừa nhìn thấy mẹ liền chạy về phía mẹ.","tip":"","error":"向老师学习 là “học hỏi thầy/cô”, khác 给老师…… (làm gì cho ai nhận). Không thay tự do 向 bằng 给。"},{"title":"Câu phản vấn “不是……吗？”","formula":"不是 + nội dung cần xác nhận / nhấn mạnh + 吗？","explain":"Hình thức là câu phủ định nhưng ý nghĩa thường là khẳng định, nhấn mạnh — “Chẳng phải... sao?”. Dùng khi người nói không hiểu, không hài lòng, muốn nhắc nhở hoặc xác nhận lại điều đã biết.","examples":"你不是喜欢玩电脑吗？你可以去看看跟电脑有关系的书。(Nǐ bú shì xǐhuan wán diànnǎo ma? Nǐ kěyǐ qù kànkan gēn diànnǎo yǒu guānxi de shū.) — Chẳng phải bạn thích dùng máy tính sao? Bạn có thể xem những cuốn sách liên quan đến máy tính. 你不是说今天有事吗？为什么来了？(Nǐ bú shì shuō jīntiān yǒu shì ma? Wèi shénme lái le?) — Chẳng phải bạn nói hôm nay có việc sao? Sao lại đến rồi?. 考试不是下个月吗？你怎么今天就开始复习了？(Kǎoshì bù shì xià ge yuè ma? Nǐ zěnme jīntiān jiù kāishǐ fùxí le?) — Chẳng phải thi vào tháng sau sao? Sao hôm nay bạn đã bắt đầu ôn tập rồi?","tip":"","error":"Tùy giọng điệu, câu này có thể mang sắc thái ngạc nhiên hoặc trách nhẹ. Muốn hỏi thông tin thuần túy với người chưa thân, hãy dùng câu hỏi trung tính."},{"title":"Câu ghép tăng tiến “……，更……”","formula":"Mệnh đề 1，更 + mệnh đề / nội dung có mức độ cao hơn","explain":"Mệnh đề thứ hai đẩy ý lên thêm một mức so với mệnh đề thứ nhất. Trong chuỗi phủ định, 更没…… nhấn việc thứ hai còn chưa được làm hơn nữa — “Ngay A còn chưa..., B lại càng chưa...”.","examples":"我还没想好学什么，更没想好去哪个国家。(Wǒ hái méi xiǎnghǎo xué shénme, gèng méi xiǎnghǎo qù nǎge guójiā.) — Tôi còn chưa nghĩ xong sẽ học gì, lại càng chưa nghĩ xong sẽ đi nước nào. 想提高中文水平要多听多看，更要多说多练。(Xiǎng tígāo Zhōngwén shuǐpíng yào duō tīng duō kàn, gèng yào duō shuō duō liàn.) — Muốn nâng cao trình độ tiếng Trung thì phải nghe nhiều, xem nhiều, và càng phải nói nhiều, luyện nhiều. 来中国学习，我学会了中文，更了解了中国文化。(Lái Zhōngguó xuéxí, wǒ xuéhuì le Zhōngwén, gèng liǎojiě le Zhōngguó wénhuà.) — Đến Trung Quốc học, tôi đã học được tiếng Trung, và càng hiểu hơn về văn hóa Trung Quốc.","tip":"","error":"Vế sau phải thật sự CAO HƠN về mức độ trong quan hệ tăng tiến, không phải liệt kê ngẫu nhiên hai việc. Và có 更 chưa chắc đã là nguyên nhân – kết quả."},{"title":"Câu điều kiện “只有……，才……”","formula":"只有 + điều kiện，才 + kết quả","explain":"Thành phần sau 只有 là điều kiện CẦN — không thể thiếu — để kết quả ở vế 才 có thể xảy ra: “Chỉ khi A thì mới B”.","examples":"只有想清楚自己真正喜欢什么，才能做出最合适的选择。(Zhǐyǒu xiǎng qīngchu zìjǐ zhēnzhèng xǐhuan shénme, cái néng zuò chū zuì héshì de xuǎnzé.) — Chỉ khi nghĩ rõ mình thật sự thích gì thì mới có thể đưa ra lựa chọn phù hợp nhất. 只有每天锻炼身体，才会越来越健康。(Zhǐyǒu měitiān duànliàn shēntǐ, cái huì yuè lái yuè jiànkāng.) — Chỉ khi tập thể dục mỗi ngày mới có thể ngày càng khỏe mạnh. 只有多听、多说、多看，你的中文水平才能提高。(Zhǐyǒu duō tīng, duō shuō, duō kàn, nǐ de Zhōngwén shuǐpíng cái néng tígāo.) — Chỉ khi nghe nhiều, nói nhiều, xem nhiều thì trình độ tiếng Trung của bạn mới nâng cao được.","tip":"","error":"Khác 只要……就…… (Bài 18): 只要 nói “chỉ cần A là đủ”, còn 只有……才…… nhấn điều kiện cần. Điều kiện cần chưa chắc bảo đảm kết quả: 只有努力，才有可能成功 (chỉ khi nỗ lực mới CÓ KHẢ NĂNG thành công)."}]},{"num":18,"emoji":"🥟","han":"我学会了包饺子","pinyin":"Wǒ xuéhuì le bāo jiǎozi","translation":"Tôi đã học được cách gói sủi cảo","theme":"Tết & gia đình","vocab":[{"emoji":"❓","word":"怎样","pinyin":"zěnyàng","pos":"Đại từ","meaning":"thế nào","example":"你想怎样学习？","examplePinyin":"Nǐ xiǎng zěnyàng xuéxí?","exampleVi":"Bạn muốn học như thế nào?"},{"emoji":"🎊","word":"过节","pinyin":"guòjié","pos":"Động từ","meaning":"đón lễ","example":"我们一起过节吧。","examplePinyin":"Wǒmen yìqǐ guòjié ba.","exampleVi":"Chúng ta cùng đón lễ nhé."},{"emoji":"🏮","word":"节","pinyin":"jié","pos":"Danh từ","meaning":"lễ, ngày lễ, dịp lễ","example":"过节时，我们一起吃饭。","examplePinyin":"Guòjié shí, wǒmen yìqǐ chī fàn.","exampleVi":"Vào dịp lễ, chúng tôi cùng ăn cơm."},{"emoji":"🎉","word":"节日","pinyin":"jiérì","pos":"Danh từ","meaning":"ngày lễ","example":"今天是什么节日？","examplePinyin":"Jīntiān shì shénme jiérì?","exampleVi":"Hôm nay là ngày lễ gì?"},{"emoji":"🎭","word":"联欢","pinyin":"liánhuān","pos":"Động từ","meaning":"liên hoan, vui chung","example":"大家一起联欢。","examplePinyin":"Dàjiā yìqǐ liánhuān.","exampleVi":"Mọi người cùng liên hoan."},{"emoji":"🤷","word":"大概","pinyin":"dàgài","pos":"Phó từ","meaning":"khoảng, đại khái; có lẽ","example":"他大概十点来。","examplePinyin":"Tā dàgài shí diǎn lái.","exampleVi":"Có lẽ anh ấy đến lúc mười giờ."},{"emoji":"👩","word":"阿姨","pinyin":"āyí","pos":"Danh từ","meaning":"cô, dì","example":"阿姨，您好！","examplePinyin":"Āyí, nín hǎo!","exampleVi":"Cháu chào cô ạ!"},{"emoji":"👨","word":"叔叔","pinyin":"shūshu","pos":"Danh từ","meaning":"chú, bác trai","example":"叔叔，您好！","examplePinyin":"Shūshu, nín hǎo!","exampleVi":"Cháu chào chú ạ!"},{"emoji":"📥","word":"收","pinyin":"shōu","pos":"Động từ","meaning":"nhận; thu, cất","example":"请把书收起来。","examplePinyin":"Qǐng bǎ shū shōu qǐlai.","exampleVi":"Hãy cất sách đi."},{"emoji":"🔁","word":"总","pinyin":"zǒng","pos":"Phó từ","meaning":"luôn, cứ","example":"他总忘记带伞。","examplePinyin":"Tā zǒng wàngjì dài sǎn.","exampleVi":"Anh ấy cứ quên mang ô."},{"emoji":"🌅","word":"起","pinyin":"qǐ","pos":"Động từ","meaning":"(sau động từ) nhắc đến; bắt đầu từ","example":"妈妈常说起你。","examplePinyin":"Māma cháng shuō qǐ nǐ.","exampleVi":"Mẹ thường nhắc đến bạn."},{"emoji":"🤝","word":"见面","pinyin":"jiànmiàn","pos":"Động từ","meaning":"gặp mặt","example":"我们明天见面。","examplePinyin":"Wǒmen míngtiān jiànmiàn.","exampleVi":"Ngày mai chúng ta gặp nhau."},{"emoji":"💧","word":"矿泉水","pinyin":"kuàngquánshuǐ","pos":"Danh từ","meaning":"nước khoáng","example":"请给我一瓶矿泉水。","examplePinyin":"Qǐng gěi wǒ yì píng kuàngquánshuǐ.","exampleVi":"Cho tôi một chai nước khoáng."},{"emoji":"⏰","word":"刚刚","pinyin":"gānggāng","pos":"Phó từ","meaning":"vừa mới","example":"他刚刚出去了。","examplePinyin":"Tā gānggāng chūqu le.","exampleVi":"Anh ấy vừa mới ra ngoài."},{"emoji":"🚗","word":"出发","pinyin":"chūfā","pos":"Động từ","meaning":"xuất phát","example":"我们八点出发。","examplePinyin":"Wǒmen bā diǎn chūfā.","exampleVi":"Chúng tôi xuất phát lúc tám giờ."},{"emoji":"⌛","word":"不久","pinyin":"bùjiǔ","pos":"Tính từ","meaning":"không lâu, chẳng bao lâu","example":"不久我们又见面了。","examplePinyin":"Bùjiǔ wǒmen yòu jiànmiàn le.","exampleVi":"Chẳng bao lâu chúng tôi lại gặp nhau."},{"emoji":"💥","word":"发生","pinyin":"fāshēng","pos":"Động từ","meaning":"xảy ra","example":"发生什么事了？","examplePinyin":"Fāshēng shénme shì le?","exampleVi":"Đã xảy ra chuyện gì?"},{"emoji":"🏠","word":"刚","pinyin":"gāng","pos":"Phó từ","meaning":"vừa mới","example":"我刚到家。","examplePinyin":"Wǒ gāng dào jiā.","exampleVi":"Tôi vừa về đến nhà."},{"emoji":"🔑","word":"只要","pinyin":"zhǐyào","pos":"Liên từ","meaning":"chỉ cần","example":"只要努力，就会进步。","examplePinyin":"Zhǐyào nǔlì, jiù huì jìnbù.","exampleVi":"Chỉ cần cố gắng thì sẽ tiến bộ."},{"emoji":"📚","word":"学期","pinyin":"xuéqī","pos":"Danh từ","meaning":"học kỳ","example":"这个学期我很忙。","examplePinyin":"Zhège xuéqī wǒ hěn máng.","exampleVi":"Học kỳ này tôi rất bận."},{"emoji":"🎓","word":"毕业","pinyin":"bìyè","pos":"Động từ","meaning":"tốt nghiệp","example":"我明年毕业。","examplePinyin":"Wǒ míngnián bìyè.","exampleVi":"Năm sau tôi tốt nghiệp."},{"emoji":"👶","word":"出生","pinyin":"chūshēng","pos":"Động từ","meaning":"sinh ra","example":"我出生在北京。","examplePinyin":"Wǒ chūshēng zài Běijīng.","exampleVi":"Tôi sinh ra ở Bắc Kinh."},{"emoji":"🕰️","word":"过去","pinyin":"guòqù","pos":"Danh từ","meaning":"quá khứ, trước đây","example":"过去这里没有学校。","examplePinyin":"Guòqù zhèlǐ méiyǒu xuéxiào.","exampleVi":"Trước đây ở đây không có trường học."},{"emoji":"💡","word":"懂得","pinyin":"dǒngde","pos":"Động từ","meaning":"hiểu, biết được","example":"他懂得很多道理。","examplePinyin":"Tā dǒngde hěn duō dàolǐ.","exampleVi":"Anh ấy hiểu nhiều đạo lý."},{"emoji":"🏃","word":"坚持","pinyin":"jiānchí","pos":"Động từ","meaning":"kiên trì, duy trì","example":"我坚持每天读中文。","examplePinyin":"Wǒ jiānchí měitiān dú Zhōngwén.","exampleVi":"Tôi kiên trì đọc tiếng Trung mỗi ngày."},{"emoji":"✔️","word":"完成","pinyin":"wánchéng","pos":"Động từ","meaning":"hoàn thành","example":"我完成作业了。","examplePinyin":"Wǒ wánchéng zuòyè le.","exampleVi":"Tôi làm xong bài tập rồi."},{"emoji":"🎯","word":"目标","pinyin":"mùbiāo","pos":"Danh từ","meaning":"mục tiêu","example":"我的目标是学好中文。","examplePinyin":"Wǒ de mùbiāo shì xué hǎo Zhōngwén.","exampleVi":"Mục tiêu của tôi là học tốt tiếng Trung."},{"emoji":"📈","word":"发展","pinyin":"fāzhǎn","pos":"Động từ","meaning":"phát triển","example":"这座城市发展很快。","examplePinyin":"Zhè zuò chéngshì fāzhǎn hěn kuài.","exampleVi":"Thành phố này phát triển rất nhanh."},{"emoji":"🧧","word":"春节","pinyin":"Chūnjié","pos":"Tên riêng","meaning":"Tết Nguyên đán","example":"春节我们一起吃饺子。","examplePinyin":"Chūnjié wǒmen yìqǐ chī jiǎozi.","exampleVi":"Tết Nguyên đán chúng tôi cùng ăn sủi cảo."}],"summary":"Bạch Gia Nguyệt lần đầu đón Tết Nguyên đán ở Trung Quốc tại nhà bạn học Lý Văn: nghe kể về phong tục gói sủi cảo xem Gala Tết, đến chúc Tết cô Trương chú Lý, xem lại tấm ảnh ngày Lý Văn lên đường du học, và hiểu ra bài học về sự kiên trì — chỉ cần luôn kiên trì thì sẽ hoàn thành được mục tiêu của mình.","structures":[{"han":"春节是中国最重要的节日","pinyin":"Chūnjié shì Zhōngguó zuì zhòngyào de jiérì","meaning":"Tết Nguyên đán là ngày lễ quan trọng nhất của Trung Quốc.","note":"Câu then chốt của bài"},{"han":"我刚刚看视频学会了包饺子","pinyin":"Wǒ gānggāng kàn shìpín xuéhuì le bāo jiǎozi","meaning":"Tôi vừa xem video và học được cách gói sủi cảo.","note":"Câu then chốt của bài"},{"han":"只要一直坚持，就能完成自己的目标","pinyin":"Zhǐyào yìzhí jiānchí, jiù néng wánchéng zìjǐ de mùbiāo","meaning":"Chỉ cần luôn kiên trì thì sẽ hoàn thành được mục tiêu của mình.","note":"Câu then chốt của bài"}],"natural":["刚才 vs 刚刚: 刚才 là danh từ thời gian, làm được định ngữ （刚才的电话 — cuộc gọi lúc nãy); 刚刚 là phó từ, chỉ đứng trước động từ. Không nói 刚刚的电话。","过年好！ là lời chúc Tết ngắn gọn, tự nhiên nhất khi gặp mặt; trang trọng hơn: 新年快乐 / 春节快乐.","说起 — 起 đặt sau động từ mang nghĩa “nhắc đến, bắt đầu nói về” （总听小文说起你); còn 从……起 lại chỉ điểm bắt đầu của thời gian.","只要……就…… đi với 坚持 tạo thành câu khích lệ rất hay gặp: 只要坚持，就能完成目标 — học thuộc cả cụm để dùng ngay."],"grammar":[{"title":"Số ước lượng — hai số liền kề + lượng từ/danh từ","formula":"Số + số liền kề （三四、五六、七八…) + lượng từ / danh từ","explain":"Đặt hai số liền nhau trước lượng từ hoặc danh từ để chỉ số lượng GẦN ĐÚNG, không chính xác: 七八天 ≈ khoảng 7–8 ngày.","examples":"春节大概放七八天假。(Chūnjié dàgài fàng qī bā tiān jià.) — Tết Nguyên đán được nghỉ khoảng bảy tám ngày. 教室里来了五六个学生。(Jiàoshì lǐ lái le wǔ liù ge xuésheng.) — Có khoảng năm sáu học sinh đến lớp. 这些照片是三四年前照的吧？(Zhè xiē zhàopiàn shì sān sì nián qián zhào de ba?) — Những bức ảnh này chụp khoảng ba bốn năm trước phải không?","tip":"","error":"Không chèn 和 giữa hai số, và đừng hiểu thành số ghép: 七八天 không phải 78 ngày."},{"title":"“刚才” và “刚刚”","formula":"刚才 (danh từ chỉ thời gian) · 刚刚 (phó từ, đứng sau chủ ngữ)","explain":"刚才 = “lúc nãy, vừa nãy” (thường vài phút trước); đứng được đầu câu, sau chủ ngữ, và làm định ngữ （刚才的电话). 刚刚 = “vừa mới”, đứng ngay trước động từ; quãng thời gian do ngữ cảnh quyết định — có thể vài phút, vài ngày, thậm chí vài tháng.","examples":"刚才的电话是我妈妈打来的。(Gāngcái de diànhuà shì wǒ māma dǎ lái de.) — Cuộc gọi lúc nãy là mẹ tôi gọi tới. 我刚才看过一遍，不想再看了。(Wǒ gāngcái kàn guò yī biàn, bù xiǎng zài kàn le.) — Tôi vừa xem qua một lượt rồi, không muốn xem lại nữa. 我刚刚看视频学会了包饺子。(Wǒ gānggāng kàn shìpín xuéhuì le bāo jiǎozi.) — Tôi vừa xem video và học được cách gói sủi cảo. 他刚刚来北京两个月。(Tā gānggāng lái Běijīng liǎng ge yuè.) — Anh ấy mới đến Bắc Kinh được hai tháng.","tip":"","error":"Trong cụm danh từ phải dùng 刚才的， không dùng 刚刚的 thay thế."},{"title":"Câu điều kiện “只要……，就……”","formula":"只要 + điều kiện đủ，就 + kết quả","explain":"只要 nêu điều kiện ĐỦ, 就 nêu kết quả: chỉ cần điều kiện được thỏa mãn thì kết quả có thể xảy ra.","examples":"我只要几天不跟他视频，就很想他。(Wǒ zhǐyào jǐ tiān bù gēn tā shìpín, jiù hěn xiǎng tā.) — Chỉ cần vài ngày không gọi video với anh ấy là tôi rất nhớ anh ấy. 只要你同意，我们就这么决定了。(Zhǐyào nǐ tóngyì, wǒmen jiù zhème juédìng le.) — Chỉ cần bạn đồng ý thì chúng ta chốt như vậy nhé. 只要你坚持每天早睡，身体就一定会好起来。(Zhǐyào nǐ jiānchí měitiān zǎoshuì, shēntǐ jiù yídìng huì hǎo qǐlai.) — Chỉ cần bạn kiên trì ngủ sớm mỗi ngày thì sức khỏe sẽ tốt dần lên.","tip":"","error":"Phân biệt với 只有……才…… (Bài 17 — điều kiện cần, duy nhất): 只有买票，才能进去 (phải mua vé mới vào được) ≠ 只要买了票，就可以进去 (chỉ cần mua vé là vào được). Không ghép lẫn thành 只要……才…… hay 只有……就……."},{"title":"Cấu trúc cố định “从……起”","formula":"从 + mốc thời gian / sự việc + 起","explain":"“Kể từ…” — xác định điểm bắt đầu của một hành động hoặc trạng thái, thường ngụ ý trạng thái đó kéo dài từ mốc ấy. Gần nghĩa 从……开始； kể chuyện hay dùng 从那以后 (từ đó về sau).","examples":"他从那时起就努力学习了。(Tā cóng nà shí qǐ jiù nǔlì xuéxí le.) — Từ lúc đó, anh ấy bắt đầu chăm chỉ học. 从那天起，我们就变成了好朋友。(Cóng nà tiān qǐ, wǒmen jiù biànchéng le hǎo péngyou.) — Từ ngày hôm đó, chúng tôi trở thành bạn tốt. 从那次旅游起，我对中国文化更有兴趣了。(Cóng nà cì lǚyóu qǐ, wǒ duì Zhōngguó wénhuà gèng yǒu xìngqù le.) — Từ chuyến du lịch lần đó, tôi càng hứng thú với văn hóa Trung Quốc hơn.","tip":"","error":"Mốc sau 从 phải là một thời điểm/sự việc xác định được; trạng thái theo sau thường mang tính kéo dài, không phải hành động chớp nhoáng."}]}];
window.analysisDetails={"10":{"translation":["Trong giờ học, học sinh vừa nghe giáo viên giảng vừa ghi chép cẩn thận. Chỗ nào nghe chưa rõ hoặc câu nào khó hiểu thì cần hỏi lại, nghe thêm một lần và ghi cho đầy đủ; học nghiêm túc như vậy mới nắm được bài.","Có những môn như Toán hay Lịch sử khiến người học cảm thấy khó, kết quả chỉ ở mức bình thường. Giáo viên nhắc rằng muốn tiến bộ thì phải ôn tập đều, đọc lại nội dung đã học và hoàn thành bài tập thay vì chỉ nhìn qua một lần.","Một học sinh đang mượn cuốn sách của giáo viên. Hai người thống nhất rằng ngày mai em sẽ trả lại sách; câu dặn 你明天再把书还给我 đặt cuốn sách lên trước bằng 把 rồi nói rõ hành động cuối cùng là trả về cho người cho mượn.","Toàn bài nối các việc rất quen thuộc ở trường — nghe giảng, ghi bài, hỏi chỗ chưa hiểu, làm xong bài tập và giữ lời khi mượn sách. Qua câu chuyện, người học vừa ôn từ vựng lớp học vừa thấy cách câu chữ 把 diễn tả một đồ vật cụ thể được xử lý đến kết quả nào."],"breakdown":[{"zh":"你明天再把书还给我","vi":"Ngày mai em hãy trả sách lại cho cô nhé.","explain":"明天 là thời gian; 再 cho biết hành động để lúc sau mới làm; 把书 đưa đồ vật cụ thể lên trước; 还给我 nêu kết quả và người nhận."},{"zh":"把作业写完","vi":"Làm xong bài tập.","explain":"Câu 把 cần kết quả rõ. 写完 cho biết bài tập được xử lý đến trạng thái hoàn tất; chỉ nói 把作业写 là chưa đủ."},{"zh":"再说一遍","vi":"Nói lại một lượt nữa.","explain":"再 dùng cho hành động chưa xảy ra ở thời điểm nói nhưng sẽ lặp lại. 遍 đếm trọn một lượt từ đầu đến cuối."},{"zh":"老师讲得很清楚","vi":"Giáo viên giảng rất rõ.","explain":"得 nối động từ 讲 với lời nhận xét về mức độ 清楚. Đây là bổ ngữ trình độ, khác với 得 děi “phải”."}],"reading":["Mạch ý: nghe chưa rõ → hỏi/ôn lại → xử lý bài tập, sách vở → cải thiện kết quả.","把、还给、写完 thường đi cùng nhau vì đều nói kết quả tác động lên đồ vật.","Khi nghe, phân biệt 再 “lần sau/làm lại” với 在 “ở/tại”."]},"11":{"translation":["Ở nơi làm việc, mọi người phải chuẩn bị cho một cuộc họp: xác nhận thời gian, địa điểm và phòng họp, rồi gửi thông tin cần thiết qua email để đồng nghiệp cùng nắm được. Những từ như 会议, 地点, 会议室 và 邮箱 vì thế xuất hiện trong cùng một mạch công việc.","Trong lúc chuẩn bị, máy tính xách tay gặp trục trặc. Sau khi xem xét tình hình, một người nhận ra mình không có cách tự giải quyết nên nói 看来我没办法解决这个问题 — xem ra vấn đề đã vượt quá khả năng của mình.","Thay vì cố làm một mình, người ấy lịch sự hỏi đồng nghiệp có sẵn lòng giúp không. Nếu điều kiện chưa cho phép xử lý ngay thì chỉ còn cách đổi sang thời điểm khác, chẳng hạn 只能明天去 — chỉ có thể đi vào ngày mai.","Câu chuyện còn mở rộng sang việc xin nghỉ và nghỉ phép. Khi cân nhắc công việc, cơ hội mới và cuộc sống cá nhân, mỗi người có thể nêu góc nhìn riêng bằng 对……来说; với người trong bài, sức khỏe vẫn là điều quan trọng nhất."],"breakdown":[{"zh":"看来我没办法解决这个问题","vi":"Xem ra tôi không có cách giải quyết vấn đề này.","explain":"看来 mở đầu một phán đoán dựa trên tình hình quan sát được. 没办法 không chỉ thiếu phương pháp mà còn có sắc thái “đành chịu”."},{"zh":"你愿意帮助我吗？","vi":"Bạn có sẵn lòng giúp tôi không?","explain":"愿意 hỏi về ý muốn tự nguyện nên lịch sự hơn mệnh lệnh. Trong công sở, câu này phù hợp khi nhờ hỗ trợ."},{"zh":"只能明天去","vi":"Chỉ có thể đi vào ngày mai.","explain":"只能 giới hạn lựa chọn: ngoài ngày mai ra không còn phương án phù hợp. Nó thường xuất hiện sau khi nêu một trở ngại."},{"zh":"对我来说，健康最重要","vi":"Đối với tôi, sức khỏe là quan trọng nhất.","explain":"对……来说 đặt góc nhìn lên trước, vế sau mới là nhận xét. Cấu trúc này giúp nói quan điểm cá nhân rõ mà không áp đặt."}],"reading":["Mạch ý: có công việc cần xử lý → phát hiện trở ngại → đánh giá tình hình → nhờ hỗ trợ/chọn phương án.","会议、经理、同事、邮箱 tạo cụm từ vựng công sở nên học theo ngữ cảnh.","看来 là phán đoán; không dịch máy móc từng chữ thành “nhìn đến”."]},"12":{"translation":["Hai người bắt đầu từ những điều nhìn thấy quanh mình rồi nói về thời tiết của mùa hiện tại. Mới lúc nãy trời còn bình thường, nhưng mùa này thời tiết đổi rất nhanh nên không thể chỉ dựa vào cảm giác lúc vừa bước ra ngoài.","Chẳng bao lâu gió nổi lên và trời bắt đầu mưa. Trước sự thay đổi bất ngờ ấy, mọi người nhắc nhau mang ô hoặc mặc áo mưa; câu 把伞带上 nhấn mạnh việc phải mang chiếc ô theo bên mình.","Từ một cơn mưa bất chợt, cuộc trò chuyện chuyển sang bốn mùa trong năm. Mùa xuân có hoa nở, mùa hè nóng, mùa thu mát và lá dần đổi màu, còn mùa đông lạnh; mỗi mùa đều có dấu hiệu riêng để nhận ra.","Mạch bài đi từ quan sát thời tiết trước mắt đến bức tranh rộng hơn về bốn mùa. Ý thực tế rút ra là nên chú ý tin thời tiết trước khi ra ngoài, vì trời có thể chuyển gió, chuyển mưa hoặc trở lạnh rất nhanh."],"breakdown":[{"zh":"这个季节天气变化很快","vi":"Thời tiết mùa này thay đổi rất nhanh.","explain":"这个季节 là khung thời gian/chủ đề; 天气 là chủ ngữ của 变化; 很快 bổ sung tốc độ thay đổi."},{"zh":"下起雨来了","vi":"Trời bắt đầu mưa rồi.","explain":"V + 起来 diễn tả hành động bắt đầu và phát triển. Với 下雨, tân ngữ 雨 chen vào giữa: 下起雨来."},{"zh":"把伞带上","vi":"Mang ô theo đi.","explain":"把 đưa 伞 lên trước; 带上 là mang theo để ở trạng thái có sẵn bên mình. 上 ở đây là bổ ngữ kết quả, không phải “ở trên”."},{"zh":"天气变冷了","vi":"Thời tiết trở lạnh rồi.","explain":"变 + tính từ diễn tả chuyển sang trạng thái mới. 了 cuối câu nhấn mạnh sự thay đổi đã xuất hiện."}],"reading":["Mạch ý: quan sát hiện tại → thời tiết đổi bất ngờ → chuẩn bị đồ dùng → khái quát bốn mùa.","刮风、下雨、变冷 là ba cụm cố định; không ghép từng chữ theo tiếng Việt.","Nghe rõ 一把伞: 把 ở đây là lượng từ của đồ có tay cầm, không phải câu chữ 把."]},"13":{"translation":["Một gia đình mới chuyển đến sống gần nhà và trở thành hàng xóm. Khi biết họ đến từ nước Anh, mọi người vừa tò mò vừa thân thiện, chủ động làm quen để những người mới không cảm thấy xa lạ ở nơi ở mới.","Lời mời 有空的话，就来我家做客 mở ra một cuộc gặp gần gũi: nếu có thời gian thì hãy đến nhà chơi. Người được mời là khách đến thăm, còn chủ nhà chuẩn bị đón tiếp và đãi khách chu đáo.","Trong bữa ăn, mọi người vừa ăn vừa trò chuyện. Câu chuyện xoay quanh phong tục, cách tiếp khách, sự khác nhau giữa món ăn miền Nam và miền Bắc, đồng thời gợi ra những điểm khác biệt giữa văn hóa phương Đông và phương Tây.","Nhờ không khí cởi mở ấy, hai bên hiểu nhau hơn và người hàng xóm mới dần hòa nhập với cuộc sống mới. Toàn bài kể một cuộc làm quen ấm áp, đồng thời giúp phân biệt rõ 做客 — đến nhà người khác làm khách — với 请客 — đứng ra mời và đãi khách."],"breakdown":[{"zh":"我的新邻居来自英国。","vi":"Hàng xóm mới của tôi đến từ Anh.","explain":""},{"zh":"有空的话，就来我家做客。","vi":"Nếu rảnh thì đến nhà tôi chơi nhé.","explain":""},{"zh":"我们一边吃饭，一边聊天儿。","vi":"Chúng tôi vừa ăn vừa trò chuyện.","explain":""}],"reading":["请客 — văn hóa đãi khách: ở Trung Quốc, người mời khách thường giành trả tiền bằng được — đó là lịch sự, không phải khoe của. Nói 我请客 (để tôi mời) là câu cửa miệng khi đi ăn cùng bạn bè.","做客 vs 请客: cặp từ dễ nhầm — 做客 là \"làm khách\" (đi chơi nhà người ta), 请客 là \"đãi khách\" (mời người ta). Nhớ: mình 请客, mình đi 做客.","的话 — nêu điều kiện mềm mại: 有空的话…… (nếu rảnh thì……) nghe tự nhiên, thân thiện hơn nhiều so với cứng nhắc 如果……. Trong văn nói hàng ngày, người TQ dùng 的话 cực kỳ nhiều.","边……边……: dạng rút gọn khẩu ngữ của 一边……一边…… — 边吃边聊 (vừa ăn vừa nói chuyện) là câu người TQ nói hằng ngày."]},"14":{"translation":["Một bạn đến thư viện để tìm cuốn sách mình cần, nhưng cuốn đó không còn trên giá vì đã bị người khác mượn đi. Câu 这本书被别人借走了 tập trung vào cuốn sách — đối tượng chịu tác động — nên dùng 被 để kể lại việc đã xảy ra với nó.","Không thể lấy đúng cuốn sách ngay, bạn ấy phải nghĩ đến phương án khác: tìm một cuốn thay thế, tra từ điển hoặc đọc tài liệu điện tử. Công việc được sắp theo thứ tự rõ ràng, trước tiên đến thư viện mượn sách, sau đó mới đi bơi.","Phần sau chuyển sang việc chuẩn bị tiết mục văn nghệ đón năm mới. Một bạn được giao hát trước hiệu trưởng và nhiều người trong trường nên cảm thấy căng thẳng, lo rằng mình sẽ không thể hiện tốt.","Các bạn xung quanh liền động viên: có gì mà phải hồi hộp, mọi người đều thích nghe bạn hát. Nhờ lời trấn an ấy, không khí trở nên nhẹ nhàng hơn; bài học vừa giới thiệu câu bị động 被, vừa cho thấy cách hỏi 怎么办 và cách khích lệ một người đang lo lắng."],"breakdown":[{"zh":"这本书被别人借走了。","vi":"Cuốn sách này bị người khác mượn mất rồi.","explain":""},{"zh":"紧张什么啊，我们都喜欢听你唱歌。","vi":"Có gì mà hồi hộp, chúng tôi đều thích nghe bạn hát.","explain":""},{"zh":"先去图书馆借书，然后去游泳。","vi":"Đến thư viện mượn sách trước, rồi đi bơi.","explain":""}],"reading":["被 — câu bị động \"quốc dân\": 把 người/vật chịu tác động lên làm chủ ngữ. Nhưng lưu ý quan trọng: không phải câu \"bị/được\" tiếng Việt nào cũng dịch bằng 被 — nhiều khi nói chủ động gọn và tự nhiên hơn (ví dụ \"cửa đóng rồi\" nói 门关了 là đủ).","被 không chỉ chuyện xấu: 他被表扬了 (anh ấy ĐƯỢC khen) — 被 dùng cho cả điều tốt khi muốn nhấn mạnh \"nhận được tác động\".","×什么啊 — trấn an kiểu phản vấn: 紧张什么啊 = \"có gì mà hồi hộp!\". Giữa bạn bè thân thì ấm áp, nhưng với người chưa thân có thể nghe gắt — lúc đó dùng 别紧张，你唱得很好 sẽ an toàn hơn.","怎么办: câu hỏi \"làm sao đây\" đa năng nhất tiếng Trung — gặp rắc rối gì cũng dùng được."]},"15":{"translation":["Một bạn kể về quãng thời gian sống ở Nam Kinh và những hình ảnh đã trở nên quen thuộc trong đời sống hằng ngày. Sau giờ học có thể ra công viên, trên đường phố thường gặp người dân đi lại và những người lớn tuổi thong thả tản bộ.","Vì đã sống ở đó lâu, hiểu nhịp sống và có nhiều kỷ niệm với thành phố, bạn ấy vui vẻ tự nhận mình là 半个南京人 — “nửa người Nam Kinh”. Cách nói này không mang nghĩa đếm chính xác, mà thể hiện cảm giác đã hòa nhập và gần như trở thành người địa phương.","Câu chuyện cũng gợi ra cảm giác thời gian trôi nhanh trong sinh hoạt thường ngày: chẳng mấy chốc trời đã tối. Những chi tiết nhỏ như công viên, đường phố và buổi chiều giúp lời kể về thành phố trở nên gần gũi hơn.","Ở phần mở rộng, bài nhắc đến Hoàng Hà và cách người Trung Quốc nhìn dòng sông này như một người mẹ. Qua hai lớp nội dung — tình cảm với nơi mình sống và hình ảnh Hoàng Hà — bài học nhấn mạnh sự gắn bó với quê hương, thành phố và ký ức chung."],"breakdown":[{"zh":"我是半个南京人。","vi":"Tôi là nửa người Nam Kinh.","explain":""},{"zh":"在我们中国人看来，黄河像妈妈一样。","vi":"Theo người Trung Quốc chúng tôi, Hoàng Hà như người mẹ.","explain":""},{"zh":"不一会儿，天就黑了。","vi":"Chẳng mấy chốc trời đã tối.","explain":""}],"reading":["半个……人 — cách nói hóm hỉnh: 半个南京人 (nửa người Nam Kinh) — người sống lâu ở một nơi, hòa nhập đến mức \"thành người địa phương\". Cách nói dí dỏm, thân thiện, dùng được cho mọi thành phố: 半个北京人, 半个上海人.","根据 vs 因为: 根据 dẫn CĂN CỨ (quy định, nhu cầu, tình hình) — 根据要求 (theo yêu cầu); 因为 nêu NGUYÊN NHÂN. Nói 根据我很忙 để chỉ \"vì tôi bận\" là sai — phải dùng 因为.","Ba cách nêu quan điểm: 在我看来 (theo nhận định của tôi — trang trọng), 我觉得 (tôi thấy — gần gũi, dùng nhiều nhất), 对我来说 (đối với tôi — góc độ cảm nhận). Dùng đúng chỗ là lên trình ngay.","Số từ + lượng từ lặp lại: 一点儿一点儿 (từng chút một), 一天一天 (từng ngày) — cách diễn đạt giàu hình ảnh, rất văn học. Khẩu ngữ có thể lược 地."]},"16":{"translation":["Câu chuyện mở đầu ở một quán có nuôi mèo. Chị cả Lưu Tiểu Tuyết trầm trồ trước con mèo xinh xắn của quán và được nhân viên kể: mèo được nuôi hơn một năm, ngày đầu mới đến vừa bẩn vừa nhỏ, nhờ được chăm sóc chu đáo mà giờ sạch sẽ, đáng yêu, lại nhận ra hết mọi người trong quán — lúc thì nằm ngủ bên chân khách, lúc lại bò lên người khách. Nghe vậy, Tiểu Tuyết ngỏ ý xin mẹ cho nuôi một con mèo, nhưng mẹ Vương Nhất Tuyết từ chối khéo vì nhà không có thời gian chăm sóc, và hứa cuối tuần sẽ đưa hai chị em đi vườn thú Bắc Kinh xem động vật.","Trước chuyến đi, cậu em Lưu Tiểu Minh hỏi mẹ dồn dập như một cuốn “mười vạn câu hỏi vì sao”. Vì sao lại gọi là “gấu trúc lớn” trong khi nó chẳng có họ hàng gì với mèo — thật ra tên đúng phải là “gấu mèo lớn”? Vì sao gấu trúc hầu như chỉ ăn trúc dù cũng ăn được thịt? Và vì sao gấu trúc được coi là quốc bảo? Mẹ kiên nhẫn giải thích: trên toàn thế giới chỉ Trung Quốc mới có gấu trúc hoang dã. Riêng chuyện có gấu trúc ra nước ngoài — cũng chính là tên của bài học — mẹ bảo phải từ từ mới kể hết được.","Đến khu gấu trúc trong vườn thú, hai chị em tha hồ ngắm: một con lúc trèo lên, lúc nhảy xuống, đáng yêu vô cùng; một con dường như chưa ăn no, đứng dậy há miệng tìm đồ ăn; con bên cạnh thì nửa ngày không động đậy, chắc đang ngủ say. Mẹ cho biết nói chung gấu trúc mỗi ngày ngủ rất nhiều giấc, thời gian còn lại phần lớn dành cho ăn. Tiểu Tuyết bật cười thốt lên đời gấu trúc thật sướng, rồi nhờ mẹ chụp ảnh cho mình cùng những chú gấu trúc.","Bài học khép lại bằng lời kể của mẹ Vương Nhất Tuyết về vườn thú Bắc Kinh: đây là một vườn thú rất nổi tiếng của Trung Quốc với vô cùng nhiều loài vật, nhưng được người lớn và trẻ em yêu thích nhất vẫn là gấu trúc — ngày nào khu gấu trúc cũng đông du khách mang máy ảnh đến chụp hình. Vườn thú mở cửa từ 7 giờ rưỡi sáng đến 7 giờ tối; mùa đông ít khách hơn mùa hè nên đóng cửa sớm hơn thường lệ một tiếng. Theo mẹ, ai lần đầu đến Bắc Kinh du lịch thì đi vườn thú cùng gia đình là một lựa chọn rất đáng thử."],"breakdown":[{"zh":"它一会儿在你脚边睡觉，一会儿在你身上爬。","vi":"Nó lúc thì ngủ bên chân bạn, lúc lại bò trên người bạn.","explain":"Mẫu 一会儿……一会儿……: hai trạng thái luân phiên nhau, không xảy ra cùng lúc."},{"zh":"全世界只有中国有野生大熊猫。","vi":"Trên toàn thế giới chỉ Trung Quốc mới có gấu trúc hoang dã.","explain":"Đây chính là lý do gấu trúc được coi là quốc bảo của Trung Quốc."},{"zh":"一般来说，熊猫每天要睡很多次觉。","vi":"Nói chung, gấu trúc mỗi ngày ngủ rất nhiều giấc.","explain":"一般来说 mở đầu một nhận định chung; 睡很多次觉 là từ li hợp 睡觉 được chèn cụm số lần vào giữa."},{"zh":"冬天比夏天早关门一个小时。","vi":"Mùa đông đóng cửa sớm hơn mùa hè một tiếng.","explain":"So sánh chênh lệch: 早 đặt trước động từ 关门， còn 一个小时 là độ chênh, không phải tổng thời gian."}],"reading":["一会儿……一会儿…… khác 一边……一边……: một mẫu là LUÂN PHIÊN (lúc này lúc kia), một mẫu là ĐỒNG THỜI (vừa… vừa…). Nhầm hai mẫu này là lỗi kinh điển.","关于 vs 对： 关于 nêu CHỦ ĐỀ (cuốn sách về động vật — 关于动物的书); 对 nêu THÁI ĐỘ với đối tượng （对中文感兴趣 — hứng thú với tiếng Trung).","大熊猫 hay 大猫熊？ Theo cấu tạo họ hàng, tên 'đúng' là 大猫熊 (họ gấu), nhưng cả thế giới quen gọi 大熊猫 — chi tiết vui được giải thích ngay trong bài khóa 16-2.","睡很多次觉 — từ li hợp 睡觉 có thể chèn cụm số lần vào giữa: 睡一次觉、睡很多次觉. Tương tự: 洗澡 → 洗个澡."]},"17":{"translation":["Bài học mở đầu trước cửa văn phòng của thầy Lý. Một người bạn học của Lưu Tiểu Tuyết cứ đi thẳng về phía trước dù đã đến nơi, vì trong lòng đang lo lắng: gần đây bạn ấy làm sai mấy việc đơn giản, sợ thầy Lý giận và cho rằng mình không nghiêm túc. Tiểu Tuyết trấn an rằng làm sai là chuyện rất thường gặp; có những người tuy thông minh nhưng lại mắc lỗi ở việc đơn giản, chính vì cho rằng việc dễ nên không nghiêm túc làm. Nghe xong, bạn học thừa nhận người đó đúng là mình, và quyết tâm từ nay học hỏi nhiều hơn từ những người nghiêm túc — cũng là thông điệp trong tên bài.","Ở thư viện, Bạch Gia Nguyệt bất ngờ khi mấy ngày liền gặp Trần Thiên Trung đến học, trong khi các bạn học đều đang khắp nơi tìm việc làm. Thiên Trung chia sẻ anh chưa muốn đi làm ngay mà muốn tiếp tục học lên, và bố mẹ cũng đồng ý; chỉ là anh chưa nghĩ ra nên học gì. Gia Nguyệt gợi ý: anh thích dùng máy tính như vậy, sao không tìm đọc các cuốn sách liên quan đến máy tính — và Thiên Trung sực nhớ ra trong thư viện có một phòng chuyên loại sách đó.","Qua cuộc gọi với Lý Văn, chuyện du học của Thiên Trung rõ ràng hơn. Điện thoại của anh tắt máy chỉ vì hết pin. Lý Văn cho biết hôm kia gặp Gia Nguyệt và nghe chuyện anh định tiếp tục du học. Thiên Trung thú thật: mình chưa nghĩ xong sẽ học gì, lại càng chưa nghĩ xong sẽ đi nước nào. Lý Văn gợi ý đến Trung Quốc học tiếng Trung — chẳng hạn Bắc Kinh, Thượng Hải có nhiều trường tốt và đông du học sinh — và hứa giới thiệu mấy trang web hữu ích để anh tra cứu.","Bài học kết lại bằng suy nghĩ của chính Trần Thiên Trung khi cuộc sống đại học sắp kết thúc. Dạo gần đây anh thường xuyên bị hỏi “sau này bạn muốn làm gì?” — một câu hỏi nghe đơn giản mà không dễ trả lời. Các bạn học mỗi người một hướng: người tiếp tục học, người du học, người tìm việc trước. Thiên Trung cho rằng chỉ khi nghĩ rõ bản thân thật sự thích gì thì mới đưa ra được lựa chọn phù hợp nhất — nhưng với anh, riêng việc nghĩ rõ điều đó đã là một vấn đề khó."],"breakdown":[{"zh":"别再向前走了，李老师的办公室已经到了。","vi":"Đừng đi về phía trước nữa, văn phòng thầy Lý đến rồi.","explain":"向 + phương hướng + động từ: 向前走 là đi về phía trước; 别……了 ngăn hành động tiếp tục."},{"zh":"你不是喜欢玩电脑吗？","vi":"Chẳng phải bạn thích dùng máy tính sao?","explain":"Câu phản vấn 不是……吗？: hình thức phủ định nhưng ý là khẳng định, dùng để nhắc lại và gợi ý."},{"zh":"我还没想好学什么，更没想好去哪个国家。","vi":"Tôi chưa nghĩ xong học gì, lại càng chưa nghĩ xong đi nước nào.","explain":"……，更…… đẩy ý lên thêm một mức: việc ở vế sau còn “chưa” hơn việc ở vế trước."},{"zh":"只有想清楚自己真正喜欢什么，才能做出最合适的选择。","vi":"Chỉ khi nghĩ rõ mình thật sự thích gì mới chọn được lựa chọn phù hợp nhất.","explain":"只有……，才……: vế sau 只有 là điều kiện cần, không thể thiếu để có kết quả."}],"reading":["向……学习 là cụm nên thuộc lòng: “học hỏi ai đó”. Đừng nói 学向 ai — 向 luôn đứng trước đối tượng, động từ 学习 theo sau.","不是……吗？ nghe KHẲNG ĐỊNH hơn một câu hỏi thật: dùng để nhắc lại hoặc nhấn mạnh. Với người chưa thân, giọng điệu dễ bị hiểu là trách móc.","可是 là “nhưng” rất khẩu ngữ, thường đứng đầu vế sau: 是，可是我还没想好…… — nhẹ và tự nhiên hơn 但是 trong văn nói hằng ngày.","只有……才…… (Bài 17, điều kiện CẦN) và 只要……就…… (Bài 18, điều kiện ĐỦ) là cặp câu điều kiện kinh điển của HSK 3 — học liền hai bài để so sánh."]},"18":{"translation":["Bài học mở đầu bằng cuộc trò chuyện trước Tết giữa Bạch Gia Nguyệt — du học sinh lần đầu đón Tết ở Trung Quốc — và bạn học Lý Văn. Lý Văn giới thiệu Tết Nguyên đán là ngày lễ quan trọng nhất của Trung Quốc; mọi người thường về nhà đón Tết cùng gia đình. Nhà anh có thói quen vừa gói sủi cảo vừa xem chương trình Gala Tết, thức đến sau 12 giờ đêm mới ngủ, và kỳ nghỉ Tết thường kéo dài khoảng bảy tám ngày.","Đến ngày Tết, Gia Nguyệt đến nhà Lý Văn chúc Tết, mang theo món quà đã chuẩn bị và gửi lời “Chúc mừng năm mới” tới cô Trương và chú Lý. Bố mẹ Lý Văn đón tiếp cô rất niềm nở: mẹ anh nói vẫn thường nghe con trai nhắc đến cô, hôm nay cuối cùng mới có dịp gặp mặt. Trên bàn có trà và nước khoáng để khách tự nhiên dùng. Khi biết sủi cảo sắp gói xong, Gia Nguyệt vui vẻ khoe mình vừa xem video học được cách gói sủi cảo và xin được gói cùng mọi người — chi tiết làm nên tên bài học.","Trong lúc trò chuyện, cô Trương cho Gia Nguyệt xem tấm ảnh gia đình chụp ở sân bay khi tiễn Lý Văn xuất phát đi du học ba bốn năm trước. Người mẹ xúc động nói thời gian trôi nhanh như mới hôm qua; ngày con mới xa nhà bà rất không quen, chỉ cần vài ngày không gọi video là nhớ con vô cùng. Gia Nguyệt an ủi: chỉ còn một học kỳ cuối nữa là Lý Văn tốt nghiệp và sẽ sớm trở về.","Bài học khép lại bằng lời kể của Gia Nguyệt. Điều khiến cô vui nhất trong chuyến đi này là được quen biết bố mẹ Lý Văn. Họ cho cô xem ảnh Lý Văn lúc nhỏ và kể nhiều chuyện ngày xưa: thời trung học anh đã muốn học y, từ lúc đó chăm chỉ học hành, đến năm lớp 12 nhờ thành tích đặc biệt tốt mà giành được cơ hội du học. Từ tấm gương của bạn, Gia Nguyệt hiểu ra một điều: chỉ cần luôn kiên trì thì sẽ hoàn thành được mục tiêu của mình, và cô tin sau này Lý Văn sẽ còn phát triển tốt hơn nữa."],"breakdown":[{"zh":"春节大概放七八天假。","vi":"Tết được nghỉ khoảng bảy tám ngày.","explain":"七八天 là số ước lượng: hai số liền kề chỉ khoảng 7–8 ngày, không phải 78 ngày."},{"zh":"我刚刚看视频学会了包饺子。","vi":"Tôi vừa xem video và học được cách gói sủi cảo.","explain":"刚刚 là phó từ “vừa mới”, đứng sau chủ ngữ, ngay trước động từ."},{"zh":"只要几天不跟他视频，就很想他。","vi":"Chỉ cần vài ngày không gọi video với anh ấy là rất nhớ anh ấy.","explain":"只要……，就……: điều kiện đủ — thỏa điều kiện là kết quả xảy ra."},{"zh":"他从那时起就努力学习了。","vi":"Từ lúc đó, anh ấy bắt đầu chăm chỉ học.","explain":"从……起 xác định điểm bắt đầu và ngụ ý trạng thái kéo dài từ mốc đó."}],"reading":["刚才 vs 刚刚: 刚才 là danh từ thời gian, làm được định ngữ （刚才的电话 — cuộc gọi lúc nãy); 刚刚 là phó từ, chỉ đứng trước động từ. Không nói 刚刚的电话。","过年好！ là lời chúc Tết ngắn gọn, tự nhiên nhất khi gặp mặt; trang trọng hơn: 新年快乐 / 春节快乐.","说起 — 起 đặt sau động từ mang nghĩa “nhắc đến, bắt đầu nói về” （总听小文说起你); còn 从……起 lại chỉ điểm bắt đầu của thời gian.","只要……就…… đi với 坚持 tạo thành câu khích lệ rất hay gặp: 只要坚持，就能完成目标 — học thuộc cả cụm để dùng ngay."]}};
window.dictations={"10":[["老师讲得很清楚，我也认真地记了笔记。","Giáo viên giảng rất rõ, tôi cũng nghiêm túc ghi chép.","清楚 · 认真 · 笔记"],["在工作上认真的人，在学习上也不会差。","Người nghiêm túc trong công việc thì trong học tập cũng không kém.","在……上 · 差 · 认真"],["请把黑板上的三个句子抄到笔记本上。","Hãy chép ba câu trên bảng vào vở.","把 · 黑板 · 句子"],["这道数学题太难，我看了两遍还是不明白。","Bài toán này quá khó, tôi xem hai lượt vẫn không hiểu.","数学 · 难 · 遍 · 明白"],["在这次考试中，他的数学成绩提高了很多。","Trong kỳ thi lần này, thành tích Toán của cậu ấy đã tiến bộ rất nhiều.","在……中 · 提高 · 数学"],["你先把作业写完，明天再把书还给我。","Em làm xong bài tập trước, ngày mai hãy trả sách cho cô.","把 · 作业 · 还给"],["为了提高外语水平，他每天练习一段对话。","Để nâng cao trình độ ngoại ngữ, cậu ấy luyện một đoạn hội thoại mỗi ngày.","提高 · 外语 · 练习 · 对话"],["在老师的帮助下，这道题我现在明白了。","Nhờ thầy giúp đỡ, bài này giờ tôi đã hiểu rồi.","在……下 · 明白"],["我遇到不清楚的问题，就去办公室问老师。","Gặp vấn đề chưa rõ, tôi liền đến văn phòng hỏi giáo viên.","遇到 · 清楚 · 办公室"],["复习的时候，最好把重要的内容再读一遍。","Khi ôn bài, tốt nhất hãy đọc lại nội dung quan trọng một lượt.","复习 · 把 · 遍"],["这本历史书我还没看完，后天还给你可以吗？","Tôi chưa đọc xong sách lịch sử này, ngày kia trả bạn được không?","历史 · 后天 · 还给"],["别把这本书带回家，这是办公室的，大家都要用。","Đừng mang cuốn sách này về nhà, sách này là của văn phòng, mọi người đều phải dùng.","把 · 办公室"],["老师要求我们用新词写五个完整的句子。","Giáo viên yêu cầu chúng tôi dùng từ mới viết năm câu hoàn chỉnh.","要求 · 句子"],["他的数学成绩一般，但是学习态度很认真。","Thành tích Toán của cậu ấy bình thường nhưng thái độ học rất nghiêm túc.","数学 · 一般 · 认真"],["当然，你先把句子写在笔记本上，再读给我听。","Đương nhiên, em hãy viết câu vào vở trước, rồi đọc cho cô nghe.","当然 · 把 · 句子"],["请翻到第十二页，我们一起读第二段对话。","Hãy mở trang 12, chúng ta cùng đọc đoạn hội thoại thứ hai.","页 · 对话"],["我没把今天的作业带来，真不好意思。","Tôi không mang bài tập hôm nay đến, thật ngại quá.","把 · 作业"],["只要继续努力，你的中文一定会提高。","Chỉ cần tiếp tục nỗ lực, tiếng Trung của bạn chắc chắn sẽ tiến bộ.","努力 · 提高"],["学外语不但要记单词，还要多听、多说。","Học ngoại ngữ không chỉ cần nhớ từ mà còn phải nghe và nói nhiều.","外语"],["后年我上三年级，希望能把数学学好。","Năm sau nữa tôi lên lớp ba, hy vọng có thể học tốt Toán.","后年 · 年级 · 把 · 数学"]],"11":[["经理通知大家后天下午三点在会议室开会。","Giám đốc báo mọi người ngày kia họp lúc ba giờ chiều tại phòng họp.","经理 · 后天 · 会议室 · 开会"],["看来我一个人没办法解决这个问题，只能找同事帮忙。","Xem ra một mình tôi không có cách giải quyết vấn đề này, chỉ có thể tìm đồng nghiệp giúp.","看来 · 办法 · 解决 · 只能"],["对我来说，工作机会重要，健康也同样重要。","Đối với tôi, cơ hội việc làm quan trọng, sức khỏe cũng quan trọng như vậy.","对……来说 · 机会"],["今天下午开会，你是去会议室还是在办公室参加？","Chiều nay họp, bạn đến phòng họp hay tham gia ở văn phòng?","还是 · 会议室 · 开会"],["请把会议的时间和地点发到我的邮箱里。","Hãy gửi thời gian và địa điểm cuộc họp vào email của tôi.","把 · 会议 · 地点 · 发 · 邮箱"],["笔记本电脑突然没有声音，我试了几次也没解决。","Laptop đột nhiên mất tiếng, tôi thử vài lần vẫn chưa giải quyết được.","笔记本电脑 · 声音 · 解决"],["喝茶或者喝咖啡都可以，你来决定吧。","Uống trà hoặc cà phê đều được, bạn quyết định nhé.","或者"],["对很多年轻人来说，离开熟悉的地方去大城市生活并不容易。","Đối với nhiều người trẻ, rời nơi quen thuộc đến thành phố lớn sống không hề dễ.","对……来说 · 离开 · 城市 · 生活"],["为了这次会议，他已经把所有资料都准备好了。","Vì cuộc họp lần này, anh ấy đã chuẩn bị xong toàn bộ tài liệu.","为 · 会议 · 把"],["看来今天解决不了这个问题，只能等技术人员来。","Xem ra hôm nay không giải quyết được vấn đề này, chỉ có thể chờ kỹ thuật viên đến.","看来 · 解决 · 只能"],["你愿意留在现在的公司，还是换一个新工作？","Bạn sẵn lòng ở lại công ty hiện tại hay đổi một công việc mới?","愿意 · 还是"],["经理正在休假，有事可以先发邮件或者打电话给他。","Giám đốc đang nghỉ phép, có việc có thể gửi email hoặc gọi điện trước cho ông ấy.","经理 · 休假 · 发 · 或者"],["老张把笔记本电脑拿到会议室去测试声音了。","Lão Trương đã mang laptop đến phòng họp để kiểm tra âm thanh rồi.","把 · 笔记本电脑 · 会议室 · 声音"],["同事今天请假了，我怕一个人做不完这些工作。","Đồng nghiệp hôm nay xin nghỉ phép, tôi sợ một mình làm không hết việc.","同事 · 请假 · 怕"],["对老张来说，这是一次难得的学习机会，他很愿意参加。","Đối với Lão Trương, đây là cơ hội học tập hiếm có, anh ấy rất sẵn lòng tham gia.","对……来说 · 机会 · 愿意"],["他怕错过重要的会议，所以提前半小时到了公司。","Anh ấy sợ lỡ cuộc họp quan trọng nên đến công ty sớm nửa tiếng.","怕 · 会议"],["会议地点改到了三楼，请你把新地点通知给其他同事。","Địa điểm họp đã đổi lên tầng ba, bạn hãy báo địa điểm mới cho các đồng nghiệp khác.","会议 · 地点 · 把 · 同事"],["看来他已经习惯了新城市的生活，不想再离开了。","Xem ra anh ấy đã quen với cuộc sống ở thành phố mới, không muốn rời đi nữa.","看来 · 城市 · 生活 · 离开"],["遇到困难的时候，你一般自己想办法还是找别人帮忙？","Khi gặp khó khăn, bạn thường tự nghĩ cách hay tìm người khác giúp đỡ?","办法 · 还是 · 别人"],["对我们部门来说，今天把客户的问题解决好是最重要的。","Đối với bộ phận chúng tôi, hôm nay giải quyết tốt vấn đề của khách hàng là quan trọng nhất.","对……来说 · 把 · 解决"]],"12":[["这个季节天气变化很快，出门前要常常关注天气新闻。","Mùa này thời tiết thay đổi rất nhanh, trước khi ra ngoài phải thường xuyên theo dõi bản tin thời tiết.","季节 · 变化 · 常常 · 关注 · 新闻"],["刚才还在出太阳，现在突然刮起大风来了。","Lúc nãy trời còn nắng, bây giờ đột nhiên nổi gió lớn rồi.","刚才 · 刮 · 风 · 起来"],["周末我或者在家看书，或者去公园划船。","Cuối tuần tôi hoặc ở nhà đọc sách, hoặc ra công viên chèo thuyền.","或者……，或者…… · 公园 · 船"],["办公室里就一把伞，外面下雨了，你先拿去用吧。","Trong văn phòng chỉ có mỗi một chiếc ô, bên ngoài mưa rồi, bạn cầm dùng trước đi.","就 · 把 · 伞"],["天气一变冷，树上的叶子就慢慢黄了，一片一片落下来。","Thời tiết vừa chuyển lạnh, lá trên cây liền dần ngả vàng rồi rụng xuống.","变 · 叶子 · 下来"],["春天到了，天气暖和起来，公园里的花也都开了。","Mùa xuân đến, thời tiết ấm dần lên, hoa trong công viên cũng đều nở rồi.","春天 · 起来 · 公园 · 开花"],["下大雨的时候，你可以穿雨衣，或者跟同事借一把伞。","Khi mưa to, bạn có thể mặc áo mưa, hoặc mượn đồng nghiệp một chiếc ô.","雨衣 · 或者 · 借 · 把 · 伞"],["工作日这个地方人很少，到了傍晚街上才热闹起来。","Ngày làm việc nơi này rất ít người, đến chiều tối ngoài phố mới nhộn nhịp lên.","工作日 · 地方 · 街 · 起来"],["刚才的雨终于停下来了，外面的空气变得格外凉快。","Cơn mưa lúc nãy cuối cùng đã tạnh, không khí bên ngoài trở nên mát mẻ hẳn.","刚才 · 下来 · 变 · 凉快"],["我们班就两个学生去过北方，别人都没见过冬天的雪。","Lớp chúng tôi chỉ có hai học sinh từng đi miền Bắc, những người khác đều chưa thấy tuyết mùa đông.","就 · 冬天"],["秋天不但天气凉快，而且树叶变成金黄色，非常好看。","Mùa thu không những thời tiết mát mẻ mà lá cây còn chuyển sang màu vàng óng rất đẹp.","秋天 · 凉快 · 叶子 · 变成"],["下起雨来以后，街上的行人都加快脚步跑去躲雨。","Sau khi trời bắt đầu đổ mưa, người đi đường trên phố đều rảo bước chạy đi trú mưa.","起来 · 街"],["冬天到了，天黑得越来越早，五点半天色就暗下来了。","Mùa đông đến, trời tối ngày càng sớm, năm rưỡi chiều sắc trời đã tối dần xuống.","冬天 · 下来"],["出门旅行的时候，我或者坐火车，或者坐飞机，看时间怎么安排。","Khi đi du lịch, tôi hoặc đi tàu hỏa, hoặc đi máy bay, tùy xem sắp xếp thời gian thế nào.","或者……，或者……"],["这把伞是我跟邻居借的，就借两天，明天得还给他。","Chiếc ô này tôi mượn của hàng xóm, chỉ mượn hai ngày thôi, mai phải trả anh ấy.","把 · 伞 · 借 · 就"],["一年有四季，每个季节都有不同的风景和气候变化。","Một năm có bốn mùa, mỗi mùa đều có phong cảnh và sự thay đổi khí hậu khác nhau.","四季 · 季节 · 变化"],["大家一聊起夏天去海边坐船的事，心情就高兴起来了。","Mọi người vừa nhắc tới chuyện mùa hè đi biển ngồi thuyền là tâm trạng liền vui hẳn lên.","夏天 · 船 · 起来"],["到了晚上，风慢慢小下来了，外面的温度也降下来了。","Đến tối, gió dần nhỏ xuống, nhiệt độ bên ngoài cũng hạ xuống rồi.","风 · 下来"],["刚才的新闻提醒大家，明天或者刮大风，或者下大雨。","Bản tin lúc nãy nhắc mọi người ngày mai hoặc có gió to, hoặc có mưa lớn.","刚才 · 新闻 · 或者……，或者…… · 刮 · 风"],["我家离那个公园很近，走路就十分钟，我常常去那儿散步。","Nhà tôi cách công viên đó rất gần, đi bộ chỉ mười phút, tôi thường tới đó đi dạo.","公园 · 就 · 常常"]],"13":[["如果你周末有空的话，就来我家做客，今天我请客。","Nếu cuối tuần bạn rảnh thì đến nhà tôi chơi nhé, hôm nay tôi mời khách.","……的话，就…… · 做客 · 请客"],["妈妈已经把切好的水果放在盘子里，端出来给客人们吃了。","Mẹ đã xếp hoa quả cắt sẵn vào đĩa rồi bưng ra cho khách ăn.","把 · 放 · 盘子 · 客人"],["晚会上，大家一边喝着红酒，一边高兴地聊天儿。","Trong buổi tiệc tối, mọi người vừa uống rượu vang vừa trò chuyện vui vẻ.","晚会 · 一边……，一边…… · 酒 · 聊天儿"],["我的新邻居是一对来自英国的夫妻，他们对东方文化很感兴趣。","Hàng xóm mới của tôi là một cặp vợ chồng đến từ nước Anh, họ rất hứng thú với văn hóa phương Đông.","邻居 · 来自 · 英国 · 夫妻 · 东方 · 文化"],["要是你对这道菜的做法不熟悉的话，我可以教你做一遍。","Nếu bạn chưa quen cách làm món này thì tôi có thể dạy bạn làm một lượt.","做法 · ……的话，就……"],["请把大家带来的礼物都拿进去，整齐地放在客厅的桌子上。","Hãy mang hết quà mọi người đem tới vào trong, đặt ngay ngắn trên bàn phòng khách.","把 · 礼物 · 放"],["中国南方和北方的饮食习惯不同，做菜的做法也有很大差别。","Thói quen ăn uống ở miền Nam và miền Bắc Trung Quốc khác nhau, cách nấu món ăn cũng khác biệt lớn.","南方 · 北方 · 不同 · 做法"],["那位著名的画家喜欢一边听安静的音乐，一边在房间里画画儿。","Vị họa sĩ nổi tiếng ấy thích vừa nghe nhạc êm dịu vừa vẽ tranh trong phòng.","画家 · 一边……，一边……"],["汤的味道如果太淡的话，你就再往里面加一点儿盐吧。","Nếu vị canh nhạt quá thì bạn hãy cho thêm một chút muối vào trong nhé.","……的话，就…… · 加 · 点"],["你放心吧，我已经把今晚请客要用的盘子和酒杯洗得干干净净了。","Bạn yên tâm đi, tôi đã rửa sạch sẽ đĩa và ly rượu dùng để đãi khách tối nay rồi.","放心 · 把 · 请客 · 盘子 · 酒"],["他一边看中国地图，一边把去过的城市用红点标出来。","Anh ấy vừa xem bản đồ Trung Quốc vừa đánh dấu những thành phố từng đi qua bằng chấm đỏ.","一边……，一边…… · 地图 · 把 · 点"],["昨晚的晚会非常热闹，客人们一直聊到半夜十二点才离开。","Buổi dạ tiệc tối qua rất náo nhiệt, khách khứa trò chuyện mãi đến 12 giờ đêm mới về.","晚会 · 客人 · 直到"],["去朋友家做客的话，最好提前准备一份小礼物带过去。","Nếu đến nhà bạn chơi thì tốt nhất nên chuẩn bị trước một món quà nhỏ mang theo.","做客 · ……的话，就…… · 礼物"],["画家把刚画好的山水画挂在墙上，大家看了都觉得特别美。","Họa sĩ treo bức tranh sơn thủy vừa vẽ xong lên tường, mọi người xem đều thấy rất đẹp.","画家 · 把"],["虽然他们夫妻来自不同的国家，但是彼此尊重对方的文化。","Tuy vợ chồng họ đến từ hai quốc gia khác nhau nhưng luôn tôn trọng văn hóa của đối phương.","夫妻 · 来自 · 不同 · 文化"],["我爸爸平时做饭的时候，喜欢一边看菜谱，一边研究新的做法。","Bố tôi lúc nấu cơm thường ngày thích vừa xem công thức vừa nghiên cứu cách chế biến mới.","一边……，一边…… · 做法"],["明天不下雨的话，我们就请新邻居一起来院子里喝茶聊天儿。","Nếu ngày mai trời không mưa thì chúng ta mời hàng xóm mới cùng ra sân uống trà trò chuyện.","……的话，就…… · 邻居 · 聊天儿"],["他直到把所有工作都做完才回家，所以感到身体非常累。","Anh ấy mãi đến khi làm xong hết mọi việc mới về nhà nên cảm thấy cơ thể rất mệt.","直到 · 把 · 感到"],["服务员把客人点的菜一盘一盘地端进去，放在大圆桌上。","Nhân viên phục vụ bưng từng đĩa thức ăn khách gọi vào trong, đặt lên bàn tròn lớn.","把 · 客人 · 点 · 盘子 · 放"],["在英国留学的时候，每当遇到热情的邻居，他都会感到很温暖。","Khi du học ở Anh, mỗi lần gặp những người hàng xóm nhiệt tình, anh ấy đều cảm thấy rất ấm áp.","英国 · 邻居 · 感到"]],"14":[["那本汉语词典被别的同学借走了，你最好先用手机查一下。","Cuốn từ điển tiếng Hán đó bị bạn khác mượn mất rồi, tốt nhất bạn dùng điện thoại tra trước đi.","词典 · 被 · 最好 · 先"],["我们先把教室打扫干净，然后再一块儿去礼堂看新年节目。","Chúng ta dọn sạch phòng học trước, sau đó cùng nhau đến hội trường xem tiết mục năm mới.","先……，再/然后…… · 一块儿 · 新年 · 节目"],["离表演开始还有半个小时呢，你急什么啊，先喝口水休息一下。","Còn nửa tiếng nữa mới bắt đầu biểu diễn mà, bạn vội gì chứ, uống ngụm nước nghỉ ngơi trước đi.","表演 · ×什么（啊） · 先"],["桌上的报纸和杂志都被老师收起来了，放进了图书馆的书架上。","Báo và tạp chí trên bàn đều đã được thầy giáo cất đi, xếp lên giá sách của thư viện.","报纸 · 被 · 图书馆"],["他先在网站上下载了电子书，然后每天晚上读两节名人故事。","Cậu ấy tải sách điện tử trên trang web trước, sau đó mỗi tối đọc hai mục chuyện danh nhân.","先……，再/然后…… · 网站 · 电子书 · 节 · 名人 · 故事"],["大家都是同班同学，在校长和老师面前表演节目，你怕什么啊？","Mọi người đều là bạn cùng lớp, biểu diễn tiết mục trước mặt hiệu trưởng và thầy cô, bạn sợ gì chứ?","校长 · 面前 · 表演 · 节目 · ×什么（啊）"],["留学生们表演的舞蹈太精彩了，视频一发到网站上就被大家转发。","Điệu múa các lưu học sinh biểu diễn quá đặc sắc, video vừa đăng lên web đã được mọi người chia sẻ.","留学生 · 表演 · 视频 · 网站 · 被"],["要是忘记带图书馆的借书证怎么办？你可以先看电子书。","Nếu quên mang thẻ thư viện thì làm sao? Bạn có thể đọc sách điện tử trước.","忘记 · 图书馆 · 怎么办 · 先 · 电子书"],["这才是一道普通的练习题，你难过什么啊，我们一块儿再算一遍。","Đây mới chỉ là một câu luyện tập bình thường, bạn buồn gì chứ, chúng mình cùng tính lại một lượt.","×什么（啊） · 一块儿"],["新年联欢会上，我们班的女生先唱歌，然后再跳一段民族舞。","Trong buổi liên hoan năm mới, các bạn nữ lớp tôi hát trước, sau đó nhảy một điệu múa dân tộc.","新年 · 女生 · 先……，再/然后…… · 跳"],["我放在桌子上的那张报纸不知道被谁拿走了，到现在还没找到。","Tờ báo tôi để trên bàn không biết bị ai cầm đi mất, đến giờ vẫn chưa tìm thấy.","报纸 · 被"],["有些同学一开始不相信自己能演好，最后却表演得非常成功。","Một số bạn lúc đầu không tin mình có thể diễn tốt, cuối cùng lại biểu diễn vô cùng thành công.","有些 · 相信 · 最后 · 表演"],["你先听完这两节课的录音，然后再把不明白的生词查词典。","Bạn nghe xong bản thu âm của hai tiết học này trước, sau đó tra từ điển những từ mới chưa hiểu.","先……，再/然后…… · 节 · 词典"],["不过是忘记带笔记本而已，你着急什么，我借给你几张纸吧。","Chỉ là quên mang vở ghi thôi mà, bạn sốt ruột gì chứ, tôi cho bạn mượn mấy tờ giấy nhé.","忘记 · ×什么（啊）"],["在全校师生面前，我们班级的节目被校长表扬了好几次。","Trước mặt toàn thể thầy trò trong trường, tiết mục của lớp chúng tôi được thầy hiệu trưởng khen mấy lần.","面前 · 班级 · 节目 · 被 · 校长"],["最好先看看网站上的教学视频，再自己动手练习，这样学得更快。","Tốt nhất hãy xem video hướng dẫn trên trang web trước, rồi tự bắt tay vào luyện tập, như vậy học nhanh hơn.","最好 · 先……，再/然后…… · 网站 · 视频"],["那个关于名人的历史故事被拍成了电影，很多留学生都喜欢看。","Câu chuyện lịch sử về danh nhân đó đã được dựng thành phim, rất nhiều lưu học sinh thích xem.","名人 · 故事 · 被 · 留学生"],["演出马上就要结束了，你还犹豫什么啊，快上台跟大家一块儿拍照！","Buổi diễn sắp kết thúc rồi, bạn còn do dự gì nữa, mau lên sân khấu chụp ảnh cùng mọi người đi!","×什么（啊） · 一块儿"],["到了最后一节课，老师先带大家复习生词，然后讲了两个新语法。","Đến tiết học cuối cùng, thầy giáo dẫn mọi người ôn từ mới trước, sau đó giảng hai ngữ pháp mới.","最后 · 节 · 先……，再/然后……"],["虽然有些句子比较难，但是我相信只要多读几遍就不会被难倒。","Tuy một số câu khá khó nhưng tôi tin chỉ cần đọc nhiều lượt thì sẽ không bị làm khó.","有些 · 相信 · 被"]],"15":[["根据天气预报，今天下午天空会很蓝，非常适合去公园散步。","Theo dự báo thời tiết, chiều nay bầu trời sẽ rất xanh, vô cùng thích hợp đi dạo công viên.","根据 · 蓝"],["经过一个学期的努力，学生们的汉语水平一天一天地提高了。","Qua một học kỳ nỗ lực, trình độ tiếng Hán của các học sinh đã nâng cao từng ngày.","经过 · 一天一天"],["在我看来，想要真正了解南京的历史，最好去著名的景点看看。","Theo tôi thấy, muốn thực sự tìm hiểu lịch sử Nam Kinh thì tốt nhất nên đi thăm các thắng cảnh nổi tiếng.","在……看来 · 了解 · 南京 · 有名 · 景点"],["放学以后孩子们跑到草地上玩游戏，不一会儿就笑成了一片。","Sau khi tan học bọn trẻ chạy ra bãi cỏ chơi trò chơi, chẳng mấy chốc đã cười vang cả một góc.","放学 · 草地 · 游戏 · 不一会儿"],["根据导游的介绍，每年都有成千上万的外地游客来这里参观。","Theo lời giới thiệu của hướng dẫn viên, mỗi năm đều có hàng vạn du khách ngoại tỉnh đến đây tham quan.","根据 · 外地 · 游客"],["这段历史故事比较复杂，我得一点儿一点儿地讲给你听。","Đoạn chuyện lịch sử này khá phức tạp, tôi phải kể cho bạn nghe từng chút từng chút một.","段 · 一点儿一点儿"],["在我们中国人看来，黄河从西北流向东方，就像母亲河一样重要。","Trong mắt người Trung Quốc chúng tôi, sông Hoàng Hà chảy từ Tây Bắc về phương Đông, quan trọng như dòng sông mẹ.","在……看来 · 黄河 · 西北 · 河"],["刚才天还晴着，可是刮了一阵风，不一会儿就下起大雨来了。","Lúc nãy trời còn nắng, thế mà thổi một cơn gió, chẳng mấy chốc đã đổ mưa to.","可是 · 不一会儿"],["我家附近的马路很宽，路边的树一棵一棵地排得非常整齐。","Đường cái gần nhà tôi rất rộng, cây bên đường xếp từng cây từng cây vô cùng ngay ngắn.","附近 · 马路 · 一棵一棵"],["根据学校的规定，三年级以上的学生平时都可以去图书馆借书。","Theo quy định của trường, học sinh từ lớp ba trở lên ngày thường đều có thể đến thư viện mượn sách.","根据 · 以上 · 平时"],["在很多老人看来，平时在公园里养花、跟朋友聊聊天儿就是幸福。","Theo nhiều người lớn tuổi, ngày thường trồng hoa trong công viên, trò chuyện cùng bạn bè chính là hạnh phúc.","在……看来 · 老人 · 平时 · 养 · 聊"],["昨天我经过学校附近的马路时，正好遇见了十年没见的老同学。","Hôm qua khi đi ngang qua con đường gần trường, tôi tình cờ bắt gặp người bạn học cũ mười năm chưa gặp.","经过 · 附近 · 马路 · 遇见"],["老师把生词一个一个地写在黑板上，不一会儿就写满了整块黑板。","Thầy giáo viết từng từ mới một lên bảng đen, chẳng mấy chốc đã viết kín cả tấm bảng.","一个一个 · 不一会儿"],["他在南京住了五年了，可是对附近一些有名的景点还不太了解。","Anh ấy đã sống ở Nam Kinh năm năm rồi, thế nhưng vẫn chưa hiểu rõ một số thắng cảnh nổi tiếng gần đó.","南京 · 可是 · 附近 · 有名 · 景点 · 了解"],["根据我平时的观察，养成早睡早起的好习惯跟身体健康很有关系。","Theo quan sát thường ngày của tôi, rèn thói quen ngủ sớm dậy sớm có quan hệ rất lớn với sức khỏe.","根据 · 平时 · 养 · 关系"],["在外地游客看来，南京不仅历史有名，而且当地人也特别热情。","Trong mắt du khách ngoại tỉnh, Nam Kinh không chỉ nổi tiếng về lịch sử mà người dân địa phương còn rất nhiệt tình.","外地 · 游客 · 在……看来 · 南京 · 有名"],["放学铃一响，同学们就一队一队地走出校门，安全地穿过马路。","Chuông tan học vừa reo, các bạn học sinh liền đi từng hàng từng hàng ra cổng trường, băng qua đường an toàn.","放学 · 一队一队 · 马路"],["我们在河边的草地上坐下来聊了没几句，不一会儿月亮就升起来了。","Chúng tôi ngồi xuống bãi cỏ bên sông trò chuyện chưa được mấy câu, chẳng mấy chốc trăng đã lên.","河 · 草地 · 聊 · 不一会儿"],["在老师看来，读十遍课文不如把每一段的意思都真正弄明白。","Theo thầy giáo, đọc mười lượt bài khóa không bằng thực sự hiểu rõ ý nghĩa của từng đoạn.","在……看来 · 段"],["根据他的经验，去西北旅行以前，最好先了解当地的天气变化。","Theo kinh nghiệm của anh ấy, trước khi đi du lịch Tây Bắc, tốt nhất nên tìm hiểu trước sự thay đổi thời tiết ở đó.","根据 · 西北 · 了解"]],"16":[["动物园里的大熊猫真可爱，一会儿爬树玩耍，一会儿坐下来吃竹子。","Gấu trúc lớn trong sở thú thật đáng yêu, lúc thì trèo cây đùa nghịch, lúc thì ngồi xuống ăn trúc.","动物园 · 大熊猫 · 可爱 · 一会儿……，一会儿…… · 竹子"],["这是一本关于野生动物的书，里面介绍了很多保护国宝的故事。","Đây là một cuốn sách về động vật hoang dã, bên trong giới thiệu rất nhiều câu chuyện bảo vệ quốc bảo.","关于 · 野生 · 动物 · 国宝"],["一般来说，大熊猫每天除了吃新鲜的竹子，大部分时间都在睡觉。","Nói chung, gấu trúc lớn mỗi ngày ngoài ăn trúc tươi ra thì phần lớn thời gian đều ngủ.","一般来说 · 大熊猫 · 竹子"],["冬天天黑得早，这家动物园冬天比夏天早关门一个小时。","Mùa đông trời tối sớm, sở thú này mùa đông đóng cửa sớm hơn mùa hè một tiếng đồng hồ.","动物园 · 比……早 + V · 小时"],["我站在旁边看了半天，这只小熊猫好像还没吃饱，嘴一直没停过。","Tôi đứng bên cạnh xem cả buổi, chú gấu trúc nhỏ này hình như vẫn chưa ăn no, miệng cứ nhai suốt.","半天 · 好像 · 饱 · 嘴"],["小猫在院子里跑来跑去，把脸和脚都弄脏了，看起来奇怪极了。","Chú mèo con chạy tới chạy lui trong sân làm bẩn cả mặt và chân, trông kỳ lạ vô cùng.","脸 · 脚 · 脏 · 奇怪"],["今天借的这本关于中国历史的书，我比昨天多看了二十页。","Cuốn sách về lịch sử Trung Quốc mượn hôm nay, tôi đọc nhiều hơn hôm qua hai mươi trang.","关于 · 比……多 + V"],["周末的天气真奇怪，一会儿出太阳，一会儿又刮起风下起雨来。","Thời tiết cuối tuần thật kỳ lạ, lúc thì nắng, lúc lại nổi gió đổ mưa.","周末 · 奇怪 · 一会儿……，一会儿……"],["一般来说，小孩子和大人一样，都很喜爱圆圆胖胖的大熊猫。","Nói chung, trẻ nhỏ cũng giống như người lớn, đều rất yêu thích những chú gấu trúc tròn trịa mũm mĩm.","一般来说 · 大人 · 喜爱 · 大熊猫"],["其实我全认得这些照片里的动物，还给它们照了好几张相呢。","Thực ra tôi nhận ra hết các loài động vật trong những bức ảnh này, còn chụp cho chúng mấy tấm ảnh nữa.","其实 · 全 · 认得 · 动物 · 张"],["为了照顾生病的妹妹，妈妈今天比平时少睡了两个小时。","Để chăm sóc em gái bị ốm, hôm nay mẹ ngủ ít hơn ngày thường hai tiếng đồng hồ.","照顾 · 比……少 + V"],["饲养员每天留在熊猫身边细心照顾它们，连每张脸都认得清清楚楚。","Nhân viên nuôi dưỡng mỗi ngày ở bên cạnh gấu trúc chăm sóc tỉ mỉ, đến từng khuôn mặt đều nhận ra rõ ràng.","身边 · 照顾 · 张 · 脸 · 认得"],["老师给我们讲了很多关于国宝大熊猫的知识，大家都听得入迷了。","Thầy giáo giảng cho chúng tôi rất nhiều kiến thức về quốc bảo gấu trúc lớn, mọi người đều nghe say mê.","关于 · 国宝 · 大熊猫"],["弟弟看电视的时候，一会儿哈哈大笑，一会儿又认真地问大人问题。","Em trai lúc xem tivi, lúc thì cười ha ha, lúc lại nghiêm túc hỏi chuyện người lớn.","一会儿……，一会儿…… · 大人"],["一般来说，野生的动物比动物园里的动物更擅长自己寻找食物。","Nói chung, động vật hoang dã giỏi tự tìm kiếm thức ăn hơn động vật trong sở thú.","一般来说 · 野生 · 动物 · 动物园"],["因为路上堵车了半天，他今天比我晚到了十五分钟。","Vì tắc đường trên phố cả buổi nên hôm nay anh ấy đến muộn hơn tôi mười lăm phút.","半天 · 比……晚 + V"],["我的脚走得有点儿疼，我们就在竹子旁边坐一会儿再继续逛吧。","Chân tôi đi hơi đau rồi, chúng mình ngồi nghỉ một lát cạnh khóm trúc rồi hãy đi dạo tiếp nhé.","脚 · 竹子 · 一会儿"],["关于周末去动物园春游的安排，班长已经通知全班同学了。","Về việc sắp xếp đi dã ngoại sở thú vào cuối tuần, lớp trưởng đã thông báo cho cả lớp rồi.","关于 · 周末 · 动物园 · 全"],["其实这只小狗一点儿也不脏，妈妈刚刚给它洗干净了脸和脚。","Thực ra chú chó nhỏ này chẳng bẩn chút nào, mẹ vừa mới rửa sạch mặt và chân cho nó xong.","其实 · 脏 · 脸 · 脚"],["哥哥今年长高了很多，每顿饭都比我多吃一碗米饭才觉得饱。","Anh trai năm nay cao lên nhiều, mỗi bữa đều ăn nhiều hơn tôi một bát cơm mới thấy no.","比……多 + V · 饱"]],"17":[["做错事情是很常见的，以后我要多向认真、聪明的人学习。","Làm sai việc là điều rất thường gặp, sau này tôi phải học hỏi nhiều hơn ở những người nghiêm túc, thông minh.","错 · 常见 · 向 · 聪明"],["你不是一直想出国留学吗？为什么现在还没开始准备材料呢？","Chẳng phải bạn vẫn luôn muốn đi du học nước ngoài sao? Sao bây giờ vẫn chưa bắt đầu chuẩn bị hồ sơ?","不是……吗？ · 留学"],["我还没想好学什么专业，更没想好将来去哪个国家留学。","Tôi vẫn chưa nghĩ xong sẽ học chuyên ngành gì, càng chưa nghĩ xong sau này đi nước nào du học.","……，更…… · 国家 · 留学"],["只有想清楚自己真正喜欢什么，才能在人生路上找准方向。","Chỉ có nghĩ thật rõ bản thân thực sự thích gì thì mới có thể tìm đúng phương hướng trên đường đời.","只有……，才…… · 真正 · 方向"],["遇到难题的时候别害怕，你可以向老师或者有经验的同学请教。","Khi gặp câu hỏi khó đừng sợ, bạn có thể xin chỉ dẫn từ thầy cô hoặc các bạn có kinh nghiệm.","难题 · 害怕 · 向"],["前天我用手机查资料的时候，发现这个网站对留学生非常有用。","Hôm kia khi dùng điện thoại tra tài liệu, tôi phát hiện trang web này vô cùng hữu ích cho lưu học sinh.","前天 · 查 · 有用"],["你不是已经答应爸妈睡觉前把手机关机吗？快去休息吧！","Chẳng phải bạn đã hứa với bố mẹ là tắt nguồn điện thoại trước khi ngủ sao? Mau đi nghỉ đi!","不是……吗？ · 关机"],["只有平时多读书、多查词典，遇到难题时才容易找到回答的办法。","Chỉ có ngày thường đọc sách nhiều, tra từ điển nhiều thì khi gặp câu khó mới dễ tìm được cách trả lời.","只有……，才…… · 查 · 难题 · 容易 · 回答"],["他平时连小事都很少做错，更不会在这么重要的考试中马虎。","Thường ngày đến việc nhỏ cậu ấy còn hiếm khi làm sai, huống hồ là bất cẩn trong kỳ thi quan trọng thế này.","错 · ……，更……"],["那个屋子里到处都放着跟中国历史和文化有关的书籍。","Trong căn phòng đó khắp nơi đều để sách vở liên quan đến lịch sử và văn hóa Trung Quốc.","屋子 · 到处 · 有关"],["知道自己走错了方向，就应该马上停下来向路人问清楚。","Biết mình đã đi sai hướng thì nên lập tức dừng lại hỏi rõ người đi đường.","错 · 方向 · 向"],["爸妈不但同意我继续读研究生，更支持我去喜欢的城市工作。","Bố mẹ không những đồng ý cho tôi học tiếp cao học mà còn ủng hộ tôi đến thành phố mình thích làm việc.","同意 · 继续 · ……，更……"],["这本书不是前天你刚从图书馆借来的吗？怎么到处都找不到了？","Cuốn sách này chẳng phải hôm kia bạn vừa mượn từ thư viện về sao? Sao tìm khắp nơi đều không thấy?","不是……吗？ · 前天 · 到处"],["大家都认为他很聪明，可他觉得只有继续努力才能取得好成绩。","Mọi người đều cho rằng cậu ấy rất thông minh, nhưng cậu ấy thấy chỉ có tiếp tục nỗ lực mới đạt kết quả tốt.","认为 · 聪明 · 可 · 只有……，才…… · 继续"],["比如北京、上海这样的大城市，工作机会多，但是竞争也很激烈。","Ví dụ những thành phố lớn như Bắc Kinh, Thượng Hải, cơ hội việc làm nhiều nhưng cạnh tranh cũng rất khốc liệt.","比如"],["做了错事要勇敢地向别人道歉，别因为害怕别人生气就不敢说。","Làm sai thì phải dũng cảm xin lỗi người khác, đừng vì sợ người ta giận mà không dám nói.","错 · 向 · 害怕 · 生气"],["电梯坏了，我们不是只能走楼梯上去吗？快走吧，别迟到了。","Thang máy hỏng rồi, chẳng phải chúng ta chỉ có thể đi cầu thang bộ lên sao? Đi mau thôi, kẻo muộn.","不是……吗？ · 楼梯"],["这个问题看似容易，可要想真正回答清楚，还得查不少资料。","Câu hỏi này nhìn có vẻ dễ, nhưng muốn thực sự trả lời rõ ràng thì còn phải tra khá nhiều tài liệu.","容易 · 可 · 真正 · 回答 · 查"],["他连普通的日常对话都听不太懂，更别说看懂这本专业书了。","Đến hội thoại thường ngày cậu ấy còn nghe chưa hiểu lắm, huống hồ là đọc hiểu cuốn sách chuyên ngành này.","……，更……"],["只有先静下心来听别人把话说完，才能真正明白对方的意思。","Chỉ có bình tĩnh lắng nghe người khác nói hết lời trước thì mới thực sự hiểu được ý của đối phương.","只有……，才…… · 真正"]],"18":[["春节是中国最重要的传统节日，大家大概可以放七八天假。","Tết Nguyên đán là ngày lễ truyền thống quan trọng nhất của Trung Quốc, mọi người được nghỉ khoảng bảy tám ngày.","春节 · 节日 · 大概 · 七八"],["我刚才给张阿姨打了个电话，她刚刚从北京出发去上海。","Lúc nãy tôi gọi điện cho dì Trương, dì ấy vừa mới xuất phát từ Bắc Kinh đi Thượng Hải.","刚才 · 阿姨 · 刚刚 · 出发"],["只要你一直坚持下去，就一定能在这个学期完成自己的目标。","Chỉ cần bạn kiên trì tới cùng thì chắc chắn sẽ hoàn thành được mục tiêu của mình trong học kỳ này.","只要……，就…… · 坚持 · 学期 · 完成 · 目标"],["从那天见面起，他们就成了好朋友，总是一起讨论学习问题。","Kể từ lần gặp mặt ngày hôm đó, họ đã trở thành bạn tốt, luôn cùng nhau thảo luận chuyện học tập.","从……起 · 见面 · 总"],["除夕晚上，全家人一边包饺子，一边热热闹闹地看春节联欢晚会。","Đêm Giao thừa, cả gia đình vừa gói sủi cảo vừa quây quần xem Gala Tết Nguyên đán.","春节 · 联欢"],["教室里来了五六个新同学，他们都是刚刚到中国不久的留学生。","Trong lớp có khoảng năm sáu bạn mới đến, họ đều là lưu học sinh vừa mới tới Trung Quốc chưa lâu.","五六 · 刚刚 · 不久"],["只要你有不懂得的问题，随时都可以去办公室找李叔叔帮忙。","Chỉ cần bạn có vấn đề chưa hiểu, bất cứ lúc nào cũng có thể tới văn phòng tìm chú Lý giúp đỡ.","只要……，就…… · 懂得 · 叔叔"],["从大学毕业那年起，他就留在这座城市工作，见证了这里的发展。","Kể từ năm tốt nghiệp đại học, anh ấy đã ở lại thành phố này làm việc, chứng kiến sự phát triển nơi đây.","从……起 · 毕业 · 发展"],["刚才的会议上，经理收到了三四份大家交上来的新年工作计划。","Trong cuộc họp lúc nãy, giám đốc đã nhận được ba bốn bản kế hoạch công việc năm mới mọi người nộp lên.","刚才 · 收 · 三四"],["他刚刚看教学视频学会了怎样包饺子，今晚打算做给爸妈尝尝。","Cậu ấy vừa xem video hướng dẫn học được cách gói sủi cảo, tối nay định làm cho bố mẹ nếm thử.","刚刚 · 怎样"],["只要每天坚持读两三页中文书，你的阅读能力就会慢慢提高。","Chỉ cần mỗi ngày kiên trì đọc hai ba trang sách tiếng Trung, khả năng đọc hiểu của bạn sẽ dần nâng cao.","只要……，就…… · 坚持 · 两三"],["从今天起，我决定每天早起锻炼身体，再也不像过去那样偷懒了。","Kể từ hôm nay, tôi quyết định mỗi ngày dậy sớm tập thể dục, không lười biếng như trước kia nữa.","从……起 · 过去"],["我刚买回来的两瓶矿泉水放在桌子上，刚才被谁拿走了一瓶？","Hai chai nước khoáng tôi vừa mua về để trên bàn, lúc nãy ai đã cầm đi một chai rồi?","刚 · 矿泉水 · 刚才"],["虽然毕业已经七八年了，但是发生过的许多事情仿佛还在昨天。","Tuy đã tốt nghiệp được bảy tám năm rồi nhưng nhiều chuyện từng xảy ra cứ ngỡ như mới hôm qua.","毕业 · 七八 · 发生"],["这是我特意为您准备的过节礼物，请张阿姨和李叔叔一定收下。","Đây là món quà lễ Tết cháu đặc biệt chuẩn bị biếu cô chú, xin cô Trương và chú Lý nhất định nhận cho.","过节 · 阿姨 · 叔叔 · 收"],["只要我们提前半小时出发，就肯定能按时赶到车站跟大家见面。","Chỉ cần chúng ta xuất phát sớm nửa tiếng thì chắc chắn sẽ kịp tới nhà ga gặp mọi người đúng giờ.","只要……，就…… · 出发 · 见面"],["从他出生那一天起，父母就希望他将来成为一个懂得感恩的人。","Kể từ ngày cậu ấy chào đời, cha mẹ đã mong sau này cậu trở thành một người biết ơn.","从……起 · 出生 · 懂得"],["我刚刚听同事说起，下个学期我们学校要举办一次大型联欢会。","Tôi vừa mới nghe đồng nghiệp nhắc tới, học kỳ tới trường chúng ta sẽ tổ chức một buổi liên hoan lớn.","刚刚 · 总 · 学期 · 联欢"],["过去从这儿到市中心要走三四个小时，现在地铁半小时就到了。","Trước kia từ đây tới trung tâm thành phố phải đi mất ba bốn tiếng, nay đi tàu điện ngầm nửa tiếng là tới.","过去 · 三四"],["不久前发生的那件事让他懂得，只有脚踏实地才能完成目标。","Chuyện xảy ra cách đây không lâu giúp anh ấy hiểu ra rằng chỉ có làm việc thực tế mới hoàn thành được mục tiêu.","不久 · 发生 · 懂得 · 完成 · 目标"]]};
window.lessonTexts={"13":{"url":"https://tieng-trung-ha-hang.vercel.app/hsk3-bt13.html","keys":[{"zh":"我的新邻居来自英国。","pinyin":"Wǒ de xīn línjū láizì Yīngguó.","vi":"Hàng xóm mới của tôi đến từ Anh."},{"zh":"有空的话，就来我家做客。","pinyin":"Yǒu kòng dehuà, jiù lái wǒ jiā zuòkè.","vi":"Nếu rảnh thì đến nhà tôi chơi nhé."},{"zh":"我们一边吃饭，一边聊天儿。","pinyin":"Wǒmen yìbiān chī fàn, yìbiān liáotiānr.","vi":"Chúng tôi vừa ăn vừa trò chuyện."}]},"14":{"url":"https://tieng-trung-ha-hang.vercel.app/hsk3-bt14.html","keys":[{"zh":"这本书被别人借走了。","pinyin":"Zhè běn shū bèi biérén jiè zǒu le.","vi":"Cuốn sách này bị người khác mượn mất rồi."},{"zh":"紧张什么啊，我们都喜欢听你唱歌。","pinyin":"Jǐnzhāng shénme a, wǒmen dōu xǐhuān tīng nǐ chàng gē.","vi":"Có gì mà hồi hộp, chúng tôi đều thích nghe bạn hát."},{"zh":"先去图书馆借书，然后去游泳。","pinyin":"Xiān qù túshūguǎn jiè shū, ránhòu qù yóu yǒng.","vi":"Đến thư viện mượn sách trước, rồi đi bơi."}]},"15":{"url":"https://tieng-trung-ha-hang.vercel.app/hsk3-bt15.html","keys":[{"zh":"我是半个南京人。","pinyin":"Wǒ shì bàn ge Nánjīng rén.","vi":"Tôi là nửa người Nam Kinh."},{"zh":"在我们中国人看来，黄河像妈妈一样。","pinyin":"Zài wǒmen Zhōngguó rén kànlái, Huáng Hé xiàng māma yíyàng.","vi":"Theo người Trung Quốc chúng tôi, Hoàng Hà như người mẹ."},{"zh":"不一会儿，天就黑了。","pinyin":"Bù yíhuìr, tiān jiù hēi le.","vi":"Chẳng mấy chốc trời đã tối."}]},"10":{"url":"https://tieng-trung-ha-hang.vercel.app/hsk3-bt10.html","keys":[{"zh":"你明天再把书还给我。","pinyin":"Nǐ míngtiān zài bǎ shū huán gěi wǒ.","vi":"Ngày mai em trả lại sách cho cô nhé."},{"zh":"把作业写完再玩。","pinyin":"Bǎ zuòyè xiě wán zài wán.","vi":"Làm xong bài tập rồi hẵng chơi."},{"zh":"老师讲得很清楚。","pinyin":"Lǎoshī jiǎng de hěn qīngchu.","vi":"Thầy giảng rất rõ ràng."}]},"11":{"url":"https://tieng-trung-ha-hang.vercel.app/hsk3-bt11.html","keys":[{"zh":"看来我没办法解决这个问题。","pinyin":"Kànlái wǒ méi bànfǎ jiějué zhè ge wèntí.","vi":"Xem ra em không có cách nào giải quyết vấn đề này."},{"zh":"对我来说，健康最重要。","pinyin":"Duì wǒ lái shuō, jiànkāng zuì zhòngyào.","vi":"Đối với tôi, sức khỏe là quan trọng nhất."},{"zh":"请把邮件发给我。","pinyin":"Qǐng bǎ yóujiàn fā gěi wǒ.","vi":"Xin gửi email cho tôi."}]},"12":{"url":"https://tieng-trung-ha-hang.vercel.app/hsk3-bt12.html","keys":[{"zh":"这个季节天气变化很快。","pinyin":"Zhè ge jìjié tiānqì biànhuà hěn kuài.","vi":"Thời tiết mùa này thay đổi rất nhanh."},{"zh":"下起雨来了，快带上伞。","pinyin":"Xià qǐ yǔ lái le, kuài dài shang sǎn.","vi":"Trời bắt đầu mưa rồi, mau mang ô theo."},{"zh":"一年有四季，每个季节都很美。","pinyin":"Yì nián yǒu sì jì, měi ge jìjié dōu hěn měi.","vi":"Một năm có bốn mùa, mùa nào cũng đẹp."}]},"16":{"url":"https://tieng-trung-ha-hang.vercel.app/hsk3-bt16.html","keys":[{"zh":"它一会儿在你脚边睡觉，一会儿在你身上爬。","pinyin":"Tā yíhuìr zài nǐ jiǎobiān shuìjiào, yíhuìr zài nǐ shēnshang pá.","vi":"Nó lúc thì ngủ bên chân bạn, lúc lại bò trên người bạn."},{"zh":"全世界只有中国有野生大熊猫。","pinyin":"Quán shìjiè zhǐyǒu Zhōngguó yǒu yěshēng dàxióngmāo.","vi":"Trên toàn thế giới chỉ Trung Quốc mới có gấu trúc hoang dã."},{"zh":"一般来说，熊猫每天要睡很多次觉。","pinyin":"Yìbān lái shuō, xióngmāo měitiān yào shuì hěn duō cì jiào.","vi":"Nói chung, gấu trúc mỗi ngày ngủ rất nhiều giấc."}]},"17":{"url":"https://tieng-trung-ha-hang.vercel.app/hsk3-bt17.html","keys":[{"zh":"你不是喜欢玩电脑吗？","pinyin":"Nǐ bú shì xǐhuan wán diànnǎo ma?","vi":"Chẳng phải bạn thích dùng máy tính sao?"},{"zh":"我还没想好学什么，更没想好去哪个国家。","pinyin":"Wǒ hái méi xiǎnghǎo xué shénme, gèng méi xiǎnghǎo qù nǎge guójiā.","vi":"Tôi chưa nghĩ xong học gì, lại càng chưa nghĩ xong đi nước nào."},{"zh":"只有想清楚自己真正喜欢什么，才能做出最合适的选择。","pinyin":"Zhǐyǒu xiǎng qīngchu zìjǐ zhēnzhèng xǐhuan shénme, cái néng zuò chū zuì héshì de xuǎnzé.","vi":"Chỉ khi nghĩ rõ mình thật sự thích gì mới chọn được lựa chọn phù hợp nhất."}]},"18":{"url":"https://tieng-trung-ha-hang.vercel.app/hsk3-bt18.html","keys":[{"zh":"春节是中国最重要的节日。","pinyin":"Chūnjié shì Zhōngguó zuì zhòngyào de jiérì.","vi":"Tết Nguyên đán là ngày lễ quan trọng nhất của Trung Quốc."},{"zh":"我刚刚看视频学会了包饺子。","pinyin":"Wǒ gānggāng kàn shìpín xuéhuì le bāo jiǎozi.","vi":"Tôi vừa xem video và học được cách gói sủi cảo."},{"zh":"只要一直坚持，就能完成自己的目标。","pinyin":"Zhǐyào yìzhí jiānchí, jiù néng wánchéng zìjǐ de mùbiāo.","vi":"Chỉ cần luôn kiên trì thì sẽ hoàn thành được mục tiêu của mình."}]}};
window.sceneData={"13":[
{label:"13-1 · Ở quán ăn",context:"Tại nhà hàng",contextZh:"在饭馆",sides:{"杨同乐":"L","王一雪":"R","同事":"R"},lines:[
["杨同乐","今天我请客，你们想吃什么就点什么！","Jīntiān wǒ qǐngkè, nǐmen xiǎng chī shénme jiù diǎn shénme!","Hôm nay tôi khao, các bạn muốn ăn gì thì cứ gọi nấy nhé!","请客 (qǐngkè): khao, mời khách · 想……就……: muốn gì thì làm nấy"],
["王一雪","那我就不客气了。听说这家饭馆的鱼做得很特别？","Nà wǒ jiù bú kèqi le. Tīngshuō zhè jiā fànguǎn de yú zuò de hěn tèbié?","Thế thì tôi không khách sáo nữa nhé. Nghe nói món cá ở quán này làm rất đặc biệt phải không?","不客气 (bú kèqi): đừng khách sáo · 听说 (tīngshuō): nghe nói"],
["杨同乐","对，南方菜跟你们北方菜的做法不同。除了鱼，你们还想吃什么？","Duì, nánfāng cài gēn nǐmen běifāng cài de zuòfǎ bù tóng. Chúle yú, nǐmen hái xiǎng chī shénme?","Đúng vậy, cách làm món miền Nam khác với món miền Bắc của các bạn. Ngoài cá ra, các bạn còn muốn ăn gì nữa?","南方 / 北方: miền Nam / miền Bắc · 做法 (zuòfǎ): cách làm · 不同 (bù tóng): khác nhau"],
["同事","我不常吃南方菜，还是你决定吧。","Wǒ bù cháng chī nánfāng cài, háishi nǐ juédìng ba.","Tôi không hay ăn món miền Nam, thôi bạn quyết định đi.","常 (cháng): thường · 还是……吧: thôi thì… vậy"],
["杨同乐","好，那再加一个鸡肉，一个……","Hǎo, nà zài jiā yí ge jīròu, yí ge...","Được, vậy thêm một món thịt gà nữa, một món……","加 (jiā): thêm vào · 鸡肉 (jīròu): thịt gà"],
["王一雪","咱们就三个人，别点那么多。","Zánmen jiù sān ge rén, bié diǎn nàme duō.","Chúng ta có ba người thôi, đừng gọi nhiều thế.","咱们 (zánmen): chúng ta (gồm cả người nghe) · 别……: đừng…"],
["杨同乐","好，那先来这几个菜。","Hǎo, nà xiān lái zhè jǐ ge cài.","Được, vậy trước mắt cứ lên mấy món này đã.","先 (xiān): trước tiên, trước đã"],
["王一雪","对了，下周我儿子过生日，你们有时间的话，就来我家做客，我给你们做北京菜。","Duì le, xià zhōu wǒ érzi guò shēngrì, nǐmen yǒu shíjiān dehuà, jiù lái wǒ jiā zuòkè, wǒ gěi nǐmen zuò Běijīng cài.","À phải rồi, tuần sau sinh nhật con trai tôi, nếu các bạn có thời gian thì đến nhà tôi chơi nhé, tôi sẽ nấu món Bắc Kinh đãi các bạn.","……的话，就……: nếu… thì… · 做客 (zuòkè): đến nhà ai làm khách · 过生日: đón sinh nhật"]]},
{label:"13-2 · Chuẩn bị đón khách",context:"Tại nhà",contextZh:"在家",sides:{"王一雪":"L","刘明":"R"},lines:[
["王一雪","第一次请新邻居来做客，总是担心有什么没准备好。","Dì-yī cì qǐng xīn línjū lái zuòkè, zǒngshì dānxīn yǒu shénme méi zhǔnbèi hǎo.","Lần đầu mời hàng xóm mới đến nhà chơi, lúc nào cũng lo có gì đó chưa chuẩn bị chu đáo.","邻居 (línjū): hàng xóm · 担心 (dānxīn): lo lắng · 准备 (zhǔnbèi): chuẩn bị"],
["刘明","放心吧，我帮你看了，都已经准备好了。","Fàngxīn ba, wǒ bāng nǐ kàn le, dōu yǐjīng zhǔnbèi hǎo le.","Yên tâm đi, anh xem giúp em rồi, mọi thứ đều đã chuẩn bị xong cả.","放心 (fàngxīn): yên tâm · 已经 (yǐjīng): đã"],
["王一雪","我记得刚才已经把饮料拿出来了，怎么不见了？","Wǒ jìde gāngcái yǐjīng bǎ yǐnliào ná chūlái le, zěnme bú jiàn le?","Em nhớ vừa nãy đã lấy đồ uống ra rồi cơ mà, sao lại không thấy đâu nữa?","把……拿出来: lấy… ra ngoài · 不见 (bú jiàn): biến mất, không thấy"],
["刘明","我把饮料和酒都放进冰箱里了，客人来了再拿出来。","Wǒ bǎ yǐnliào hé jiǔ dōu fàng jìn bīngxiāng lǐ le, kèrén lái le zài ná chūlái.","Anh cất cả đồ uống lẫn rượu vào tủ lạnh rồi, khách đến thì mới lấy ra.","酒 (jiǔ): rượu · 放 (fàng): đặt, cất · 冰箱 (bīngxiāng): tủ lạnh · 客人 (kèrén): khách"],
["王一雪","音乐的声音合适吗？","Yīnyuè de shēngyīn héshì ma?","Âm lượng nhạc như thế có vừa không?","声音 (shēngyīn): âm thanh, âm lượng · 合适 (héshì): phù hợp, vừa"],
["刘明","你把声音开得太大了，我去关小一点儿。","Nǐ bǎ shēngyīn kāi de tài dà le, wǒ qù guān xiǎo yìdiǎnr.","Em mở tiếng to quá rồi, để anh đi vặn nhỏ lại một chút.","把……开得太大了: mở… to quá mức · 一点儿 (yìdiǎnr): một chút"],
["王一雪","好，那我们就等客人来吧。","Hǎo, nà wǒmen jiù děng kèrén lái ba.","Được, vậy chúng ta chờ khách đến thôi.","等 (děng): chờ, đợi"]]},
{label:"13-3 · Tiệc sinh nhật",context:"Tại nhà",contextZh:"在家",sides:{"王一雪":"L","杨同乐":"R","刘小明":"R"},lines:[
["王一雪","谢谢你们来参加我儿子的生日晚会，希望大家今晚玩得开心。","Xièxie nǐmen lái cānjiā wǒ érzi de shēngrì wǎnhuì, xīwàng dàjiā jīnwǎn wán de kāixīn.","Cảm ơn mọi người đã đến dự buổi tiệc sinh nhật của con trai tôi, mong mọi người tối nay chơi thật vui.","晚会 (wǎnhuì): buổi tiệc tối · 参加 (cānjiā): tham dự"],
["杨同乐","小明，生日快乐！我准备了一个小礼物，希望你喜欢！","Xiǎomíng, shēngrì kuàilè! Wǒ zhǔnbèi le yí ge xiǎo lǐwù, xīwàng nǐ xǐhuan!","Tiểu Minh, chúc mừng sinh nhật! Chú chuẩn bị một món quà nhỏ, mong là cháu thích!","礼物 (lǐwù): quà tặng · 生日快乐: chúc mừng sinh nhật"],
["刘小明","谢谢您，我可以打开吗？","Xièxie nín, wǒ kěyǐ dǎkāi ma?","Cháu cảm ơn chú ạ, cháu mở ra được không?","您 (nín): kính ngữ của 你，dùng với người lớn · 打开 (dǎkāi): mở ra"],
["杨同乐","当然可以，你妈妈说你跟姐姐一样，都喜欢画画，对吗？","Dāngrán kěyǐ, nǐ māma shuō nǐ gēn jiějie yíyàng, dōu xǐhuan huàhuà, duì ma?","Đương nhiên được. Mẹ cháu nói cháu giống chị gái, đều thích vẽ tranh, đúng không?","跟……一样: giống như… · 画画 (huàhuà): vẽ tranh"],
["刘小明","对，我想做一名画家。啊！画板和画笔，这正是我需要的。我太喜欢了。","Duì, wǒ xiǎng zuò yì míng huàjiā. A! Huàbǎn hé huàbǐ, zhè zhèng shì wǒ xūyào de. Wǒ tài xǐhuan le.","Vâng ạ, cháu muốn làm họa sĩ. A! Bảng vẽ và bút vẽ, đúng là thứ cháu đang cần. Cháu thích lắm ạ!","画家 (huàjiā): họa sĩ · 正是 (zhèng shì): chính là · 需要 (xūyào): cần"],
["王一雪","我去把盘子拿过来，咱们一边吃蛋糕，一边聊天儿吧。","Wǒ qù bǎ pánzi ná guòlái, zánmen yìbiān chī dàngāo, yìbiān liáotiānr ba.","Để tôi đi lấy đĩa sang đây, chúng ta vừa ăn bánh vừa trò chuyện nhé.","盘子 (pánzi): cái đĩa · 一边……，一边……: vừa… vừa… · 聊天儿 (liáotiānr): trò chuyện"]]},
{label:"13-4 · Kể về hàng xóm mới",context:"Tại nhà",contextZh:"在家",sides:{"王一雪":"C"},lines:[
["王一雪","我的新邻居是来自英国的夫妻。上周我去他们家做客了。","Wǒ de xīn línjū shì láizì Yīngguó de fūqī. Shàng zhōu wǒ qù tāmen jiā zuòkè le.","Hàng xóm mới của tôi là một cặp vợ chồng đến từ nước Anh. Tuần trước tôi đã sang nhà họ chơi.","来自 (láizì): đến từ · 夫妻 (fūqī): vợ chồng · 英国 (Yīngguó): nước Anh"],
["王一雪","他们做了很多好吃的，还准备了英国的红茶。","Tāmen zuò le hěn duō hǎochī de, hái zhǔnbèi le Yīngguó de hóngchá.","Họ làm rất nhiều món ngon, còn chuẩn bị cả hồng trà Anh.","红茶 (hóngchá): hồng trà (trà đen kiểu Anh)"],
["王一雪","那天我跟他们一边喝红茶，一边聊天儿，直到十二点多才回家。","Nà tiān wǒ gēn tāmen yìbiān hē hóngchá, yìbiān liáotiānr, zhídào shí'èr diǎn duō cái huí jiā.","Hôm ấy tôi vừa uống hồng trà vừa trò chuyện với họ, mãi đến hơn mười hai giờ mới về nhà.","直到 (zhídào): cho đến tận · 一边……，一边……: vừa… vừa…"],
["王一雪","他们年轻的时候喜欢旅游，他家有一张世界地图，上面每一个红点都是他们去过的地方。","Tāmen niánqīng de shíhou xǐhuan lǚyóu, tā jiā yǒu yì zhāng shìjiè dìtú, shàngmiàn měi yí ge hóng diǎn dōu shì tāmen qù guo de dìfang.","Thời trẻ họ thích đi du lịch; nhà họ có một tấm bản đồ thế giới, mỗi chấm đỏ trên đó đều là nơi họ từng đến.","地图 (dìtú): bản đồ · 点 (diǎn): điểm, chấm"],
["王一雪","后来，他们感到东方的文化很特别，就开始学习中文。","Hòulái, tāmen gǎndào dōngfāng de wénhuà hěn tèbié, jiù kāishǐ xuéxí Zhōngwén.","Sau này, họ cảm thấy văn hóa phương Đông rất đặc biệt nên bắt đầu học tiếng Trung.","感到 (gǎndào): cảm thấy · 东方 (dōngfāng): phương Đông · 文化 (wénhuà): văn hóa"],
["王一雪","今天是小明的生日，我请他们到我家玩，来看看中国人的家，也尝尝中国菜。","Jīntiān shì Xiǎomíng de shēngrì, wǒ qǐng tāmen dào wǒ jiā wán, lái kànkan Zhōngguó rén de jiā, yě chángchang Zhōngguó cài.","Hôm nay là sinh nhật Tiểu Minh, tôi mời họ đến nhà tôi chơi, để xem nhà của người Trung Quốc và nếm thử món ăn Trung Quốc.","尝尝 (chángchang): nếm thử một chút"]]}
],"14":[{"label":"14-1 · Mượn sách thư viện","context":"Trong nhà ăn trường","contextZh":"在校园餐厅","sides":{"李文":"L","白家月":"R"},"lines":[["李文","我借的这本词典最好今天还，但是我没时间去。","Wǒ jiè de zhè běn cídiǎn zuìhǎo jīntiān huán, dànshì wǒ méi shíjiān qù.","Cuốn từ điển tôi mượn tốt nhất hôm nay trả, nhưng tôi không có thời gian đi."],["白家月","下午我只有两节课，可以帮你去图书馆还书。","Xiàwǔ wǒ zhǐ yǒu liǎng jié kè, kěyǐ bāng nǐ qù túshūguǎn huán shū.","Buổi chiều tôi chỉ có hai tiết, có thể giúp bạn đi thư viện trả sách."],["李文","那太谢谢了。你能再帮我借本书吗？","Nà tài xièxie le. Nǐ néng zài bāng wǒ jiè běn shū ma?","Vậy thì cảm ơn nhiều. Bạn có thể giúp tôi mượn thêm một cuốn sách nữa không?"],["白家月","行，你告诉我书名。","Xíng, nǐ gàosu wǒ shūmíng.","Được, bạn nói cho tôi tên sách."],["李文","我把名字写在纸上吧。我去了好几次图书馆，这本书都被别人借走了。","Wǒ bǎ míngzi xiě zài zhǐ shàng ba. Wǒ qù le hǎo jǐ cì túshūguǎn, zhè běn shū dōu bèi biérén jiè zǒu le.","Để tôi viết tên ra giấy nhé. Tôi đi thư viện mấy lần rồi, cuốn sách này đều bị người khác mượn mất."],["白家月","《名人的故事》？我有这本书。明天我借给你吧。","“Míngrén de Gùshi”? Wǒ yǒu zhè běn shū. Míngtiān wǒ jiè gěi nǐ ba.","«Câu chuyện danh nhân» à? Tôi có cuốn sách này. Ngày mai tôi cho bạn mượn nhé."]]},{"label":"14-2 · Kế hoạch buổi chiều","context":"Trong sân trường","contextZh":"在校园里","sides":{"安妮":"L","白家月":"R"},"lines":[["安妮","今天下课早，你一会儿做什么？","Jīntiān xiàkè zǎo, nǐ yíhuìr zuò shénme?","Hôm nay tan học sớm, lát nữa bạn làm gì?"],["白家月","我今天忙得很，要先去图书馆借书，然后去游泳。","Wǒ jīntiān máng de hěn, yào xiān qù túshūguǎn jiè shū, ránhòu qù yóuyǒng.","Hôm nay tôi bận lắm, phải đi thư viện mượn sách trước rồi đi bơi."],["安妮","咱们一起走吧，我想去图书馆看看中文报纸。","Zánmen yìqǐ zǒu ba, wǒ xiǎng qù túshūguǎn kànkan Zhōngwén bàozhǐ.","Chúng ta cùng đi nhé, tôi muốn đến thư viện xem báo tiếng Trung."],["白家月","等等，我的校园卡不见了，没有卡进不去图书馆。","Děngdeng, wǒ de xiàoyuánkǎ bú jiàn le, méiyǒu kǎ jìn bu qù túshūguǎn.","Khoan đã, thẻ sinh viên của tôi mất rồi, không có thẻ thì không vào được thư viện."],["安妮","你想想上一次用是什么时候？","Nǐ xiǎngxiang shàng yí cì yòng shì shénme shíhou?","Bạn nghĩ xem lần trước dùng là khi nào?"],["白家月","我忘记了，可能被我放在家里了。","Wǒ wàngjì le, kěnéng bèi wǒ fàng zài jiālǐ le.","Tôi quên rồi, có khi tôi để ở nhà rồi."],["安妮","进不去图书馆也没关系，上网看看有没有电子书。","Jìn bu qù túshūguǎn yě méi guānxi, shàngwǎng kànkan yǒu méiyǒu diànzǐshū.","Không vào được thư viện cũng không sao, lên mạng xem có sách điện tử không."],["白家月","不行，我必须去，我还得帮李文还书呢。","Bù xíng, wǒ bìxū qù, wǒ hái děi bāng Lǐ Wén huán shū ne.","Không được, tôi nhất định phải đi, tôi còn phải giúp Lý Văn trả sách nữa."]]},{"label":"14-3 · Tiết mục văn nghệ","context":"Trong nhà ăn trường","contextZh":"在校园餐厅","sides":{"李文":"L","白家月":"R"},"lines":[["李文","下周学校有晚会，你知道吗？","Xià zhōu xuéxiào yǒu wǎnhuì, nǐ zhīdào ma?","Tuần sau trường có dạ hội, bạn biết không?"],["白家月","知道，我和几个女生要表演一个节目。你也参加吗？","Zhīdào, wǒ hé jǐ ge nǚshēng yào biǎoyǎn yí ge jiémù. Nǐ yě cānjiā ma?","Biết chứ, tôi và mấy bạn nữ sẽ biểu diễn một tiết mục. Bạn cũng tham gia à?"],["李文","我想唱中文歌，但是还没找到人一起表演，不知道怎么办。","Wǒ xiǎng chàng Zhōngwén gē, dànshì hái méi zhǎodào rén yìqǐ biǎoyǎn, bù zhīdào zěnme bàn.","Tôi muốn hát tiếng Trung nhưng chưa tìm được người biểu diễn cùng, không biết làm sao."],["白家月","找不到人，你就一个人唱吧。","Zhǎo bu dào rén, nǐ jiù yí ge rén chàng ba.","Không tìm được người thì bạn hát một mình đi."],["李文","一想到要在校长、老师和那么多同学面前表演，我就有些紧张。","Yì xiǎngdào yào zài xiàozhǎng, lǎoshī hé nàme duō tóngxué miànqián biǎoyǎn, wǒ jiù yǒuxiē jǐnzhāng.","Vừa nghĩ đến việc phải biểu diễn trước thầy hiệu trưởng, các thầy cô và bao nhiêu bạn học là tôi hơi căng thẳng."],["白家月","紧张什么啊，我们都喜欢听你唱歌，你要相信自己。","Jǐnzhāng shénme a, wǒmen dōu xǐhuan tīng nǐ chànggē, nǐ yào xiāngxìn zìjǐ.","Căng thẳng gì chứ, chúng tôi đều thích nghe bạn hát, bạn phải tin vào bản thân mình."]]},{"label":"14-4 · Dạ hội năm mới","context":"白家月 kể chuyện","contextZh":"白家月讲述","sides":{"白家月":"C"},"lines":[["白家月","昨天是我们学校的新年晚会，每个班级的同学都表演节目了。","Zuótiān shì wǒmen xuéxiào de xīnnián wǎnhuì, měi ge bānjí de tóngxué dōu biǎoyǎn jiémù le.","Hôm qua là dạ hội năm mới của trường chúng tôi, học sinh mỗi lớp đều biểu diễn tiết mục."],["白家月","晚会是八点开始的，差不多十二点才结束。","Wǎnhuì shì bā diǎn kāishǐ de, chàbuduō shí'èr diǎn cái jiéshù.","Dạ hội tám giờ bắt đầu, gần mười hai giờ mới kết thúc."],["白家月","我一个晚上跟大家一起又唱又跳，开心极了，也累坏了。","Wǒ yí ge wǎnshang gēn dàjiā yìqǐ yòu chàng yòu tiào, kāixīn jí le, yě lèi huài le.","Cả buổi tối tôi cùng mọi người vừa hát vừa nhảy, vui cực kỳ mà cũng mệt nhoài."],["白家月","我最喜欢的节目是留学生们跳舞，最后老师和校长也被叫起来一块儿跳，特别有意思。","Wǒ zuì xǐhuan de jiémù shì liúxuéshēngmen tiàowǔ, zuìhòu lǎoshī hé xiàozhǎng yě bèi jiào qǐlái yíkuàir tiào, tèbié yǒuyìsi.","Tiết mục tôi thích nhất là lưu học sinh nhảy múa, cuối cùng thầy cô và thầy hiệu trưởng cũng bị gọi dậy nhảy cùng, thú vị vô cùng."],["白家月","过几天学校的网站上会有晚会的视频，我打算再看一遍。","Guò jǐ tiān xuéxiào de wǎngzhàn shàng huì yǒu wǎnhuì de shìpín, wǒ dǎsuàn zài kàn yí biàn.","Vài hôm nữa trên trang web của trường sẽ có video dạ hội, tôi định xem lại một lần nữa."]]}],"15":[{"label":"15-1 · Khu dân cư mới","context":"Trong văn phòng","contextZh":"在办公室里","sides":{"杨同乐":"L","王一雪":"R"},"lines":[["杨同乐","您搬到蓝天小区一段时间了，觉得怎么样？","Nín bān dào Lántiān Xiǎoqū yí duàn shíjiān le, juéde zěnmeyàng?","Bác chuyển đến khu Lam Thiên được một thời gian rồi, thấy thế nào ạ?"],["王一雪","小区环境挺好的，附近买东西也很方便，过马路就是超市。","Xiǎoqū huánjìng tǐng hǎo de, fùjìn mǎi dōngxi yě hěn fāngbiàn, guò mǎlù jiù shì chāoshì.","Môi trường khu dân cư khá tốt, mua đồ gần đây cũng rất tiện, qua đường là siêu thị."],["杨同乐","平时孩子们在哪儿玩？","Píngshí háizimen zài nǎr wán?","Bình thường bọn trẻ chơi ở đâu?"],["王一雪","小区里有很多树，孩子们放学后就在树下做游戏。你想买房子吗？","Xiǎoqū lǐ yǒu hěn duō shù, háizimen fàngxué hòu jiù zài shù xià zuò yóuxì. Nǐ xiǎng mǎi fángzi ma?","Trong khu có nhiều cây, bọn trẻ tan học xong chơi trò chơi dưới gốc cây. Bạn muốn mua nhà à?"],["杨同乐","是，我想买一个大房子，让我爸妈过来跟我一起住。","Shì, wǒ xiǎng mǎi yí ge dà fángzi, ràng wǒ bàmā guòlái gēn wǒ yìqǐ zhù.","Đúng vậy, tôi muốn mua một căn nhà lớn để bố mẹ tôi qua ở cùng tôi."],["王一雪","蓝天小区的老人挺多的，这几年小区根据他们的需要，有了很多变化。","Lántiān Xiǎoqū de lǎorén tǐng duō de, zhè jǐ nián xiǎoqū gēnjù tāmen de xūyào, yǒu le hěn duō biànhuà.","Người già ở khu Lam Thiên khá đông, mấy năm nay khu dân cư căn cứ vào nhu cầu của họ mà có nhiều thay đổi."],["杨同乐","真不错！过几天我去蓝天小区看看。","Zhēn búcuò! Guò jǐ tiān wǒ qù Lántiān Xiǎoqū kànkan.","Thật tốt! Vài hôm nữa tôi đến khu Lam Thiên xem thử."]]},{"label":"15-2 · Giới thiệu Nam Kinh","context":"Giới thiệu Nam Kinh","contextZh":"介绍南京","sides":{"王一雪":"L","杨同乐":"R"},"lines":[["王一雪","假期我想去南京旅游，但是我不太了解那里。","Jiàqī wǒ xiǎng qù Nánjīng lǚyóu, dànshì wǒ bú tài liǎojiě nàli.","Kỳ nghỉ tôi muốn đi Nam Kinh du lịch nhưng tôi không hiểu rõ về nơi đó lắm."],["杨同乐","我虽然不是南京人，可是我是在南京上的大学，可以说是半个南京人。","Wǒ suīrán bú shì Nánjīng rén, kěshì wǒ shì zài Nánjīng shàng de dàxué, kěyǐ shuō shì bàn ge Nánjīng rén.","Tuy tôi không phải người Nam Kinh nhưng tôi học đại học ở Nam Kinh, có thể nói là nửa người Nam Kinh."],["王一雪","太好了！你快给我介绍一下南京吧。","Tài hǎo le! Nǐ kuài gěi wǒ jièshào yíxià Nánjīng ba.","Tốt quá! Bạn mau giới thiệu Nam Kinh cho tôi đi."],["杨同乐","南京有两千年以上的历史，有老城、老街，还有很多有名的景点，每年去旅游的游客特别多。","Nánjīng yǒu liǎng qiān nián yǐshàng de lìshǐ, yǒu lǎochéng, lǎojiē, hái yǒu hěn duō yǒumíng de jǐngdiǎn, měinián qù lǚyóu de yóukè tèbié duō.","Nam Kinh có lịch sử hơn hai nghìn năm, có thành cổ, phố cổ, còn có nhiều điểm tham quan nổi tiếng, mỗi năm khách du lịch đến đặc biệt đông."],["王一雪","除了这些以外，你再告诉我一些外地人不知道的地方。","Chúle zhèxiē yǐwài, nǐ zài gàosu wǒ yìxiē wàidì rén bù zhīdào de dìfang.","Ngoài những thứ này ra, bạn nói cho tôi thêm vài nơi người ngoài không biết đi."],["杨同乐","那太多了，我得一点儿一点儿给您讲。","Nà tài duō le, wǒ děi yìdiǎnr yìdiǎnr gěi nín jiǎng.","Cái đó thì nhiều lắm, tôi phải kể cho bác từng chút một."],["王一雪","行。下班后我请你吃晚饭，咱们边吃边聊。","Xíng. Xiàbān hòu wǒ qǐng nǐ chī wǎnfàn, zánmen biān chī biān liáo.","Được. Sau giờ làm tôi mời bạn ăn tối, chúng ta vừa ăn vừa nói chuyện."]]},{"label":"15-3 · Đố vui Hoàng Hà","context":"Ở nhà","contextZh":"在家里","sides":{"王一雪":"L","刘小明":"R"},"lines":[["王一雪","小明，中国有一条大河，它的名字跟颜色有关系，你知道是什么河吗？","Xiǎomíng, Zhōngguó yǒu yì tiáo dà hé, tā de míngzi gēn yánsè yǒu guānxi, nǐ zhīdào shì shénme hé ma?","Tiểu Minh, Trung Quốc có một con sông lớn, tên của nó có liên quan đến màu sắc, em biết là sông nào không?"],["刘小明","我知道，是黄河！","Wǒ zhīdào, shì Huáng Hé!","Em biết, là Hoàng Hà!"],["王一雪","你说对了。我再问问你，你知道它为什么叫黄河吗？","Nǐ shuō duì le. Wǒ zài wènwen nǐ, nǐ zhīdào tā wèishénme jiào Huáng Hé ma?","Em nói đúng rồi. Chị hỏi thêm em, em biết tại sao nó gọi là Hoàng Hà không?"],["刘小明","因为河水看起来是黄色的，所以叫这个名字。黄河是中国最长的河吗？","Yīnwèi héshuǐ kàn qǐlái shì huángsè de, suǒyǐ jiào zhège míngzi. Huáng Hé shì Zhōngguó zuì cháng de hé ma?","Vì nước sông nhìn có màu vàng nên gọi tên này. Hoàng Hà có phải sông dài nhất Trung Quốc không?"],["王一雪","不是。黄河虽然不是最长的河，可是在历史上很重要。","Bú shì. Huáng Hé suīrán bú shì zuì cháng de hé, kěshì zài lìshǐ shàng hěn zhòngyào.","Không phải. Hoàng Hà tuy không phải sông dài nhất nhưng trong lịch sử rất quan trọng."],["刘小明","这个我知道。很久以前，很多中国人都住在黄河边上。","Zhège wǒ zhīdào. Hěn jiǔ yǐqián, hěn duō Zhōngguó rén dōu zhù zài Huáng Hé biān shàng.","Cái này em biết. Rất lâu trước đây, nhiều người Trung Quốc sống bên bờ Hoàng Hà."],["王一雪","对。在我们中国人看来，黄河像妈妈一样，养了我们几千年。","Duì. Zài wǒmen Zhōngguó rén kànlái, Huáng Hé xiàng māma yíyàng, yǎng le wǒmen jǐ qiān nián.","Đúng. Trong mắt người Trung Quốc chúng ta, Hoàng Hà như mẹ vậy, nuôi chúng ta mấy nghìn năm."]]},{"label":"15-4 · Tuổi thơ bên sông","context":"王一雪 kể chuyện","contextZh":"王一雪讲述","sides":{"王一雪":"C"},"lines":[["王一雪","我小时候住在北京的西北边，有一条非常有名的河经过那里。","Wǒ xiǎoshíhou zhù zài Běijīng de xīběi biān, yǒu yì tiáo fēicháng yǒumíng de hé jīngguò nàli.","Hồi nhỏ tôi sống ở phía tây bắc Bắc Kinh, có một con sông rất nổi tiếng chảy qua đó."],["王一雪","我家就住在河边。","Wǒ jiā jiù zhù zài hébiān.","Nhà tôi ở ngay bên sông."],["王一雪","那里有高高的大树和绿绿的草地。","Nàli yǒu gāogāo de dàshù hé lǜlǜ de cǎodì.","Ở đó có cây cao và bãi cỏ xanh mướt."],["王一雪","春天，河边的花都开了，看起来特别漂亮。","Chūntiān, hébiān de huā dōu kāi le, kàn qǐlái tèbié piàoliang.","Mùa xuân, hoa bên sông đều nở, nhìn đặc biệt đẹp."],["王一雪","还记得小时候，一到夏天我就去河里游泳。","Hái jìde xiǎoshíhou, yí dào xiàtiān wǒ jiù qù hé lǐ yóuyǒng.","Còn nhớ hồi nhỏ, cứ đến hè là tôi đi bơi ở sông."],["王一雪","长大以后，遇到什么不开心的事情，我就去河边的树下坐着，听听鸟叫，看看河水，跟遇见的朋友聊聊天儿，难过的事情不一会儿就忘了。","Zhǎngdà yǐhòu, yùdào shénme bù kāixīn de shìqing, wǒ jiù qù hébiān de shù xià zuòzhe, tīngting niǎo jiào, kànkan héshuǐ, gēn yùjiàn de péngyou liáoliao tiānr, nánguò de shìqing bù yíhuìr jiù wàng le.","Sau khi lớn lên, gặp chuyện gì không vui, tôi lại đến ngồi dưới gốc cây bên sông, nghe chim hót, ngắm nước sông, trò chuyện với bạn bè gặp được, chuyện buồn chẳng mấy chốc đã quên."],["王一雪","那是我最喜欢的地方。","Nà shì wǒ zuì xǐhuan de dìfang.","Đó là nơi tôi thích nhất."]]}],"10":[{"label":"10-1 · Bàn về phương pháp học","context":"Trong lớp học","contextZh":"在教室里","sides":{"同学":"L","刘小雪":"R"},"lines":[["同学","你的数学越来越好，能不能介绍一下学习方法？","Nǐ de shùxué yuèláiyuè hǎo, néng bu néng jièshào yíxià xuéxí fāngfǎ?","Toán của bạn càng ngày càng giỏi, bạn có thể giới thiệu một chút về phương pháp học tập không?"],["刘小雪","没有什么特别的方法，认真听课，认真记笔记。","Méiyǒu shénme tèbié de fāngfǎ, rènzhēn tīngkè, rènzhēn jì bǐjì.","Không có phương pháp gì đặc biệt đâu, nghe giảng nghiêm túc và ghi chép cẩn thận."],["同学","我看过你的笔记，记得非常清楚。","Wǒ kàn guo nǐ de bǐjì, jì de fēicháng qīngchu.","Tôi đã xem ghi chép của bạn rồi, ghi rất rõ ràng."],["刘小雪","老师写在黑板上的题都很重要，所以我会把这些题都记在本子上。","Lǎoshī xiě zài hēibǎn shàng de tí dōu hěn zhòngyào, suǒyǐ wǒ huì bǎ zhèxiē tí dōu jì zài běnzi shàng.","Những bài tập thầy cô viết trên bảng đều rất quan trọng, nên tôi ghi hết những bài đó vào vở."],["同学","你说得对。我没有记笔记的习惯。","Nǐ shuō de duì. Wǒ méiyǒu jì bǐjì de xíguàn.","Bạn nói đúng. Tôi không có thói quen ghi chép."],["刘小雪","笔记挺重要的，我每天写作业以前，都要看一遍。","Bǐjì tǐng zhòngyào de, wǒ měitiān xiě zuòyè yǐqián, dōu yào kàn yí biàn.","Ghi chép quan trọng lắm, mỗi ngày trước khi làm bài tập tôi đều xem lại một lượt."],["同学","这个方法真好！我以后也试试，希望能提高成绩。","Zhège fāngfǎ zhēn hǎo! Wǒ yǐhòu yě shìshi, xīwàng néng tígāo chéngjì.","Phương pháp này hay thật! Sau này tôi cũng thử xem, hy vọng có thể nâng cao thành tích."]]},{"label":"10-2 · Bàn về kỳ thi","context":"Trong lớp học","contextZh":"在教室里","sides":{"同学":"L","刘小雪":"R"},"lines":[["同学","小雪，昨天的考试，你考得怎么样？","Xiǎoxuě, zuótiān de kǎoshì, nǐ kǎo de zěnmeyàng?","Tiểu Tuyết, bài kiểm tra hôm qua bạn làm thế nào?"],["刘小雪","我觉得历史有点儿难，你呢？","Wǒ juéde lìshǐ yǒudiǎnr nán, nǐ ne?","Tôi thấy môn Lịch sử hơi khó, còn bạn thì sao?"],["同学","数学考试我没看清楚要求，做错了好几个题，考得挺差的。","Shùxué kǎoshì wǒ méi kàn qīngchu yāoqiú, zuò cuò le hǎo jǐ ge tí, kǎo de tǐng chà de.","Bài thi Toán tôi không đọc rõ yêu cầu, làm sai mấy bài, thi khá tệ."],["刘小雪","明天还有考试呢，别想那么多了，先复习外语吧。","Míngtiān hái yǒu kǎoshì ne, bié xiǎng nàme duō le, xiān fùxí wàiyǔ ba.","Ngày mai còn thi nữa đấy, đừng nghĩ nhiều nữa, ôn ngoại ngữ trước đi."],["同学","外语作业里有几个问题，我可以问问你吗？","Wàiyǔ zuòyè lǐ yǒu jǐ ge wèntí, wǒ kěyǐ wènwen nǐ ma?","Trong bài tập ngoại ngữ có vài câu hỏi, tôi hỏi bạn được không?"],["刘小雪","当然可以。在学习上，遇到什么问题都可以问我。","Dāngrán kěyǐ. Zài xuéxí shàng, yùdào shénme wèntí dōu kěyǐ wèn wǒ.","Đương nhiên được. Trong học tập, gặp vấn đề gì cũng có thể hỏi tôi."],["刘小雪","不好意思，这几个题我也不会。咱们还是一起去办公室问问李老师吧。","Bù hǎoyìsi, zhè jǐ ge tí wǒ yě bú huì. Zánmen háishi yìqǐ qù bàngōngshì wènwen Lǐ lǎoshī ba.","Xin lỗi nhé, mấy câu này tôi cũng không biết. Chúng ta cùng đến văn phòng hỏi thầy Lý vậy."]]},{"label":"10-3 · Hỏi bài thầy Lý","context":"Trong văn phòng thầy Lý","contextZh":"在李老师办公室","sides":{"同学":"L","李老师":"R","刘小雪":"R"},"lines":[["同学","李老师，书上有几个问题，我们想问问您。","Lǐ lǎoshī, shū shàng yǒu jǐ ge wèntí, wǒmen xiǎng wènwen nín.","Thầy Lý ơi, trong sách có vài câu hỏi, chúng em muốn hỏi thầy."],["李老师","好，坐下说吧，哪个题不会？","Hǎo, zuòxia shuō ba, nǎ ge tí bú huì?","Được, ngồi xuống nói đi, bài nào không biết?"],["同学","书上第五页的这个对话我看不懂，小雪也不明白。","Shū shàng dì wǔ yè de zhège duìhuà wǒ kàn bù dǒng, Xiǎoxuě yě bù míngbai.","Đoạn hội thoại ở trang 5 trong sách em đọc không hiểu, Tiểu Tuyết cũng không hiểu."],["李老师","我课上讲过这几句话，再给你们讲一遍。","Wǒ kè shàng jiǎng guo zhè jǐ jù huà, zài gěi nǐmen jiǎng yí biàn.","Mấy câu này tôi đã giảng trên lớp rồi, giảng lại cho các em một lần nữa."],["同学","我终于懂了。这些句子一点儿也不难。","Wǒ zhōngyú dǒng le. Zhèxiē jùzi yìdiǎnr yě bù nán.","Cuối cùng em đã hiểu. Những câu này chẳng khó chút nào."],["刘小雪","我也明白了，谢谢您，李老师。","Wǒ yě míngbai le, xièxie nín, Lǐ lǎoshī.","Em cũng hiểu rồi, cảm ơn thầy ạ, thầy Lý."],["李老师","我这本书上还有几个练习，你们回家也做一做，明天再把书还给我。","Wǒ zhè běn shū shàng hái yǒu jǐ ge liànxí, nǐmen huí jiā yě zuò yi zuò, míngtiān zài bǎ shū huán gěi wǒ.","Trong cuốn sách này của tôi còn vài bài tập, các em về nhà cũng làm thử đi, ngày mai trả lại sách cho tôi."]]},{"label":"10-4 · Thư gửi chị Gia Nguyệt","context":"Ở nhà","contextZh":"在家里","sides":{"刘小雪":"C"},"lines":[["刘小雪","家月姐姐：你最近怎么样？忙不忙？","Jiāyuè jiějie: Nǐ zuìjìn zěnmeyàng? Máng bu máng?","Chị Gia Nguyệt, gần đây chị thế nào? Có bận không?"],["刘小雪","我现在上初中二年级，学习越来越忙，后年就要考高中了。","Wǒ xiànzài shàng chūzhōng èr niánjí, xuéxí yuèláiyuè máng, hòunián jiù yào kǎo gāozhōng le.","Em hiện học lớp 8, việc học ngày càng bận, năm kia sẽ thi cấp 3."],["刘小雪","中国的学校一般是小学六年，初中三年，高中三年。","Zhōngguó de xuéxiào yìbān shì xiǎoxué liù nián, chūzhōng sān nián, gāozhōng sān nián.","Trường học ở Trung Quốc thường là tiểu học 6 năm, trung học cơ sở 3 năm, trung học phổ thông 3 năm."],["刘小雪","妈妈说想考上好大学，就得上一个好高中；为了考上好高中，初中就得有一个不错的成绩，所以我现在非常努力。","Māma shuō xiǎng kǎo shàng hǎo dàxué, jiù děi shàng yí ge hǎo gāozhōng; wèile kǎo shàng hǎo gāozhōng, chūzhōng jiù děi yǒu yí ge búcuò de chéngjì, suǒyǐ wǒ xiànzài fēicháng nǔlì.","Mẹ nói muốn đỗ đại học tốt thì phải học cấp 3 tốt; để học cấp 3 tốt thì cấp 2 phải có thành tích khá, nên giờ em rất chăm chỉ."],["刘小雪","家月姐姐，你知道吗？在你的影响下，我也开始喜欢拍照了。","Jiāyuè jiějie, nǐ zhīdào ma? Zài nǐ de yǐngxiǎng xià, wǒ yě kāishǐ xǐhuan pāizhào le.","Chị Gia Nguyệt, chị biết không? Nhờ ảnh hưởng của chị mà em cũng bắt đầu thích chụp ảnh."],["刘小雪","下次你再来北京，我给你看看我照的照片。","Xià cì nǐ zài lái Běijīng, wǒ gěi nǐ kànkan wǒ zhào de zhàopiàn.","Lần sau chị đến Bắc Kinh, em cho chị xem những bức ảnh em chụp."]]}],
"11":[{"label":"11-1 · Chuẩn bị cuộc họp","context":"Chuẩn bị cuộc họp","contextZh":"准备开会","sides":{"王一雪":"L","杨同乐":"R"},"lines":[["王一雪","会议下午几点开始？","Huìyì xiàwǔ jǐ diǎn kāishǐ?","Cuộc họp chiều nay bắt đầu lúc mấy giờ?"],["杨同乐","今天下午经理不在，不开会了。","Jīntiān xiàwǔ jīnglǐ bú zài, bù kāihuì le.","Chiều nay giám đốc không có mặt nên không họp nữa."],["王一雪","那什么时候开会？","Nà shénme shíhou kāihuì?","Vậy khi nào thì họp?"],["杨同乐","后天上午十点，会议地点换到第一会议室。我正要给大家发邮件。","Hòutiān shàngwǔ shí diǎn, huìyì dìdiǎn huàn dào dì-yī huìyìshì. Wǒ zhèng yào gěi dàjiā fā yóujiàn.","Mười giờ sáng ngày kia, địa điểm họp đổi sang phòng họp số một. Tôi đang định gửi email cho mọi người."],["王一雪","开会的时候，我们用会议室的电脑还是自己的笔记本电脑？","Kāihuì de shíhou, wǒmen yòng huìyìshì de diànnǎo háishi zìjǐ de bǐjìběn diànnǎo?","Lúc họp, chúng ta dùng máy tính của phòng họp hay máy tính xách tay của mình?"],["杨同乐","会议室的电脑或者自己的电脑都可以。","Huìyìshì de diànnǎo huòzhě zìjǐ de diànnǎo dōu kěyǐ.","Dùng máy tính của phòng họp hay máy tính của mình đều được."],["王一雪","那到时候咱们早点儿过去，你帮我把电脑接好吧。","Nà dào shíhou zánmen zǎo diǎnr guòqù, nǐ bāng wǒ bǎ diànnǎo jiē hǎo ba.","Vậy đến lúc đó chúng ta qua sớm một chút, bạn giúp tôi nối máy tính nhé."]]},{"label":"11-2 · Nối máy tính","context":"Nối máy tính","contextZh":"接电脑","sides":{"王一雪":"L","杨同乐":"R"},"lines":[["王一雪","电脑接好了吗？","Diànnǎo jiē hǎo le ma?","Nối máy tính xong chưa?"],["杨同乐","已经接好了，您开机看看有没有问题。","Yǐjīng jiē hǎo le, nín kāijī kànkan yǒu méiyǒu wèntí.","Nối xong rồi ạ, chị bật máy xem có vấn đề gì không."],["王一雪","现在什么都看不见。","Xiànzài shénme dōu kàn bu jiàn.","Bây giờ chẳng nhìn thấy gì cả."],["杨同乐","我检查一下哪里出问题了……您再试一下。","Wǒ jiǎnchá yíxià nǎlǐ chū wèntí le... Nín zài shì yíxià.","Để tôi kiểm tra xem chỗ nào có vấn đề… Chị thử lại xem."],["王一雪","看见了，但是听不见声音。","Kànjiàn le, dànshì tīng bu jiàn shēngyīn.","Nhìn thấy rồi, nhưng không nghe thấy tiếng."],["杨同乐","现在呢？","Xiànzài ne?","Bây giờ thì sao?"],["王一雪","听得见声音，但是声音有点儿小，听不清楚。","Tīng de jiàn shēngyīn, dànshì shēngyīn yǒudiǎnr xiǎo, tīng bu qīngchu.","Nghe thấy tiếng rồi, nhưng tiếng hơi nhỏ, nghe không rõ."],["杨同乐","看来我没办法解决这个问题，只能找别人来帮帮忙了。","Kànlái wǒ méi bànfǎ jiějué zhège wèntí, zhǐnéng zhǎo biérén lái bāngbangmáng le.","Xem ra tôi không giải quyết được vấn đề này, chỉ còn cách tìm người khác đến giúp thôi."]]},{"label":"11-3 · Đồng nghiệp nghỉ phép","context":"Đồng nghiệp nghỉ phép","contextZh":"同事请假","sides":{"王一雪":"L","杨同乐":"R"},"lines":[["王一雪","同乐，你看见老张了吗？","Tónglè, nǐ kànjiàn Lǎo Zhāng le ma?","Đồng Lạc, bạn có thấy lão Trương không?"],["杨同乐","老张没来。他说家里有点儿事，所以请假了。","Lǎo Zhāng méi lái. Tā shuō jiālǐ yǒudiǎnr shì, suǒyǐ qǐngjià le.","Lão Trương không đến. Anh ấy nói nhà có chút việc nên xin nghỉ rồi."],["王一雪","好几个同事都休假了，开会前这么多工作我怕干不完。","Hǎo jǐ ge tóngshì dōu xiūjià le, kāihuì qián zhème duō gōngzuò wǒ pà gàn bu wán.","Mấy đồng nghiệp đều nghỉ phép rồi, trước cuộc họp còn nhiều việc thế này tôi sợ làm không xong."],["杨同乐","十二点多了，咱们先去吃饭吧。吃完饭，我跟您一起把这些工作做完。","Shí'èr diǎn duō le, zánmen xiān qù chīfàn ba. Chī wán fàn, wǒ gēn nín yìqǐ bǎ zhèxiē gōngzuò zuò wán.","Hơn mười hai giờ rồi, chúng ta đi ăn trước đã. Ăn xong tôi cùng chị làm nốt những việc này."],["王一雪","你先去吃，我想再干一会儿。明天开会前要发到公司的邮箱里。","Nǐ xiān qù chī, wǒ xiǎng zài gàn yíhuìr. Míngtiān kāihuì qián yào fā dào gōngsī de yóuxiāng lǐ.","Bạn đi ăn trước đi, tôi muốn làm thêm một lúc nữa. Trước cuộc họp ngày mai phải gửi vào email công ty."],["杨同乐","您没看到邮件吗？经理还没回来呢，下周才能开会。","Nín méi kàndào yóujiàn ma? Jīnglǐ hái méi huílái ne, xià zhōu cái néng kāihuì.","Chị không thấy email à? Giám đốc còn chưa về, tuần sau mới họp được."],["王一雪","那不着急了。走，吃饭去。","Nà bù zháojí le. Zǒu, chīfàn qù.","Vậy thì không vội nữa. Đi, đi ăn thôi."]]},{"label":"11-4 · Nhật ký: có nên đi Thượng Hải?","context":"王一雪 kể chuyện","contextZh":"王一雪讲述","sides":{"王一雪":"C"},"lines":[["王一雪","前几天，上海的同事来北京了。","Qián jǐ tiān, Shànghǎi de tóngshì lái Běijīng le.","Mấy hôm trước, đồng nghiệp ở Thượng Hải đến Bắc Kinh."],["王一雪","一起吃饭时，他们跟我说最近有不少同事去上海工作了，问我愿意不愿意也去上海。","Yìqǐ chīfàn shí, tāmen gēn wǒ shuō zuìjìn yǒu bù shǎo tóngshì qù Shànghǎi gōngzuò le, wèn wǒ yuànyì bu yuànyì yě qù Shànghǎi.","Lúc cùng nhau ăn cơm, họ nói với tôi gần đây có không ít đồng nghiệp đi Thượng Hải làm việc, hỏi tôi có muốn đi Thượng Hải không."],["王一雪","我是这样想的：现在丈夫和孩子都在北京，刘明的工作很忙，小雪和小明也还小，我去别的城市工作就要离开他们。","Wǒ shì zhèyàng xiǎng de: xiànzài zhàngfu hé háizi dōu zài Běijīng, Liú Míng de gōngzuò hěn máng, Xiǎoxuě hé Xiǎomíng yě hái xiǎo, wǒ qù bié de chéngshì gōngzuò jiù yào líkāi tāmen.","Tôi nghĩ thế này: bây giờ chồng và con đều ở Bắc Kinh, công việc của Lưu Minh rất bận, Tiểu Tuyết và Tiểu Minh còn nhỏ, tôi đi thành phố khác làm việc sẽ phải rời xa họ."],["王一雪","虽然去上海可能会有更好的机会，但是对我来说，生活也很重要，我不愿意为工作或学习离开家人。","Suīrán qù Shànghǎi kěnéng huì yǒu gèng hǎo de jīhuì, dànshì duì wǒ lái shuō, shēnghuó yě hěn zhòngyào, wǒ bù yuànyì wèi gōngzuò huò xuéxí líkāi jiārén.","Tuy đi Thượng Hải có thể có cơ hội tốt hơn, nhưng đối với tôi, cuộc sống cũng rất quan trọng, tôi không muốn vì công việc hay học tập mà rời xa gia đình."]]}],
"12":[{"label":"12-1 · Rủ nhau đi công viên","context":"Trên phố","contextZh":"在街上","sides":{"白家月":"L","王一飞":"R"},"lines":[["白家月","王老师，您看，这条街上的树都开花了。","Wáng lǎoshī, nín kàn, zhè tiáo jiē shàng de shù dōu kāihuā le.","Thầy Vương, thầy xem này, cây trên phố này đều nở hoa rồi."],["王一飞","上周我去公园坐船了，公园里的花也开了。","Shàng zhōu wǒ qù gōngyuán zuò chuán le, gōngyuán lǐ de huā yě kāi le.","Tuần trước tôi đi công viên ngồi thuyền, hoa trong công viên cũng nở rồi."],["白家月","天气这么好，下午我也想去公园坐船。","Tiānqì zhème hǎo, xiàwǔ wǒ yě xiǎng qù gōngyuán zuò chuán.","Thời tiết đẹp thế này, chiều nay tôi cũng muốn đi công viên ngồi thuyền."],["王一飞","去吧！今天是工作日，人应该不多。","Qù ba! Jīntiān shì gōngzuòrì, rén yīnggāi bù duō.","Đi đi! Hôm nay là ngày làm việc, người chắc không đông."],["白家月","您有时间吗？我想跟您一起去。","Nín yǒu shíjiān ma? Wǒ xiǎng gēn nín yìqǐ qù.","Thầy có thời gian không? Tôi muốn đi cùng thầy."],["王一飞","我今天下午有课，不能去太远的地方。","Wǒ jīntiān xiàwǔ yǒu kè, bù néng qù tài yuǎn de dìfang.","Chiều nay tôi có tiết, không đi chỗ xa được."],["白家月","那咱们换一天去？","Nà zánmen huàn yì tiān qù?","Vậy chúng ta đổi sang hôm khác đi?"],["王一飞","行。或者明天去，或者后天去，我给你打电话。","Xíng. Huòzhě míngtiān qù, huòzhě hòutiān qù, wǒ gěi nǐ dǎ diànhuà.","Được. Hoặc ngày mai đi, hoặc ngày kia đi, tôi gọi điện cho bạn."]]},{"label":"12-2 · Trời bỗng đổi gió","context":"Trời đổi gió","contextZh":"天气变化","sides":{"白家月":"L","王一飞":"R"},"lines":[["白家月","刚才还是大晴天呢，怎么突然就刮起风来了？","Gāngcái háishi dà qíngtiān ne, zěnme tūrán jiù guā qǐ fēng lái le?","Vừa nãy còn nắng to, sao đột nhiên nổi gió thế?"],["王一飞","好像新闻里说今天有雨。","Hǎoxiàng xīnwén lǐ shuō jīntiān yǒu yǔ.","Hình như tin tức nói hôm nay có mưa."],["白家月","啊？我每天书包里都放着雨伞，就今天没带。","A? Wǒ měitiān shūbāo lǐ dōu fàngzhe yǔsǎn, jiù jīntiān méi dài.","Hả? Ngày nào trong cặp tôi cũng để ô, chỉ hôm nay không mang."],["王一飞","我可以借给你，我车里有一把伞和一件雨衣。","Wǒ kěyǐ jiè gěi nǐ, wǒ chē lǐ yǒu yì bǎ sǎn hé yí jiàn yǔyī.","Tôi cho bạn mượn được, trong xe tôi có một cái ô và một cái áo mưa."],["白家月","谢谢，希望下午天气能变好。","Xièxie, xīwàng xiàwǔ tiānqì néng biàn hǎo.","Cảm ơn, hy vọng chiều nay thời tiết khá hơn."],["王一飞","这个季节天气变化很快。","Zhège jìjié tiānqì biànhuà hěn kuài.","Mùa này thời tiết thay đổi nhanh lắm."],["白家月","雨已经下起来了，咱们快点儿走吧。","Yǔ yǐjīng xià qǐlái le, zánmen kuài diǎnr zǒu ba.","Mưa rơi rồi, chúng ta đi nhanh thôi."]]},{"label":"12-3 · Chuyện thời tiết","context":"Chuyện thời tiết","contextZh":"聊天气","sides":{"白家月":"L","王一飞":"R"},"lines":[["白家月","您来这里已经一年多了，习惯了吧？","Nín lái zhèlǐ yǐjīng yì nián duō le, xíguàn le ba?","Thầy đến đây hơn một năm rồi, quen rồi chứ?"],["王一飞","别的早就习惯了，就是天气我还不太习惯。","Bié de zǎo jiù xíguàn le, jiùshì tiānqì wǒ hái bú tài xíguàn.","Những thứ khác quen từ lâu rồi, chỉ có thời tiết là tôi còn chưa quen lắm."],["白家月","为什么？您不喜欢这里的天气吗？","Wèishénme? Nín bù xǐhuan zhèlǐ de tiānqì ma?","Tại sao ạ? Thầy không thích thời tiết ở đây sao?"],["王一飞","我觉得冬天太冷了。","Wǒ juéde dōngtiān tài lěng le.","Tôi thấy mùa đông lạnh quá."],["白家月","冬天虽然冷，但是下雪的时候特别漂亮。","Dōngtiān suīrán lěng, dànshì xiàxuě de shíhou tèbié piàoliang.","Mùa đông tuy lạnh nhưng lúc tuyết rơi thì đẹp vô cùng."],["王一飞","我也喜欢雪。北京常常下雪，但听说今年就下了一次。","Wǒ yě xǐhuan xuě. Běijīng chángcháng xiàxuě, dàn tīngshuō jīnnián jiù xià le yí cì.","Tôi cũng thích tuyết. Bắc Kinh thường xuyên có tuyết, nhưng nghe nói năm nay mới rơi có một lần."],["白家月","我没关注过北京的天气，但是新闻里说过，今年冬天很多地方雪下得都少了。","Wǒ méi guānzhù guo Běijīng de tiānqì, dànshì xīnwén lǐ shuō guo, jīnnián dōngtiān hěn duō dìfang xuě xià de dōu shǎo le.","Tôi không để ý thời tiết Bắc Kinh, nhưng tin tức có nói mùa đông năm nay nhiều nơi tuyết rơi ít hẳn."]]},{"label":"12-4 · Nhật ký: bốn mùa Bắc Kinh","context":"王一飞 kể chuyện","contextZh":"王一飞讲述","sides":{"王一飞":"C"},"lines":[["王一飞","我离开北京到这里工作一年多了。","Wǒ líkāi Běijīng dào zhèlǐ gōngzuò yì nián duō le.","Tôi rời Bắc Kinh đến đây làm việc hơn một năm rồi."],["王一飞","这一年多住下来，我还是更喜欢北京的四季。","Zhè yì nián duō zhù xiàlái, wǒ háishi gèng xǐhuan Běijīng de sìjì.","Sống ở đây hơn một năm, tôi vẫn thích bốn mùa của Bắc Kinh hơn."],["王一飞","北京的春天最舒服，天气不冷不热。","Běijīng de chūntiān zuì shūfu, tiānqì bù lěng bù rè.","Mùa xuân Bắc Kinh dễ chịu nhất, thời tiết không lạnh không nóng."],["王一飞","夏天白天很热，但是晚上比较凉快。","Xiàtiān báitiān hěn rè, dànshì wǎnshang bǐjiào liángkuai.","Mùa hè ban ngày rất nóng nhưng buổi tối khá mát."],["王一飞","秋天树上的叶子都变成了红色、黄色，非常漂亮。","Qiūtiān shù shàng de yèzi dōu biànchéng le hóngsè, huángsè, fēicháng piàoliang.","Mùa thu lá trên cây đều chuyển sang đỏ, vàng, đẹp vô cùng."],["王一飞","冬天不但冷，而且风很大，我最不喜欢冬天。","Dōngtiān bùdàn lěng, érqiě fēng hěn dà, wǒ zuì bù xǐhuan dōngtiān.","Mùa đông không những lạnh mà gió còn to, tôi ghét nhất mùa đông."],["王一飞","每个人都有自己最喜欢的季节，你最喜欢哪个季节呢？","Měi ge rén dōu yǒu zìjǐ zuì xǐhuan de jìjié, nǐ zuì xǐhuan nǎ ge jìjié ne?","Mỗi người đều có mùa mình thích nhất, bạn thích nhất mùa nào?"]]}],"16":[{"label":"16-1 · Mèo con ở quán","context":"Con mèo của quán","contextZh":"小猫","sides":{"刘小雪":"L","服务员":"R","王一雪":"R"},"lines":[["刘小雪","这只小猫你们养了多久了？","Zhè zhī xiǎomāo nǐmen yǎng le duō jiǔ le?","Con mèo con này quán mình nuôi bao lâu rồi ạ?"],["服务员","已经一年多了。第一天看见它的时候，它又脏又小。","Yǐjīng yì nián duō le. Dì-yī tiān kànjiàn tā de shíhou, tā yòu zāng yòu xiǎo.","Được hơn một năm rồi. Ngày đầu tiên nhìn thấy nó, nó vừa bẩn vừa nhỏ."],["刘小雪","现在它变得又干净又漂亮了。","Xiànzài tā biàn de yòu gānjìng yòu piàoliang le.","Bây giờ nó trở nên vừa sạch vừa đẹp rồi."],["服务员","是啊。它还特别可爱，一会儿在你脚边睡觉，一会儿在你身上爬。","Shì a. Tā hái tèbié kě'ài, yíhuìr zài nǐ jiǎobiān shuìjiào, yíhuìr zài nǐ shēnshang pá.","Đúng vậy. Nó còn đặc biệt đáng yêu, lúc thì ngủ bên chân bạn, lúc thì trèo lên người bạn."],["刘小雪","你们把它照顾得真好。","Nǐmen bǎ tā zhàogù de zhēn hǎo.","Các chị chăm sóc nó tốt thật."],["服务员","它就好像我们的孩子，我们照顾它，它也认得我们了。","Tā jiù hǎoxiàng wǒmen de háizi, wǒmen zhàogù tā, tā yě rènde wǒmen le.","Nó như con của chúng tôi vậy, chúng tôi chăm sóc nó, nó cũng nhận ra chúng tôi rồi."],["刘小雪","妈妈，我们家也养一只小猫吧。","Māma, wǒmen jiā yě yǎng yì zhī xiǎomāo ba.","Mẹ ơi, nhà mình cũng nuôi một con mèo con đi."],["王一雪","咱们没时间照顾，还是别养了，我周末带你们去北京动物园看动物吧。","Zánmen méi shíjiān zhàogù, háishi bié yǎng le, wǒ zhōumò dài nǐmen qù Běijīng Dòngwùyuán kàn dòngwù ba.","Chúng ta không có thời gian chăm sóc, vẫn là đừng nuôi, cuối tuần mẹ dẫn các con đi vườn thú Bắc Kinh xem động vật nhé."]]},{"label":"16-2 · Vì sao gọi là gấu trúc","context":"Vì sao gọi là gấu trúc","contextZh":"大熊猫的名字","sides":{"刘小明":"L","王一雪":"R","刘小雪":"R"},"lines":[["刘小明","妈妈，大熊猫这个名字很奇怪，它们跟猫有什么关系？","Māma, dàxióngmāo zhège míngzi hěn qíguài, tāmen gēn māo yǒu shénme guānxi?","Mẹ ơi, cái tên gấu trúc lớn này lạ quá, chúng có quan hệ gì với mèo ạ?"],["王一雪","这个问题问得好，它们跟猫没什么关系，其实应该叫大猫熊。","Zhège wèntí wèn de hǎo, tāmen gēn māo méi shénme guānxi, qíshí yīnggāi jiào dàmāoxióng.","Câu hỏi này hay đấy, chúng chẳng có quan hệ gì với mèo, thật ra nên gọi là gấu mèo lớn."],["刘小明","大熊猫为什么只吃竹子不吃肉？","Dàxióngmāo wèishénme zhǐ chī zhúzi bù chī ròu?","Tại sao gấu trúc chỉ ăn tre mà không ăn thịt ạ?"],["王一雪","它们跟人一样，也可以吃肉，但是对肉不感兴趣。","Tāmen gēn rén yíyàng, yě kěyǐ chī ròu, dànshì duì ròu bù gǎn xìngqù.","Chúng giống người vậy, cũng có thể ăn thịt, nhưng không hứng thú với thịt."],["刘小明","大熊猫为什么是中国的国宝？","Dàxióngmāo wèishénme shì Zhōngguó de guóbǎo?","Tại sao gấu trúc là quốc bảo của Trung Quốc ạ?"],["王一雪","全世界只有中国有野生大熊猫，中国是大熊猫的家。","Quán shìjiè zhǐyǒu Zhōngguó yǒu yěshēng dàxióngmāo, Zhōngguó shì dàxióngmāo de jiā.","Trên toàn thế giới chỉ có Trung Quốc có gấu trúc hoang dã, Trung Quốc là nhà của gấu trúc."],["刘小明","我听说有的熊猫出国了，他们去哪儿了？","Wǒ tīngshuō yǒude xióngmāo chūguó le, tāmen qù nǎr le?","Con nghe nói có gấu trúc ra nước ngoài, chúng đi đâu ạ?"],["王一雪","关于这个问题，我得慢慢给你讲。","Guānyú zhège wèntí, wǒ děi mànmàn gěi nǐ jiǎng.","Về vấn đề này, mẹ phải từ từ kể cho con nghe."],["刘小雪","弟弟，你真是“十万个为什么”。","Dìdi, nǐ zhēn shì “shí wàn ge wèishénme”.","Em trai, em đúng là \"mười vạn câu hỏi vì sao\"."]]},{"label":"16-3 · Ngắm gấu trúc","context":"Ngắm gấu trúc","contextZh":"看大熊猫","sides":{"刘小雪":"L","王一雪":"R","刘小明":"R"},"lines":[["刘小雪","这只大熊猫一会儿爬上去，一会儿跳下来，可爱极了！","Zhè zhī dàxióngmāo yíhuìr pá shàngqu, yíhuìr tiào xiàlai, kě'ài jí le!","Con gấu trúc này lúc thì trèo lên, lúc thì nhảy xuống, đáng yêu vô cùng!"],["王一雪","它好像还没吃饱，站起来张着嘴找吃的呢。","Tā hǎoxiàng hái méi chī bǎo, zhàn qǐlai zhāngzhe zuǐ zhǎo chī de ne.","Nó hình như còn chưa ăn no, đứng dậy há miệng tìm đồ ăn kìa."],["刘小雪","它身边那只熊猫半天没动，是不是在睡觉呢？","Tā shēnbiān nà zhī xióngmāo bàntiān méi dòng, shì bú shì zài shuìjiào ne?","Con gấu trúc bên cạnh nó nửa ngày không động đậy, có phải đang ngủ không?"],["王一雪","我看不见它的脸，可能是吧。一般来说，熊猫每天要睡很多次觉。","Wǒ kàn bú jiàn tā de liǎn, kěnéng shì ba. Yìbān lái shuō, xióngmāo měitiān yào shuì hěn duō cì jiào.","Mẹ không nhìn thấy mặt nó, có lẽ vậy. Nói chung, gấu trúc mỗi ngày phải ngủ nhiều lần."],["刘小明","对，除了睡觉以外，很多时间都在吃东西。","Duì, chúle shuìjiào yǐwài, hěn duō shíjiān dōu zài chī dōngxi.","Đúng ạ, ngoài ngủ ra, phần lớn thời gian đều ăn."],["刘小雪","大熊猫的生活真舒服啊！","Dàxióngmāo de shēnghuó zhēn shūfu a!","Cuộc sống của gấu trúc thoải mái thật!"],["刘小雪","妈妈，您帮我和这两只大熊猫照一张照片吧。","Māma, nín bāng wǒ hé zhè liǎng zhī dàxióngmāo zhào yì zhāng zhàopiàn ba.","Mẹ ơi, mẹ chụp cho con với hai con gấu trúc này một tấm ảnh nhé."]]},{"label":"16-4 · Đi sở thú Bắc Kinh","context":"王一雪 kể chuyện","contextZh":"王一雪讲述","sides":{"王一雪":"C"},"lines":[["王一雪","今天我带小雪和小明去动物园玩了。","Jīntiān wǒ dài Xiǎoxuě hé Xiǎomíng qù dòngwùyuán wán le.","Hôm nay tôi dẫn Tiểu Tuyết và Tiểu Minh đi vườn thú chơi."],["王一雪","北京动物园是中国很有名的动物园，里面有非常多的动物，当然，大人和孩子最喜爱的还是大熊猫。","Běijīng Dòngwùyuán shì Zhōngguó hěn yǒumíng de dòngwùyuán, lǐmiàn yǒu fēicháng duō de dòngwù, dāngrán, dàrén hé háizi zuì xǐ'ài de háishi dàxióngmāo.","Vườn thú Bắc Kinh là vườn thú rất nổi tiếng của Trung Quốc, bên trong có rất nhiều động vật, đương nhiên, người lớn và trẻ con yêu thích nhất vẫn là gấu trúc."],["王一雪","每天有很多游客去熊猫馆，他们带着相机去给可爱的大熊猫拍照。","Měitiān yǒu hěn duō yóukè qù xióngmāoguǎn, tāmen dàizhe xiàngjī qù gěi kě'ài de dàxióngmāo pāizhào.","Mỗi ngày có nhiều du khách đến nhà gấu trúc, họ mang máy ảnh đi chụp ảnh cho gấu trúc đáng yêu."],["王一雪","动物园早上七点半开门，晚上七点关门，冬天比夏天游客少，所以也比平时早关门一个小时。","Dòngwùyuán zǎoshang qī diǎn bàn kāimén, wǎnshang qī diǎn guānmén, dōngtiān bǐ xiàtiān yóukè shǎo, suǒyǐ yě bǐ píngshí zǎo guānmén yí ge xiǎoshí.","Vườn thú buổi sáng bảy giờ rưỡi mở cửa, buổi tối bảy giờ đóng cửa, mùa đông ít du khách hơn mùa hè nên cũng đóng cửa sớm hơn bình thường một tiếng."],["王一雪","如果第一次来北京旅游，跟家人一起去北京动物园是个不错的选择。","Rúguǒ dì-yī cì lái Běijīng lǚyóu, gēn jiārén yìqǐ qù Běijīng Dòngwùyuán shì ge búcuò de xuǎnzé.","Nếu lần đầu đến Bắc Kinh du lịch, cùng gia đình đi vườn thú Bắc Kinh là một lựa chọn không tồi."]]}],"17":[{"label":"17-1 · Trước văn phòng thầy Lý","context":"Trước văn phòng thầy Lý","contextZh":"在李老师办公室门口","sides":{"刘小雪":"L","同学":"R"},"lines":[["刘小雪","别再向前走了，李老师的办公室已经到了。","Bié zài xiàng qián zǒu le, Lǐ lǎoshī de bàngōngshì yǐjīng dào le.","Đừng đi tiếp nữa, văn phòng thầy Lý đã đến rồi."],["同学","你进去吧，我在楼梯那儿等你。我害怕见李老师。","Nǐ jìnqu ba, wǒ zài lóutī nàr děng nǐ. Wǒ hàipà jiàn Lǐ lǎoshī.","Bạn vào đi, tôi đợi bạn ở chỗ cầu thang. Tôi sợ gặp thầy Lý."],["刘小雪","怎么回事？","Zěnme huí shì?","Có chuyện gì vậy?"],["同学","最近我做错了好几件事，我怕李老师生气。","Zuìjìn wǒ zuò cuò le hǎo jǐ jiàn shì, wǒ pà Lǐ lǎoshī shēngqì.","Gần đây tôi làm sai mấy việc, tôi sợ thầy Lý giận."],["刘小雪","你想多了，做错事情是很常见的。","Nǐ xiǎng duō le, zuò cuò shìqing shì hěn chángjiàn de.","Bạn nghĩ nhiều rồi, làm sai việc là chuyện rất bình thường."],["同学","我把简单的事情做错了，李老师一定觉得我不认真。","Wǒ bǎ jiǎndān de shìqing zuò cuò le, Lǐ lǎoshī yídìng juéde wǒ bù rènzhēn.","Tôi làm sai cả những việc đơn giản, thầy Lý nhất định cho rằng tôi không nghiêm túc."],["刘小雪","有的人虽然很聪明，但是会在简单的事情中出错，因为他们认为事情简单，就不会认真去做了。","Yǒude rén suīrán hěn cōngming, dànshì huì zài jiǎndān de shìqing zhōng chūcuò, yīnwèi tāmen rènwéi shìqing jiǎndān, jiù bú huì rènzhēn qù zuò le.","Có người tuy rất thông minh nhưng cũng sẽ sai sót trong những việc đơn giản, vì họ cho rằng việc đơn giản nên sẽ không làm một cách nghiêm túc."],["同学","你说的就是我，以后我要多向认真的人学习。","Nǐ shuō de jiù shì wǒ, yǐhòu wǒ yào duō xiàng rènzhēn de rén xuéxí.","Bạn nói đúng là tôi. Sau này tôi phải học tập nhiều hơn ở những người nghiêm túc."]]},{"label":"17-2 · Gặp nhau ở thư viện","context":"Trong thư viện","contextZh":"在图书馆","sides":{"白家月":"L","陈天中":"R"},"lines":[["白家月","太阳从西边出来了？这几天怎么总是在图书馆看见你？","Tàiyáng cóng xībian chūlai le? Zhè jǐ tiān zěnme zǒngshì zài túshūguǎn kànjiàn nǐ?","Mặt trời mọc đằng tây à? Mấy hôm nay sao lúc nào cũng thấy bạn ở thư viện vậy?"],["陈天中","这有什么奇怪的？我是来学习的。","Zhè yǒu shénme qíguài de? Wǒ shì lái xuéxí de.","Có gì lạ đâu? Tôi đến để học mà."],["白家月","你怎么还来图书馆学习？同学们都在到处找工作呢。","Nǐ zěnme hái lái túshūguǎn xuéxí? Tóngxuémen dōu zài dàochù zhǎo gōngzuò ne.","Sao bạn còn đến thư viện học vậy? Các bạn học đều đang khắp nơi tìm việc đấy."],["陈天中","我不想现在就工作，还想继续学习，我爸妈也同意。可我还没想好学什么，所以来图书馆看看。","Wǒ bù xiǎng xiànzài jiù gōngzuò, hái xiǎng jìxù xuéxí, wǒ bàmā yě tóngyì. Kě wǒ hái méi xiǎnghǎo xué shénme, suǒyǐ lái túshūguǎn kànkan.","Tôi không muốn đi làm ngay, còn muốn tiếp tục học, bố mẹ tôi cũng đồng ý. Nhưng tôi còn chưa nghĩ ra học gì nên đến thư viện xem thử."],["白家月","你不是喜欢玩电脑吗？你可以去看看跟电脑有关系的书。","Nǐ bú shì xǐhuan wán diànnǎo ma? Nǐ kěyǐ qù kànkan gēn diànnǎo yǒu guānxi de shū.","Bạn không phải thích chơi máy tính sao? Bạn có thể đi xem sách liên quan đến máy tính."],["陈天中","你说得对，我记得那个屋子里有些跟电脑有关的书，我去找找。","Nǐ shuō de duì, wǒ jìde nàge wūzi li yǒuxiē gēn diànnǎo yǒuguān de shū, wǒ qù zhǎozhao.","Bạn nói đúng, tôi nhớ trong căn phòng kia có vài cuốn sách liên quan đến máy tính, tôi đi tìm thử."]]},{"label":"17-3 · Điện thoại hết pin","context":"Trong sân trường","contextZh":"在校园里","sides":{"李文":"L","陈天中":"R"},"lines":[["李文","天中，你的手机怎么关机了？","Tiānzhōng, nǐ de shǒujī zěnme guānjī le?","Thiên Trung, điện thoại của bạn sao tắt máy rồi?"],["陈天中","我的手机没电了。你找我有事吗？","Wǒ de shǒujī méi diàn le. Nǐ zhǎo wǒ yǒu shì ma?","Điện thoại tôi hết pin rồi. Bạn tìm tôi có việc à?"],["李文","前天我看见家月了，她告诉我你打算继续留学？","Qiántiān wǒ kànjiàn Jiāyuè le, tā gàosu wǒ nǐ dǎsuàn jìxù liúxué?","Hôm kia tôi gặp Gia Nguyệt, chị ấy nói với tôi bạn định tiếp tục du học à?"],["陈天中","是，可是我还没想好学什么，更没想好去哪个国家。","Shì, kěshì wǒ hái méi xiǎnghǎo xué shénme, gèng méi xiǎnghǎo qù nǎge guójiā.","Đúng vậy, nhưng tôi còn chưa nghĩ ra học gì, càng chưa nghĩ ra đi nước nào."],["李文","你可以去中国学中文啊。比如可以去北京、上海这样的大城市，那里有很多好大学，也有很多留学生。","Nǐ kěyǐ qù Zhōngguó xué Zhōngwén a. Bǐrú kěyǐ qù Běijīng, Shànghǎi zhèyàng de dà chéngshì, nàli yǒu hěn duō hǎo dàxué, yě yǒu hěn duō liúxuéshēng.","Bạn có thể sang Trung Quốc học tiếng Trung mà. Ví dụ có thể đến những thành phố lớn như Bắc Kinh, Thượng Hải, ở đó có nhiều trường đại học tốt, cũng có nhiều lưu học sinh."],["陈天中","好，那我上网查一查。","Hǎo, nà wǒ shàngwǎng chá yì chá.","Được, vậy tôi lên mạng tra thử."],["李文","我给你介绍几个有用的网站。","Wǒ gěi nǐ jièshào jǐ ge yǒuyòng de wǎngzhàn.","Tôi giới thiệu cho bạn vài trang web hữu ích."]]},{"label":"17-4 · Suy nghĩ về tương lai","context":"陈天中 kể chuyện","contextZh":"陈天中讲述","sides":{"陈天中":"C"},"lines":[["陈天中","大学生活马上就要结束了，我最近经常被问到一个问题——“你以后想做什么”，这个问题真不容易回答。","Dàxué shēnghuó mǎshàng jiù yào jiéshù le, wǒ zuìjìn jīngcháng bèi wèn dào yí ge wèntí — “Nǐ yǐhòu xiǎng zuò shénme”, zhège wèntí zhēn bù róngyì huídá.","Cuộc sống đại học sắp kết thúc rồi, gần đây tôi thường xuyên bị hỏi một câu — \"sau này bạn muốn làm gì\", câu hỏi này thật không dễ trả lời."],["陈天中","我也问了几个同学，大家选择的方向都不同。","Wǒ yě wèn le jǐ ge tóngxué, dàjiā xuǎnzé de fāngxiàng dōu bù tóng.","Tôi cũng hỏi vài bạn học, hướng lựa chọn của mọi người đều khác nhau."],["陈天中","有的想继续在学校学习，有的打算出国留学，还有的决定先找工作。","Yǒude xiǎng jìxù zài xuéxiào xuéxí, yǒude dǎsuàn chūguó liúxué, hái yǒude juédìng xiān zhǎo gōngzuò.","Có người muốn tiếp tục học ở trường, có người định ra nước ngoài du học, còn có người quyết định đi làm trước."],["陈天中","我认为只有想清楚自己真正喜欢什么，才能做出最合适的选择。","Wǒ rènwéi zhǐyǒu xiǎng qīngchu zìjǐ zhēnzhèng xǐhuan shénme, cái néng zuò chū zuì héshì de xuǎnzé.","Tôi cho rằng chỉ khi nghĩ rõ mình thực sự thích gì mới có thể đưa ra lựa chọn phù hợp nhất."],["陈天中","对我来说，想清楚“真正喜欢什么”是个难题。","Duì wǒ lái shuō, xiǎng qīngchu “zhēnzhèng xǐhuan shénme” shì ge nántí.","Đối với tôi, nghĩ rõ \"thực sự thích gì\" là một bài toán khó."]]}],"18":[{"label":"18-1 · Trước thềm Tết","context":"Trên máy bay","contextZh":"在飞机上","sides":{"白家月":"L","李文":"R"},"lines":[["白家月","我要在中国过年，真开心。","Wǒ yào zài Zhōngguó guònián, zhēn kāixīn.","Tôi sắp đón Tết ở Trung Quốc, vui thật."],["李文","第一次请外国朋友来家里过春节，我也很高兴。","Dì-yī cì qǐng wàiguó péngyou lái jiā li guò Chūnjié, wǒ yě hěn gāoxìng.","Lần đầu mời bạn nước ngoài đến nhà đón Tết, tôi cũng rất vui."],["白家月","你们怎样过节？","Nǐmen zěnyàng guòjié?","Các bạn đón Tết thế nào?"],["李文","春节是中国最重要的节日，我们一般会回家，跟家人一起过。","Chūnjié shì Zhōngguó zuì zhòngyào de jiérì, wǒmen yìbān huì huí jiā, gēn jiārén yìqǐ guò.","Tết là ngày lễ quan trọng nhất của Trung Quốc, chúng tôi thường về nhà đón cùng gia đình."],["白家月","那你跟家人会一起做什么？","Nà nǐ gēn jiārén huì yìqǐ zuò shénme?","Vậy bạn và gia đình sẽ cùng làm gì?"],["李文","我们家会一边包饺子，一边看春节联欢晚会，一直到十二点以后才睡觉。","Wǒmen jiā huì yìbiān bāo jiǎozi, yìbiān kàn Chūnjié Liánhuān Wǎnhuì, yìzhí dào shí'èr diǎn yǐhòu cái shuìjiào.","Nhà tôi sẽ vừa gói bánh chẻo vừa xem Gala Tết, mãi đến sau mười hai giờ mới ngủ."],["白家月","听起来很有意思。春节放几天假？","Tīng qǐlai hěn yǒuyìsi. Chūnjié fàng jǐ tiān jià?","Nghe thú vị thật. Tết được nghỉ mấy ngày?"],["李文","大概七八天。","Dàgài qī bā tiān.","Khoảng bảy tám ngày."]]},{"label":"18-2 · Đến nhà chúc Tết","context":"Ở nhà Lý Văn","contextZh":"在李文家","sides":{"白家月":"L","李叔叔":"R","张阿姨":"R"},"lines":[["白家月","张阿姨，李叔叔。过年好！这是我准备的礼物，请收下。","Zhāng āyí, Lǐ shūshu. Guònián hǎo! Zhè shì wǒ zhǔnbèi de lǐwù, qǐng shōuxià.","Cô Trương, chú Lý. Chúc mừng năm mới! Đây là quà tôi chuẩn bị, xin nhận lấy."],["李叔叔","谢谢家月，你太客气了！","Xièxie Jiāyuè, nǐ tài kèqi le!","Cảm ơn Gia Nguyệt, cháu khách sáo quá!"],["张阿姨","总听小文说起你，今天终于有机会见面了。","Zǒng tīng Xiǎowén shuōqǐ nǐ, jīntiān zhōngyú yǒu jīhuì jiànmiàn le.","Cô vẫn nghe Tiểu Văn nhắc đến cháu, hôm nay cuối cùng cũng có dịp gặp mặt."],["白家月","谢谢您和叔叔请我来家里做客。","Xièxie nín hé shūshu qǐng wǒ lái jiā li zuòkè.","Cảm ơn cô và chú đã mời cháu đến nhà chơi."],["李叔叔","桌子上有饮料，还有矿泉水，你想喝什么就自己拿。","Zhuōzi shàng yǒu yǐnliào, hái yǒu kuàngquánshuǐ, nǐ xiǎng hē shénme jiù zìjǐ ná.","Trên bàn có đồ uống, còn có nước khoáng, cháu muốn uống gì thì tự lấy."],["张阿姨","你先坐着看会儿电视，饺子很快就包好了。","Nǐ xiān zuòzhe kàn huìr diànshì, jiǎozi hěn kuài jiù bāo hǎo le.","Cháu ngồi xem tivi một lúc trước đi, bánh chẻo sắp gói xong rồi."],["白家月","我刚刚看视频学会了包饺子，我跟你们一起包吧。","Wǒ gānggāng kàn shìpín xuéhuì le bāo jiǎozi, wǒ gēn nǐmen yìqǐ bāo ba.","Tôi vừa xem video học được cách gói bánh chẻo, tôi gói cùng cô chú nhé."]]},{"label":"18-3 · Tấm ảnh cũ","context":"Tấm ảnh cũ","contextZh":"看照片","sides":{"白家月":"L","张阿姨":"R"},"lines":[["白家月","这张照片是李文出国前照的吗？","Zhè zhāng zhàopiàn shì Lǐ Wén chūguó qián zhào de ma?","Tấm ảnh này là Lý Văn chụp trước khi ra nước ngoài phải không ạ?"],["张阿姨","对，这是他从北京出发时，我们全家在机场照的。","Duì, zhè shì tā cóng Běijīng chūfā shí, wǒmen quánjiā zài jīchǎng zhào de.","Đúng vậy, đây là lúc nó từ Bắc Kinh lên đường, cả nhà chúng tôi chụp ở sân bay."],["白家月","那是三四年前吧？","Nà shì sān sì nián qián ba?","Đó là ba bốn năm trước phải không ạ?"],["张阿姨","是啊，时间过得真快，好像是不久前发生的一样。","Shì a, shíjiān guò de zhēn kuài, hǎoxiàng shì bùjiǔ qián fāshēng de yíyàng.","Đúng vậy, thời gian trôi nhanh thật, cứ như mới xảy ra không lâu vậy."],["白家月","您一定特别想李文吧？","Nín yídìng tèbié xiǎng Lǐ Wén ba?","Cô nhất định nhớ Lý Văn lắm phải không ạ?"],["张阿姨","他刚离开家时，我很不习惯，只要几天不跟他视频，就很想他。","Tā gāng líkāi jiā shí, wǒ hěn bù xíguàn, zhǐyào jǐ tiān bù gēn tā shìpín, jiù hěn xiǎng tā.","Lúc nó vừa rời nhà, cô rất không quen, chỉ cần vài ngày không gọi video với nó là cô rất nhớ nó."],["白家月","还有最后一个学期就要毕业了，他很快就会回来了。","Hái yǒu zuìhòu yí ge xuéqī jiù yào bìyè le, tā hěn kuài jiù huì huílai le.","Còn một học kỳ cuối nữa là tốt nghiệp rồi, nó sẽ sớm trở về thôi."]]},{"label":"18-4 · Kể về gia đình Lý Văn","context":"白家月 kể chuyện","contextZh":"白家月讲述","sides":{"白家月":"C"},"lines":[["白家月","这次来中国，我最高兴的是认识了李文的父母。","Zhè cì lái Zhōngguó, wǒ zuì gāoxìng de shì rènshi le Lǐ Wén de fùmǔ.","Lần này đến Trung Quốc, điều tôi vui nhất là quen biết bố mẹ của Lý Văn."],["白家月","他们给我看了李文出生时的照片，还给我讲了很多他过去的故事。","Tāmen gěi wǒ kàn le Lǐ Wén chūshēng shí de zhàopiàn, hái gěi wǒ jiǎng le hěn duō tā guòqù de gùshi.","Họ cho tôi xem ảnh lúc Lý Văn mới sinh, còn kể cho tôi nhiều câu chuyện trước đây của nó."],["白家月","李文高中的时候想学医，从那时起就努力学习。","Lǐ Wén gāozhōng de shíhou xiǎng xué yī, cóng nà shí qǐ jiù nǔlì xuéxí.","Hồi cấp ba Lý Văn muốn học y, từ lúc đó bắt đầu chăm chỉ học tập."],["白家月","高三的时候，因为成绩特别好，他得到了出国留学的机会。","Gāosān de shíhou, yīnwèi chéngjì tèbié hǎo, tā dédào le chūguó liúxué de jīhuì.","Năm lớp 12, vì thành tích đặc biệt tốt, nó đã có cơ hội ra nước ngoài du học."],["白家月","在他身上，我懂得了，只要一直坚持，就能完成自己的目标。","Zài tā shēnshang, wǒ dǒngde le, zhǐyào yìzhí jiānchí, jiù néng wánchéng zìjǐ de mùbiāo.","Ở nó, tôi hiểu ra rằng chỉ cần kiên trì mãi thì có thể hoàn thành mục tiêu của mình."],["白家月","我相信，他以后一定会发展得更好。","Wǒ xiāngxìn, tā yǐhòu yídìng huì fāzhǎn de gèng hǎo.","Tôi tin rằng sau này nó nhất định sẽ phát triển tốt hơn."]]}]};
